/// Optional scheduling plan for too few surviving groups. Byte weight bounds both task count and plan overhead;
/// a stable flat chunk supplies independent seeks, while one-shot streams and ordered reductions keep their path.
fn splitRowGroups(
    a: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    workers: usize,
) !?[]WorkItem {
    if (workers < 2) return null;
    var alive: usize = 0;
    var bytes: u64 = 0;
    var sample: ?WorkItem = null;
    for (work) |item| {
        const rg = &metas[item.file].row_groups.items[item.rg];
        const decision = plan.decide(rg, &metas[item.file]);
        if (decision == .skip or rg.num_rows == 0) continue;
        if (!args.inputs[item.file].rescannable() or rg.num_rows < 0 or rg.num_rows > std.math.maxInt(u32)) return null;
        if (!row_subgroups.supported(rg, &metas[item.file], item.columns.forRowGroup(decision))) return null;
        // The indexed filter path compacts survivors and can leave rejected page bodies unread. Keep that
        // contract rather than replacing it with ranges that would decode those pages again.
        if (decision == .filter) for (rg.columns.items, 0..) |col, ci| {
            const read = item.columns.forRowGroup(decision);
            if (ci < read.len and read[ci] and col.column_index_offset != null) return null;
        };
        alive += 1;
        if (sample == null) sample = item;
        bytes +|= subgroupBytes(rg, item.columns.forRowGroup(decision));
    }
    if (alive == 0 or alive >= workers) return null;
    const target = @min(workers *| 2, bytes / @max(1, args.min_bytes_per_worker));
    if (target <= alive) return null;
    if (plan.query.filter) |filter| {
        const item = sample.?;
        const meta = &metas[item.file];
        const rg = &meta.row_groups.items[item.rg];
        const source = args.inputs[item.file].plan_bytes orelse args.inputs[item.file].bytes;
        // Unknown fixed-width selectivity can leave little grouping behind a large decoded-byte estimate.
        // Costing only: a prefix never bounds rows or skips evaluation; probe refusal retains today's split.
        const share = subgroupPassShare(a, source, rg, meta, filter, args.min_bytes_per_worker, workers) catch 1;
        if (@as(f64, @floatFromInt(bytes)) * share <
            @as(f64, @floatFromInt(@max(1, args.min_bytes_per_worker))) * @as(f64, @floatFromInt(workers)))
            return null;
    }
    // A cold header walk must not serialize the chunk reads ahead of the worker pool. Both the walk and
    // mapped decoders reuse these file-backed pages; no extra input buffer is retained by this hint.
    for (work) |item| {
        const rg = &metas[item.file].row_groups.items[item.rg];
        const decision = plan.decide(rg, &metas[item.file]);
        if (decision == .skip or rg.num_rows == 0) continue;
        const source = args.inputs[item.file].plan_bytes orelse args.inputs[item.file].bytes;
        try row_subgroups.adviseGroup(source, rg, item.columns.forRowGroup(decision));
    }
    var split: std.ArrayList(WorkItem) = .empty;
    var changed = false;
    for (work, 0..) |item, wi| {
        var original = item;
        original.position = expr_agg.firstPosition(wi, 0);
        const rg = &metas[item.file].row_groups.items[item.rg];
        const decision = plan.decide(rg, &metas[item.file]);
        if (decision == .skip or rg.num_rows == 0) {
            try split.append(a, original);
            continue;
        }
        const read = item.columns.forRowGroup(decision);
        const weight = subgroupBytes(rg, read);
        const parts: usize = @intCast(@max(1, (target *| weight +| bytes - 1) / bytes));
        const source = args.inputs[item.file].plan_bytes orelse args.inputs[item.file].bytes;
        const group = if (try row_subgroups.Group.init(a, source, rg, &metas[item.file], read, parts)) |g| blk: {
            const ptr = try a.create(row_subgroups.Group);
            ptr.* = g;
            break :blk ptr;
        } else {
            try split.append(a, original);
            continue;
        };
        changed = true;
        for (group.ranges) |range| {
            var part = original;
            part.subgroup = .{ .group = group, .rows = range };
            part.position = expr_agg.firstPosition(wi, range.lo);
            try split.append(a, part);
        }
    }
    return if (changed) split.items else null;
}

fn subgroupProbeLeaves(
    a: std.mem.Allocator,
    f: filter_ast.Filter,
    rg: *const schema.RowGroup,
    meta: *const schema.FileMetaData,
    leaves: *std.ArrayList(filter_ast.Filter),
) !void {
    if (f == .and_filter) {
        if (f.and_filter.in_set != null or f.and_filter.null_member) return;
        for (f.and_filter.children) |child| try subgroupProbeLeaves(a, child, rg, meta, leaves);
        return;
    }
    switch (f) {
        .int32, .int64, .float, .double, .boolean => {},
        else => return,
    }
    if (filter_prune.pruneRowGroup(rg, f, meta) == .always_match or
        filter_prune.passFraction(f, rg, meta) != 1) return;
    try leaves.append(a, f);
}

fn subgroupPassShare(
    a: std.mem.Allocator,
    source: []const u8,
    rg: *const schema.RowGroup,
    meta: *const schema.FileMetaData,
    filter: filter_ast.Filter,
    min_bytes: u64,
    workers: usize,
) !f64 {
    var leaves: std.ArrayList(filter_ast.Filter) = .empty;
    try subgroupProbeLeaves(a, filter, rg, meta, &leaves);
    if (leaves.items.len == 0) return 1;
    const n: usize = @intCast(@min(@as(u64, @intCast(rg.num_rows)), @max(@import("hw.zig").cacheLineBytes(), min_bytes / @max(1, workers) / @sizeOf(i64))));
    const lookup = try a.alloc(?usize, rg.columns.items.len);
    @memset(lookup, null);
    var columns: std.ArrayList(filter_eval.Batch.Column) = .empty;
    for (leaves.items) |leaf| {
        const ci = filter_ast.leafColumn(leaf).?;
        if (ci >= lookup.len) return 1;
        if (lookup[ci] != null) continue;
        var reader = (try consumer.SliceReader.init(a, a, rg, meta, .{ .bytes = source, .byte_origin = 0 }, ci, .{ .encoded = false })) orelse return 1;
        defer reader.deinit();
        const col = try reader.next(a, n);
        lookup[ci] = columns.items.len;
        try columns.append(a, col);
    }
    var selected = try filter_selection.SelectionVector.init(a, n);
    defer selected.deinit();
    const batch: filter_eval.Batch = .{ .cols = columns.items, .num_rows = n };
    for (leaves.items) |leaf| try filter_eval.evaluate(leaf, &batch, &selected, lookup, a);
    return @as(f64, @floatFromInt(selected.count())) / @as(f64, @floatFromInt(n));
}

fn subgroupBytes(rg: *const schema.RowGroup, read: []const bool) u64 {
    var bytes: u64 = 0;
    for (rg.columns.items, 0..) |col, ci| {
        if (ci < read.len and read[ci]) if (col.meta_data) |cm| {
            bytes +|= @max(@as(u64, @intCast(@max(0, cm.total_uncompressed_size))), @as(u64, @intCast(@max(0, rg.num_rows))) *| 4);
        };
    }
    return bytes;
}

test "row subgroups decline sparse unknown predicates before walking payload pages" {
    const gpa = testing.allocator;
    var arena = std.heap.ArenaAllocator.init(gpa);
    defer arena.deinit();
    const a = arena.allocator();
    const fixture = try row_subgroups.testFixture(a);
    var predicate: std.ArrayList(u8) = .empty;
    for (0..36) |i| try predicate.print(a, "{s}k != {d}", .{ if (i == 0) "" else " AND ", i });
    var args: MultiAggArgs = .{
        .inputs = &.{.{ .name = "sparse", .bytes = fixture.bytes }},
        .metas = &.{fixture.meta},
        .aggregate = "count(*) AS c",
        .group_by = "k,s",
        .filter = predicate.items,
        .parallelism = 1,
        .min_bytes_per_worker = 2 << 10,
        .max_memory = 64 << 20,
        .dense = false,
        .ndv_policy = false,
        .plain_rules = false,
        .spill = false,
        .sketch_topk = null,
    };
    var want = try runMultiAggregate(gpa, a, args);
    defer want.deinit(gpa);
    args.parallelism = 8;
    row_subgroups.test_ranges.store(0, .monotonic);
    var got = try runMultiAggregate(gpa, a, args);
    defer got.deinit(gpa);
    try testing.expectEqual(@as(usize, 0), row_subgroups.test_ranges.load(.monotonic));
    try testing.expectEqual(want.rows_matched, got.rows_matched);
    try testing.expectEqualDeep(want.output.group_rows, got.output.group_rows);
}

test "row subgroups preserve grouped counts, first ordinals, ties and LIMIT OFFSET under pool failures" {
    const gpa = testing.allocator;
    var arena = std.heap.ArenaAllocator.init(gpa);
    defer arena.deinit();
    const a = arena.allocator();
    const fixture = try row_subgroups.testFixture(a);
    const inputs = [_]Input{.{ .name = "subgroups", .bytes = fixture.bytes }};
    var args: MultiAggArgs = .{
        .inputs = &inputs,
        .metas = (&fixture.meta)[0..1],
        .aggregate = "count(*) AS c",
        .group_by = "k,s",
        .filter = "v >= 10 AND v < 4000",
        .parallelism = 1,
        .min_bytes_per_worker = 1,
        .max_memory = 64 << 20,
        .dense = false,
        .ndv_policy = false,
        .shared_strings = false,
        .integer_records = false,
        .byte_records = false,
        .msd_records = false,
        .plain_rules = false,
        .spill = false,
        .sketch_topk = null,
        .result_order = .{ .keys = &.{.{ .column = 2, .descending = true }}, .limit = 13, .offset = 37 },
    };
    var want = try runMultiAggregate(gpa, a, args);
    defer want.deinit(gpa);
    try want.output.applyResultOrder(gpa, args.result_order);
    args.parallelism = 8;
    const explanation = try explainAggregate(gpa, a, args);
    try testing.expect(explanation.workers > 1);
    try testing.expect(explanation.work_items > fixture.meta.row_groups.items.len);
    for ([_]?usize{ null, 0, 1 }) |fail_after| {
        if (fail_after) |k| spawn_util.injectFailureAfter(k);
        defer spawn_util.resetFailure();
        args.parallelism = 8;
        row_subgroups.test_ranges.store(0, .monotonic);
        var got = try runMultiAggregate(gpa, a, args);
        defer got.deinit(gpa);
        try testing.expect(row_subgroups.test_ranges.load(.monotonic) > 1);
        try got.output.applyResultOrder(gpa, args.result_order);
        try testing.expectEqual(want.rows_in, got.rows_in);
        try testing.expectEqual(want.rows_scanned, got.rows_scanned);
        try testing.expectEqual(want.rows_matched, got.rows_matched);
        try testing.expectEqual(want.row_groups_in, got.row_groups_in);
        try testing.expectEqualDeep(want.output.group_rows, got.output.group_rows);
    }
    // The producer poisons its chunks at done(): an early release corrupts another range's next page.
    var window: ReleasingScanWindow = .{ .bytes = try a.dupe(u8, fixture.bytes), .meta = &fixture.meta };
    const streamed = [_]Input{window.input(fixture.bytes)};
    args.inputs = &streamed;
    row_subgroups.test_ranges.store(0, .monotonic);
    var streamed_result = try runMultiAggregate(gpa, a, args);
    defer streamed_result.deinit(gpa);
    try streamed_result.output.applyResultOrder(gpa, args.result_order);
    const ranges = row_subgroups.test_ranges.load(.monotonic);
    try testing.expect(ranges > 1);
    try testing.expectEqual(ranges, window.waits.load(.monotonic));
    try testing.expectEqual(@as(usize, 1), window.releases.load(.monotonic));
    try testing.expectEqualDeep(want.output.group_rows, streamed_result.output.group_rows);
    args.inputs = &inputs;
    const indexed = try a.dupe(schema.RowGroup, fixture.meta.row_groups.items);
    indexed[0].columns.items = try a.dupe(schema.ColumnChunk, indexed[0].columns.items);
    indexed[0].columns.items[2].column_index_offset = 0;
    var indexed_meta = fixture.meta;
    indexed_meta.row_groups.items = indexed;
    args.metas = (&indexed_meta)[0..1];
    const indexed_plan = try explainAggregate(gpa, a, args);
    try testing.expectEqual(@as(usize, 1), indexed_plan.work_items);
    args.metas = (&fixture.meta)[0..1];
    const profiler = try profile.Profiler.create(gpa, .{ .sample_interval_ns = 0 }, .{});
    defer profiler.destroy();
    args.profiler = profiler;
    var profiled = try runMultiAggregate(gpa, a, args);
    defer profiled.deinit(gpa);
    profiler.finish();
    var scans: usize = 0;
    var range_plans: usize = 0;
    var thread = profiler.head.load(.acquire);
    while (thread) |t| : (thread = t.next) {
        var events: profile.EventIterator = .{ .t = t };
        while (events.next()) |batch| for (batch) |event| {
            scans += @intFromBool(event.kind == .plan);
            range_plans += @intFromBool(event.kind == .plan_ranges);
        };
    }
    try testing.expectEqual(@as(usize, 1), scans);
    try testing.expectEqual(@as(usize, 1), range_plans);
}

/// Cost quote only: stream pages are not available yet. Bound one probe column from its chunk footprint and
/// a 64-row window, never all projected columns or workers at once. False size metadata can only limit evidence.
fn streamProbeBytes(inputs: []const Input, metas: []const schema.FileMetaData, plan: *const agg_plan.Plan) usize {
    var largest: usize = 0;
    for (inputs, metas) |input, *meta| {
        if (input.rescannable()) continue;
        for (meta.row_groups.items) |*rg| {
            const decision = plan.decide(rg, meta);
            if (decision == .skip) continue;
            const read = plan.columns.forRowGroup(decision);
            for (read, 0..) |needed, ci| {
                if (!needed) continue;
                var unit: usize = std.heap.pageSize() * 4 +| read.len *| 16;
                if (rg.columns.items[ci].meta_data) |cm| {
                    const raw = std.math.cast(usize, @max(0, cm.total_uncompressed_size)) orelse
                        std.math.maxInt(usize);
                    const n = std.math.cast(usize, @max(0, cm.num_values)) orelse std.math.maxInt(usize);
                    // Byte windows may copy the same long dictionary string 64 times. Numeric pages retain
                    // decompression/dictionary storage and can expand levels even when values are tightly coded.
                    const copies: usize = switch (cm.type) {
                        .BYTE_ARRAY, .FIXED_LEN_BYTE_ARRAY, .INT96 => 64 + 12,
                        else => 4,
                    };
                    unit +|= raw *| copies +| n *| 4 +| 64 * 32;
                }
                largest = @max(largest, unit);
            }
        }
    }
    return largest;
}

const WinnerCharge = expr_agg.WinnerCharge;

/// Complete dense COUNT or signed SUM ranks need no losing groups when no later predicate or expression reads them.
fn denseLimit(args: MultiAggArgs, calls: []const expr_agg.AggCall, outputs: ?[]const BoundOutputColumn) ?usize {
    const ai = if (agg_dense.countOnly(calls)) 0 else agg_dense.sumCall(calls) orelse return null;
    const outs = outputs orelse return null;
    const order = args.result_order;
    const limit = order.limit orelse return null;
    if (limit == 0 or order.having != null or order.hidden.len != 0 or order.keys.len != 1 or
        !order.keys[0].descending or order.keys[0].column >= outs.len) return null;
    for (outs) |out| if (out.derived != null) return null;
    const source = outs[order.keys[0].column].source;
    if (source != .agg or source.agg != ai) return null;
    return std.math.cast(usize, std.math.add(u64, order.offset, limit) catch return null);
}

/// Hot membership is sampled; each hot lane is then counted completely and every other row contributes to a
/// saturating cold bound. The exact residual includes equality at the cut, preserving all secondary ordering.
fn hotCertificate(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    workers: []Worker,
    cursor: *std.atomic.Value(usize),
    tables: []expr_agg.GroupTable,
    calls: []const expr_agg.AggCall,
    order: expr_ast.ResultOrder,
    cfg: SketchTopK,
) !bool {
    const cert = @import("count_certificate.zig");
    if (cfg.hot_outcome) |outcome| outcome.* = .declined;
    if (!cfg.hot) return false;
    const keys = workers[0].group_by_keys orelse return false;
    if (keys.len == 0 or keys.len > 2 or calls.len != 1 or calls[0].func != .count or calls[0].arg != null or
        calls[0].where != null or calls[0].offset != 0 or calls[0].state or
        tables[0].fixed_stride != keys.len * 9) return false;
    for (keys) |key| {
        if (key != .col_ref or key.col_ref.expr_type != .i64 or key.col_ref.unsigned_64) return false;
        if (key.col_ref.physical_type != .INT32 and key.col_ref.physical_type != .INT64) return false;
    }
    const h: usize = @intCast(order.offset +| order.limit.?);
    var unlimited: core_memory.SharedBudget = .{ .limit = std.math.maxInt(usize) };
    var charge: core_memory.Charged = .{ .child = gpa, .budget = tables[0].shared orelse &unlimited };
    const a = charge.allocator();
    const sources = a.alloc(cert.Source, workers[0].work.len) catch return false;
    defer a.free(sources);
    for (workers[0].work, sources) |item, *source| source.* = .{
        .rg = &workers[0].metas[item.file].row_groups.items[item.rg],
        .meta = &workers[0].metas[item.file],
        .src = .{ .bytes = workers[0].inputs[item.file].bytes, .byte_origin = 0 },
    };
    // A failed optional sample is never the query's error; the complete scan establishes canonical failures.
    var sample = cert.sample(
        a,
        sources,
        keys[0].col_ref.col_idx,
        if (keys.len == 2) keys[1].col_ref.col_idx else null,
        h,
        workers.len,
        workers[0].decode_options,
    ) catch {
        consumer.setDecodeFailure(null);
        return false;
    };
    defer sample.deinit(a);
    const cell_capacity = @max(16, @import("hw.zig").l2BytesPerWorkerOr(640 << 10) / (2 * @sizeOf(u32)));
    const bits = @min(cfg.cell_bits, std.math.log2_int(usize, cell_capacity));
    const n_cells = @as(usize, 1) << @intCast(bits);
    var plan = (cert.hotPlan(a, sample, keys.len == 2, h, n_cells) catch return false) orelse return false;
    defer plan.deinit(a);
    sample.deinit(a);
    const hot = a.alloc(cert.Hot, workers.len) catch return false;
    defer a.free(hot);
    var made: usize = 0;
    defer for (hot[0..made]) |local| local.deinit(a);
    for (hot) |*local| {
        local.* = cert.Hot.init(a, &plan) catch return false;
        made += 1;
    }
    const sketches = a.alloc(expr_agg.CountSketch, workers.len) catch return false;
    defer a.free(sketches);
    var cells_made: usize = 0;
    defer for (sketches[0..cells_made]) |s| a.free(s.cells);
    for (sketches, hot) |*s, *local| {
        s.* = .{
            .cells = a.alloc(u32, n_cells) catch return false,
            .shift = @intCast(@as(u7, 64) - bits),
            .hot = local,
        };
        @memset(s.cells, 0);
        cells_made += 1;
    }
    const totals = a.alloc(u64, plan.lanes()) catch return false;
    defer a.free(totals);
    @memset(totals, 0);
    const ranked = a.alloc(u64, plan.lanes()) catch return false;
    defer a.free(ranked);
    const saved = try arena.dupe(Worker, workers);
    var accepted = false;
    defer if (!accepted) restoreCounts(workers, saved);
    for (tables, sketches) |*t, *s| t.sketch = s;
    defer for (tables) |*t| {
        t.sketch = null;
    };
    const t0 = nowMonoNs();
    try runPhase(workers, cursor);
    for (hot) |local| {
        if (local.overflow) return false;
        for (totals, local.counts) |*total, count| total.* += count;
        for (hot[0].first, local.first) |*first, ordinal| first.* = @min(first.*, ordinal);
    }
    @memcpy(ranked, totals);
    std.mem.sortUnstable(u64, ranked, {}, std.sort.desc(u64));
    const cut = ranked[h - 1];
    if (cut == 0) return false;
    const cells = sketches[0].cells;
    for (sketches[1..]) |s| for (cells, s.cells) |*cell, count| {
        cell.* +|= count;
    };
    var residual: u64 = 0;
    for (cells) |cell| if (cell == std.math.maxInt(u32)) {
        // A saturated cell is infinity, including when an exact hot score exceeds u32.
        return false;
    } else if (cell >= cut) {
        residual +|= cell;
    };
    if (cfg.trace) std.debug.print("certificate: hot={d} width={d} cut={d} residual_bound={d} count_ms={d}\n", .{
        plan.keys.len, plan.width, cut, residual, @divTrunc(nowMonoNs() - t0, 1_000_000),
    });
    // The residual counts survivors, so compare it with this pass's selected rows, excluding earlier phases.
    var selected_rows: u64 = 0;
    for (workers, saved) |w, before| selected_rows +|= @intCast(w.rows_matched - before.rows_matched);
    if (residual >= selected_rows / 2 or !cfg.certify) return false;
    if (residual > 0) {
        const admit = try a.alloc(u64, (n_cells + 63) / 64);
        defer a.free(admit);
        @memset(admit, 0);
        for (cells, 0..) |cell, i| if (cell >= cut) {
            admit[i / 64] |= @as(u64, 1) << @intCast(i % 64);
        };
        for (sketches) |*s| s.admit = admit;
        restoreCounts(workers, saved);
        try runPhase(workers, cursor);
    }
    // Each hot key is complete in one lane, even when its cold hash cell was also admitted. The residual drops
    // hot rows; materializing the complete lane once cannot double-count them.
    for (tables) |*t| t.sketch = null;
    for (totals, hot[0].first, 0..) |total, first, id| if (total != 0) {
        var image: [18]u8 = undefined;
        const g = try tables[0].getOrInsert(plan.image(id, &image), calls, first);
        tables[0].writeAcc(g, 0, 1, .{ .count = total });
    };
    if (cfg.outcome) |o| o.* = .certified;
    if (cfg.hot_outcome) |o| o.* = if (residual == 0) .certified else .residual;
    accepted = true;
    return true;
}

/// A COUNT-descending cut of `k = offset + limit` groups, grouping only the keys that can make it. The count pass
/// gives no key a group: each row adds one to its key's hash cell. The cells, summed over workers, bound every key's
/// total. The admit pass groups, exactly and with first appearance, every key of the `T` fullest cells, and drops the
/// rest. A dropped key totals at most the fullest cell not admitted, `bound`; when `bound` is below the k-th largest
/// admitted total, every group the cut keeps, ties at the cut included, is admitted, and the tables answer exactly.
/// Otherwise (or when the cells are too even for that to happen) the tables start over and the scan runs as usual.
fn certifiedTopK(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    workers: []Worker,
    cursor: *std.atomic.Value(usize),
    tables: []expr_agg.GroupTable,
    calls: []const expr_agg.AggCall,
    order: expr_ast.ResultOrder,
    a_idx: usize,
    cfg: SketchTopK,
    decision: AggregateDispatch,
) !void {
    if (!decision.distinct_census) {
        const hot = hotCertificate(gpa, arena, workers, cursor, tables, calls, order, cfg) catch |e| {
            if (e != error.ExceededMemoryBudget) return e;
            // The hot trial has released its lanes/cells and restored scan counts before replay owns the tables.
            try clearWorkerErrors(workers, error.ExceededMemoryBudget);
            clearTables(gpa, tables);
            if (cfg.outcome) |o| o.* = .fell_back;
            try runPhase(workers, cursor);
            return;
        };
        if (hot) return;
    }
    const k: usize = @intCast(order.offset +| order.limit.?);
    const n_cells = @as(usize, 1) << cfg.cell_bits;
    const sketches = try arena.alloc(expr_agg.CountSketch, workers.len);
    var made: usize = 0;
    defer for (sketches[0..made]) |s| gpa.free(s.cells);
    for (sketches) |*s| {
        s.* = .{
            .cells = try gpa.alloc(u32, n_cells),
            .shift = @intCast(@as(u7, 64) - cfg.cell_bits),
            .whole_keys = decision.distinct_census,
        };
        made += 1;
        @memset(s.cells, 0);
    }
    for (tables, sketches) |*t, *s| t.sketch = s;
    defer for (tables) |*t| {
        t.sketch = null;
    };
    const admit_n = @max(k * cfg.admit_per_row, @min(64, n_cells / 16));
    // A census (`identityBoundPlan`) rides along when it fits and the keys look unique (`keysLookUnique`), so
    // cells too even to bound anything need no second count pass. It fills the cells too, and stops early wherever a
    // worker's own cells already separate the cut, as the cells will then do without it.
    var dropped: std.atomic.Value(bool) = .init(false);
    // A census riding the count pass drops on the merged cells of every worker with `check_after` rows to judge.
    // Each worker judges at its share of what one worker's cells once judged alone, so the merged cells hold as many
    // rows, drawn from every worker's slice rather than one.
    var merged: expr_agg.Census.MergedCells = .{ .slots = &.{}, .quorum = 0 };
    var merged_check: u64 = cfg.census_check_rows;
    if (decision.census_allowed and decision.census_fused and !decision.distinct_census) {
        var rows: u64 = 0;
        for (workers[0].work) |item| if (item.agg_start == 0) {
            rows +|= @intCast(@max(0, workers[0].metas[item.file].row_groups.items[item.rg].num_rows));
        };
        merged.quorum = workers.len;
        merged_check = @max(1, cfg.census_check_rows / workers.len);
        // Workers that cannot all reach their check never complete the quorum: judge on fewer.
        if (rows / merged_check < workers.len) merged.quorum = @intCast(rows / merged_check);
        merged.slots = try arena.alloc([]u32, workers.len);
        for (merged.slots) |*slot| {
            slot.* = try arena.alloc(u32, n_cells);
            @memset(slot.*, 0);
        }
    }
    const censuses: []expr_agg.Census = if (decision.census_allowed) blk: {
        const item_rows = try arena.alloc(u64, workers[0].work.len);
        @memset(item_rows, 0);
        const cs = try arena.alloc(expr_agg.Census, workers.len);
        for (cs, 0..) |*c, wi| c.* = .{
            .worker = wi,
            .gpa = gpa,
            .item_rows = item_rows,
            .dropped = &dropped,
            .merged = if (merged.slots.len != 0) &merged else null,
            .cut_k = k,
            .admit_n = admit_n,
            .distinct = decision.distinct_census,
            .check_after = if (decision.distinct_census)
                @min(cfg.census_check_rows, expr_agg.Census.distinct_check_rows)
            else
                merged_check,
            .fp_mask = censusMask(cfg),
        };
        break :blk cs;
    } else &.{};
    defer for (censuses) |*c| c.deinit();
    const fused = decision.census_fused;
    if (fused) for (sketches, censuses) |*s, *c| {
        s.census = c;
    };
    defer for (sketches) |*s| {
        s.census = null;
    };
    const saved = try arena.dupe(Worker, workers);
    const t0 = nowMonoNs();
    // A count(DISTINCT) census that would admit most rows is abandoned as soon as one worker sees it.
    if (decision.distinct_census) for (workers) |*w| {
        w.stop = &dropped;
    };
    runPhase(workers, cursor) catch |e| {
        if (e != error.CensusAbandoned) return e;
        try clearWorkerErrors(workers, error.CensusAbandoned);
    };
    for (workers) |*w| w.stop = null;
    var t1 = nowMonoNs();
    for (sketches) |*s| s.census = null;
    if (decision.distinct_census) {
        const abandoned = dropped.load(.monotonic);
        if (cfg.trace) std.debug.print("census distinct: count_ms={d} abandoned={}\n", .{
            @divTrunc(t1 - t0, 1_000_000), abandoned,
        });
        if (!abandoned) {
            var bound_plan = try identityBoundPlan(
                gpa,
                arena,
                workers,
                tables,
                censuses,
                calls,
                order,
                a_idx,
                cfg,
                t1 - t0,
            );
            for (censuses) |*c| c.deinit();
            if (bound_plan) |*plan| {
                defer plan.deinit(gpa);
                if (try certifiedResidual(
                    gpa,
                    arena,
                    workers,
                    cursor,
                    tables,
                    sketches,
                    censuses,
                    calls,
                    order,
                    a_idx,
                    cfg,
                    plan,
                ))
                    return;
            }
        }
        if (abandoned) if (cfg.outcome) |o| {
            o.* = .bailed;
        };
        for (censuses) |*c| c.deinit();
        for (tables) |*t| t.sketch = null;
        restoreCounts(workers, saved);
        try runPhase(workers, cursor);
        return;
    }

    const sum = sketches[0].cells;
    for (sketches[1..]) |s| for (sum, s.cells) |*a, b| {
        a.* +|= b;
    };
    const ranked = try gpa.dupe(u32, sum);
    defer gpa.free(ranked);
    std.mem.sortUnstable(u32, ranked, {}, std.sort.desc(u32));
    // Admitting every cell fuller than `bound` keeps ties at it out, so `bound` is the fullest cell not admitted.
    const bound = ranked[admit_n];
    const viable = expr_agg.cellsSeparate(ranked, k, admit_n);
    if (cfg.trace) std.debug.print("sketch: count_ms={d} kth_cell={d} bound={d} viable={} census_dropped={}\n", .{
        @divTrunc(t1 - t0, 1_000_000), ranked[k - 1], bound, viable, dropped.load(.monotonic),
    });
    if (!viable) if (cfg.outcome) |o| {
        o.* = .bailed;
    };
    const census_try = !viable and censuses.len > 0 and
        (!decision.census_cell_repeat_gate or censusCellBet(sum, calls.len > 1));
    if (cfg.trace and !viable and decision.census_cell_repeat_gate)
        std.debug.print("certificate: hash_identity_try={}\n", .{census_try});
    var bound_plan: ?CutBoundPlan = null;
    if (census_try) {
        if (!fused or dropped.load(.monotonic)) {
            // The census did not ride along, or a worker's cells misjudged the whole: count again, census only.
            for (censuses) |*c| {
                c.deinit();
                c.* = .{ .gpa = gpa, .item_rows = c.item_rows, .fp_mask = censusMask(cfg) };
            }
            @memset(censuses[0].item_rows, 0);
            for (sketches, censuses) |*s, *c| s.census = c;
            restoreCounts(workers, saved);
            const t2 = nowMonoNs();
            try runPhase(workers, cursor);
            t1 = nowMonoNs();
            for (sketches) |*s| s.census = null;
            if (cfg.trace) std.debug.print("census: recount_ms={d}\n", .{@divTrunc(t1 - t2, 1_000_000)});
        }
        bound_plan = try identityBoundPlan(gpa, arena, workers, tables, censuses, calls, order, a_idx, cfg, t1 - t0);
    }
    for (censuses) |*c| c.deinit();
    if (viable) {
        const admit = try gpa.alloc(u64, (n_cells + 63) / 64);
        @memset(admit, 0);
        for (sum, 0..) |count, i| if (count > bound) {
            admit[i / 64] |= @as(u64, 1) << @intCast(i % 64);
        };
        bound_plan = .{ .bound = if (bound == std.math.maxInt(u32)) std.math.maxInt(u64) else bound, .cells = admit };
    }
    if (bound_plan) |*plan| {
        defer plan.deinit(gpa);
        if (try certifiedResidual(
            gpa,
            arena,
            workers,
            cursor,
            tables,
            sketches,
            censuses,
            calls,
            order,
            a_idx,
            cfg,
            plan,
        ))
            return;
    }
    for (tables) |*t| t.sketch = null;
    restoreCounts(workers, saved);
    try runPhase(workers, cursor);
}

/// Whether a census after a sketch bail is worth recounting for. Its repeats no longer bound its use (the census keeps
/// each partition's most frequent and certifies against the rest), so the only reason left not to is a selective
/// narrow COUNT, which merges directly more cheaply than recounting every filter column.
fn censusCellBet(cells: []const u32, payload: bool) bool {
    if (payload) return true;
    var rows: f64 = 0;
    for (cells) |c| rows += @floatFromInt(c);
    return rows > 1 << 20;
}

/// Empties `tables` for a pass that starts over, keeping their budget, key width and sketch (all three).
fn clearTables(gpa: std.mem.Allocator, tables: []expr_agg.GroupTable) void {
    for (tables) |*t| {
        const shared = t.shared;
        const stride = t.fixed_stride;
        const sketch = t.sketch;
        const layout = t.compact;
        t.deinit();
        t.* = expr_agg.GroupTable.init(gpa, 0);
        t.shared = shared;
        t.fixed_stride = stride;
        t.sketch = sketch;
        t.compact = layout;
        t.compact.words = .empty;
    }
}

fn censusMask(cfg: SketchTopK) u64 {
    return (@as(u64, 1) << @min(cfg.census_fp_bits, 32)) - 1;
}

/// A complete identity class seen more than once. Its row count is an upper bound, never key equality.
const Repeat = struct { fp: u64, count: u64 };

/// Folds the census partitions claimed from `cursor`: each partition's fingerprints from every worker, sorted, give
/// the fingerprints seen more than once. Every copy of a fingerprint lands in one partition, so its count there is
/// complete. A partition keeps at most `keep` of them, its most frequent, and records in `omitted` the largest count
/// it dropped: every fingerprint not kept has a count at most that, a bound the cut must clear. Stops once all tasks
/// together have found more than `cap`.
const CensusTask = struct {
    gpa: std.mem.Allocator,
    censuses: []expr_agg.Census,
    cursor: *std.atomic.Value(usize),
    found: *std.atomic.Value(usize),
    cap: usize,
    keep: usize = std.math.maxInt(usize),
    /// The largest count of a repeated fingerprint some partition dropped; 1 when none was (a single row each).
    omitted: u64 = 1,
    out: std.ArrayList(Repeat) = .empty,
    sorted: std.ArrayList(u32) = .empty,
    table: std.ArrayList(u64) = .empty,
    /// One partition's repeats, before the most frequent `keep` are emitted.
    pending: std.ArrayList(Pending) = .empty,
    err: ?anyerror = null,

    /// A repeated fingerprint whose rows are `sorted.items[lo..hi]`.
    const Pending = struct { fp: u64, count: u64 };

    fn run(t: *CensusTask) void {
        t.fold() catch |e| {
            t.err = e;
        };
    }

    fn fold(t: *CensusTask) !void {
        while (t.found.load(.monotonic) <= t.cap) {
            const p = t.cursor.fetchAdd(1, .monotonic);
            if (p >= expr_agg.Census.N_PARTS) return;
            // Every worker's entries for the partition, bucketed by the top byte straight from the chunks, so each
            // bucket is small enough to stay in cache.
            var starts: [257]usize = @splat(0);
            for (t.censuses) |*c| {
                for (c.full[p].items) |chunk| for (chunk) |e| {
                    starts[(e >> 24) + 1] += 1;
                };
                if (c.open[p]) |chunk| for (chunk[0..c.fill[p]]) |e| {
                    starts[(e >> 24) + 1] += 1;
                };
            }
            for (1..257) |b| starts[b] += starts[b - 1];
            try t.sorted.resize(t.gpa, starts[256]);
            const entries = t.sorted.items;
            var next = starts;
            for (t.censuses) |*c| {
                for (c.full[p].items) |chunk| scatter(entries, &next, chunk);
                if (c.open[p]) |chunk| scatter(entries, &next, chunk[0..c.fill[p]]);
                c.freeChunks(&c.full[p]);
                c.open[p] = null;
                c.fill[p] = 0;
            }
            var found: usize = 0;
            t.pending.clearRetainingCapacity();
            for (0..256) |b| found += try t.repeatsIn(p, entries, starts[b], starts[b + 1]);
            if (t.pending.items.len > 0) found += try t.emitMostFrequent(p);
            _ = t.found.fetchAdd(found, .monotonic);
        }
    }

    /// Emit the partition's `keep` most frequent pending repeats, recording the largest count left out.
    fn emitMostFrequent(t: *CensusTask, p: usize) !usize {
        const all = t.pending.items;
        // Most frequent first, ties by fingerprint so the choice does not depend on scheduling.
        std.mem.sortUnstable(Pending, all, {}, struct {
            fn more(_: void, a: Pending, b: Pending) bool {
                return a.count > b.count or (a.count == b.count and a.fp < b.fp);
            }
        }.more);
        const kept = all[0..@min(all.len, t.keep)];
        if (kept.len < all.len) t.omitted = @max(t.omitted, all[kept.len].count);
        for (kept) |r| {
            try t.emit(p, r.fp, r.count);
        }
        return kept.len;
    }

    fn scatter(entries: []u32, next: *[257]usize, chunk: []const u32) void {
        for (chunk) |e| {
            const b: usize = @intCast(e >> 24);
            entries[next[b]] = e;
            next[b] += 1;
        }
    }

    /// The fingerprints of `entries[lo..hi]` seen more than once. A table of its fingerprints finds them in one pass;
    /// a bucket with more than a few is sorted instead, so their rows come together and wait in `pending`. Returns
    /// how many it emitted itself.
    fn repeatsIn(t: *CensusTask, p: usize, entries: []u32, lo: usize, hi: usize) !usize {
        const bucket = entries[lo..hi];
        if (bucket.len < 2) return 0;
        const size = std.math.ceilPowerOfTwoAssert(usize, bucket.len * 2);
        try t.table.resize(t.gpa, size);
        const table = t.table.items;
        @memset(table, 0);
        const used: u64 = 1 << 63;
        const seen_twice: u64 = 1 << 62;
        var reps: [8]u64 = undefined;
        var n_reps: usize = 0;
        for (bucket) |e| {
            const fp: u64 = e;
            var i: usize = @intCast(fp & (size - 1));
            while (true) : (i = (i + 1) & (size - 1)) {
                const slot = table[i];
                if (slot == 0) {
                    table[i] = fp | used;
                    break;
                }
                if (slot & ~seen_twice != fp | used) continue;
                if (slot & seen_twice == 0) {
                    if (n_reps == reps.len) return t.repeatsSorted(entries, lo, hi);
                    table[i] |= seen_twice;
                    reps[n_reps] = fp;
                    n_reps += 1;
                }
                break;
            }
        }
        for (reps[0..n_reps]) |fp| {
            var count: u64 = 0;
            for (bucket) |e| if (e == fp) {
                count += 1;
            };
            try t.emit(p, fp, count);
        }
        return n_reps;
    }

    /// The repeats of a bucket with many, sorted so each one's rows are a run; they wait in `pending` for the
    /// partition's most frequent to be chosen.
    fn repeatsSorted(t: *CensusTask, entries: []u32, lo: usize, hi: usize) !usize {
        std.mem.sortUnstable(u32, entries[lo..hi], {}, std.sort.asc(u32));
        var i = lo;
        while (i < hi) {
            const fp = entries[i];
            var j = i + 1;
            while (j < hi and entries[j] == fp) j += 1;
            if (j - i > 1) try t.pending.append(t.gpa, .{ .fp = fp, .count = j - i });
            i = j;
        }
        return 0;
    }

    /// Emit one complete class. The exact residual scans every work item and filters by this identity.
    fn emit(t: *CensusTask, p: usize, fp: u64, count: u64) !void {
        try t.out.append(t.gpa, .{ .fp = (@as(u64, p) << 40) | fp, .count = count });
    }
};

/// A census's repeated fingerprints from every partition (`CensusTask`), most frequent first, ties by fingerprint, and
/// the largest count a partition dropped (1 when none was).
const CensusRepeats = struct {
    tasks: []CensusTask,
    repeats: std.ArrayList(Repeat) = .empty,
    omitted: u64 = 1,

    fn deinit(self: *CensusRepeats, gpa: std.mem.Allocator) void {
        self.repeats.deinit(gpa);
        for (self.tasks) |*t| {
            t.out.deinit(gpa);
            t.sorted.deinit(gpa);
            t.table.deinit(gpa);
            t.pending.deinit(gpa);
        }
    }
};

/// Folds every census partition, each keeping its `keep` most frequent repeats. Null when more than `cap` repeat.
fn reduceCensus(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    n_workers: usize,
    censuses: []expr_agg.Census,
    keep: usize,
    cap: usize,
) !?CensusRepeats {
    var cursor_p: std.atomic.Value(usize) = .init(0);
    var found: std.atomic.Value(usize) = .init(0);
    var out: CensusRepeats = .{ .tasks = try arena.alloc(CensusTask, @min(n_workers, expr_agg.Census.N_PARTS)) };
    for (out.tasks) |*t| t.* = .{
        .gpa = gpa,
        .censuses = censuses,
        .cursor = &cursor_p,
        .found = &found,
        .cap = cap,
        // Dense repeats are reduced to the most frequent per partition, never all emitted (`CensusTask`).
        .keep = keep,
    };
    errdefer out.deinit(gpa);
    const config: std.Thread.SpawnConfig = .{ .stack_size = WORKER_STACK_SIZE };
    if (out.tasks.len == 1 or !spawn_util.runTree(CensusTask, out.tasks, config, CensusTask.run)) out.tasks[0].run();
    for (out.tasks) |t| if (t.err) |e| return e;
    if (found.load(.monotonic) > cap) {
        out.deinit(gpa);
        return null;
    }
    try out.repeats.ensureTotalCapacity(gpa, found.load(.monotonic));
    for (out.tasks) |t| out.repeats.appendSliceAssumeCapacity(t.out.items);
    std.mem.sortUnstable(Repeat, out.repeats.items, {}, struct {
        fn more(_: void, a: Repeat, b: Repeat) bool {
            return a.count > b.count or (a.count == b.count and a.fp < b.fp);
        }
    }.more);
    for (out.tasks) |task| out.omitted = @max(out.omitted, task.omitted);
    return out;
}

/// A producer's excluded-class bound and candidate membership. Cell and identity producers share the same
/// exact grouping pass and proof. A prefix additionally proves that excluded singleton ties appear later.
const CutBoundPlan = struct {
    bound: u64,
    distinct: bool = false,
    widen: ?struct { identities: expr_agg.FingerprintSet, bound: u64 } = null,
    cells: ?[]u64 = null,
    identities: ?expr_agg.FingerprintSet = null,
    prefix: ?struct { item_rows: []const u64, sure_need: u64, short_need: u64 } = null,

    fn proves(p: CutBoundPlan, score: u64) bool {
        return p.bound == 0 or score > p.bound;
    }

    fn deinit(p: *CutBoundPlan, a: std.mem.Allocator) void {
        if (p.cells) |cells| a.free(cells);
        if (p.identities) |*set| {
            set.map.deinit(a);
            a.free(set.filter);
        }
        if (p.widen) |*more| more.identities.map.deinit(a);
    }
};

fn certifiedResidual(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    workers: []Worker,
    cursor: *std.atomic.Value(usize),
    tables: []expr_agg.GroupTable,
    sketches: []expr_agg.CountSketch,
    censuses: []expr_agg.Census,
    calls: []const expr_agg.AggCall,
    order: expr_ast.ResultOrder,
    a_idx: usize,
    cfg: SketchTopK,
    plan: *CutBoundPlan,
) !bool {
    const k: usize = @intCast(order.offset +| order.limit.?);
    const counted = try arena.dupe(Worker, workers);
    const work = workers[0].work;
    var need: u64 = if (plan.prefix) |p| p.short_need else 0;
    const t0 = nowMonoNs();
    while (true) {
        if (plan.identities) |*set| {
            var last: u64 = 0;
            var row: u64 = 0;
            if (plan.prefix) |prefix| {
                last = std.math.maxInt(u32);
                var seen: u64 = 0;
                for (prefix.item_rows, 0..) |n, i| {
                    if (seen + n < need) {
                        seen += n;
                        continue;
                    }
                    const rg_rows = workers[0].metas[work[i].file].row_groups.items[work[i].rg].num_rows;
                    last = i;
                    row = if (rg_rows >= 0 and n == @as(u64, @intCast(rg_rows))) need - seen else std.math.maxInt(u64);
                    break;
                }
            }
            for (sketches, censuses) |*s, *c| {
                c.admitted = set;
                c.prefix_item = last;
                c.prefix_row = row;
                s.census = c;
            }
        } else {
            for (sketches) |*s| {
                s.census = null;
                s.admit = plan.cells.?;
            }
        }
        runPhase(workers, cursor) catch |e| {
            if (e != error.ExceededMemoryBudget) return e;
            try clearWorkerErrors(workers, error.ExceededMemoryBudget);
            restoreCounts(workers, counted);
            clearTables(gpa, tables);
            if (cfg.outcome) |o| o.* = .fell_back;
            return false;
        };
        restoreCounts(workers, counted);
        var short = false;
        const proven = if (plan.prefix) |prefix| prefix_proof: {
            if (need >= prefix.sure_need) break :prefix_proof true;
            var fresh: usize = 0;
            for (tables) |*table| fresh += table.unadmittedGroups(&censuses[0]);
            if (fresh < k) {
                clearTables(gpa, tables);
                need = prefix.sure_need;
                continue;
            }
            short = true;
            break :prefix_proof true;
        } else count_proof: {
            const kth = if (plan.distinct)
                kthDistinct(gpa, arena, tables, calls.len, a_idx, k) catch |e| {
                    if (e != error.ExceededMemoryBudget) return e;
                    clearTables(gpa, tables);
                    if (cfg.outcome) |o| o.* = .fell_back;
                    return false;
                }
            else
                try kthTotal(arena, tables, calls.len, a_idx, k);
            break :count_proof plan.proves(kth);
        };
        if (cfg.trace) std.debug.print("certificate: residual_ms={d} excluded_bound={d} prefix={} proven={}\n", .{
            @divTrunc(nowMonoNs() - t0, 1_000_000), plan.bound, plan.prefix != null, proven,
        });
        if (cfg.certify and proven) {
            if (cfg.outcome) |o| o.* = if (plan.identities != null)
                (if (short) .census_short else .census)
            else
                .certified;
            return true;
        }
        if (plan.widen) |more| {
            // Keep completed exact groups; the next map contains only newly admitted classes.
            plan.identities.?.map.deinit(gpa);
            plan.identities = more.identities;
            plan.bound = more.bound;
            plan.widen = null;
            continue;
        }
        if (cfg.outcome) |o| o.* = .fell_back;
        clearTables(gpa, tables);
        return false;
    }
}

/// Produce a complete hash-class bound and candidate superset; full-key equality is deferred to the shared
/// residual. Collisions can retain more classes or decline, never exclude a possible winner.
/// The filter may contain a superset of bits when two batches share it; full identity lookup still admits only
/// the map's classes. Separate maps allow widening without counting any previously admitted row twice.
fn identitySet(
    gpa: std.mem.Allocator,
    filter: []u64,
    classes: []const Repeat,
) !expr_agg.FingerprintSet {
    var set: expr_agg.FingerprintSet = .{ .filter = filter, .map = .empty };
    errdefer set.map.deinit(gpa);
    try set.map.ensureTotalCapacity(gpa, @intCast(classes.len));
    for (classes) |class| {
        set.map.putAssumeCapacity(class.fp, {});
        const bit = class.fp & ((1 << expr_agg.FingerprintSet.filter_bits) - 1);
        filter[bit / 64] |= @as(u64, 1) << @intCast(bit % 64);
    }
    return set;
}

fn distinctScorePlan(
    gpa: std.mem.Allocator,
    reduced: *const CensusRepeats,
    item_rows: []const u64,
    k: usize,
    cfg: SketchTopK,
) !?CutBoundPlan {
    const classes = reduced.repeats.items;
    const n = @min(classes.len, @max(k *| cfg.admit_per_row, 1));
    const wider = @min(classes.len, n *| 4);
    var rows: u64 = 0;
    for (item_rows) |count| rows += count;
    var admitted_rows: u64 = 0;
    for (classes[0..n]) |class| admitted_rows += class.count;
    if (n < k or admitted_rows *| 4 > rows) return null;
    const filter = try gpa.alloc(u64, (1 << expr_agg.FingerprintSet.filter_bits) / 64);
    @memset(filter, 0);
    var plan: CutBoundPlan = .{
        .bound = @max(reduced.omitted, if (n < classes.len) classes[n].count else 1),
        .distinct = true,
        .identities = identitySet(gpa, filter, classes[0..n]) catch |e| {
            gpa.free(filter);
            return e;
        },
    };
    errdefer plan.deinit(gpa);
    for (classes[n..wider]) |class| admitted_rows += class.count;
    if (cfg.certify and wider > n and admitted_rows *| 4 <= rows) {
        const more = try identitySet(gpa, filter, classes[n..wider]);
        plan.widen = .{
            .bound = @max(reduced.omitted, if (wider < classes.len) classes[wider].count else 1),
            .identities = more,
        };
    }
    return plan;
}

fn identityBoundPlan(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    workers: []Worker,
    tables: []expr_agg.GroupTable,
    censuses: []expr_agg.Census,
    calls: []const expr_agg.AggCall,
    order: expr_ast.ResultOrder,
    a_idx: usize,
    cfg: SketchTopK,
    count_ns: i128,
) !?CutBoundPlan {
    const k: usize = @intCast(order.offset +| order.limit.?);
    const item_rows = censuses[0].item_rows;
    const t1 = nowMonoNs();
    const count_ms = @divTrunc(count_ns, 1_000_000);

    const distinct = calls[a_idx].func == .count_distinct;
    const cap = @max(k *| cfg.admit_per_row *| 64, 1 << 20);
    const keep = @max(k *| cfg.admit_per_row, 1) *| @as(usize, if (distinct) 4 else 1);
    var reduced = (try reduceCensus(gpa, arena, workers.len, censuses, keep, cap)) orelse {
        if (cfg.trace) std.debug.print("census: count_ms={d} repeated>{d}, too many\n", .{ count_ms, cap });
        return null;
    };
    defer reduced.deinit(gpa);
    if (distinct) return distinctScorePlan(gpa, &reduced, item_rows, k, cfg);
    if (cfg.trace) std.debug.print("census: reduce_ms={d}\n", .{@divTrunc(nowMonoNs() - t1, 1_000_000)});
    const items = reduced.repeats.items;
    const t: u64 = if (items.len >= k) items[k - 1].count else 2;
    // A fingerprint a partition dropped totals at most `omitted`, and a key at most its fingerprint (a collision only
    // adds rows to it). Only with every dropped one below `t` does admitting the fingerprints totalling `t` or more
    // admit every key that can reach the cut; the exact k-th total must still reach `t` to certify it.
    const omitted = reduced.omitted;
    if (omitted >= t) {
        if (cfg.trace) std.debug.print("census: count_ms={d} repeated={d} t={d} omitted={d}, cannot cut\n", .{
            count_ms, items.len, t, omitted,
        });
        return null;
    }
    // The census counts rows, so only a plain count(*) gives each early row's key exactly 1; a count of a column or
    // under FILTER can give it 0, and must certify by the totals.
    const call = calls[a_idx];
    const prefix = t == 2 and order.keys.len == 1 and call.arg == null and call.where == null;
    var n_admit: usize = 0;
    var admit_rows: u64 = 0;
    while (n_admit < items.len and items[n_admit].count >= t) : (n_admit += 1) admit_rows += items[n_admit].count;
    const admit_cap = @max(k *| cfg.admit_per_row *| 16, 1 << 16);
    if (n_admit > admit_cap or (items.len < k and !prefix)) {
        if (cfg.trace) std.debug.print("census: count_ms={d} repeated={d} t={d} admit={d}, cannot cut\n", .{
            count_ms, items.len, t, n_admit,
        });
        return null;
    }

    var set: expr_agg.FingerprintSet = .{ .filter = undefined, .map = .empty };
    errdefer set.map.deinit(gpa);
    const filter = try gpa.alloc(u64, (1 << expr_agg.FingerprintSet.filter_bits) / 64);
    errdefer gpa.free(filter);
    @memset(filter, 0);
    try set.map.ensureTotalCapacity(gpa, @intCast(n_admit));
    for (items[0..n_admit]) |r| {
        set.map.putAssumeCapacity(r.fp, {});
        const b = r.fp & ((1 << expr_agg.FingerprintSet.filter_bits) - 1);
        filter[b / 64] |= @as(u64, 1) << @intCast(b % 64);
    }
    set.filter = filter;

    // The prefix ends where the rows given to the census pass `need`. In a row group whose rows all reached the
    // census, at that row; otherwise at the end of it. `k` rows beyond every admitted key's rows always hold k keys
    // seen once, but heavy keys can make that most of the input. So a fixed-width table first tries a prefix sized by
    // the admitted keys' share of the rows, certified only when the admit pass grouped k keys it did not admit.
    var total_rows: u64 = 0;
    for (item_rows) |n| total_rows += n;
    const sure_need = k + admit_rows;
    const short_need: u64 = if (total_rows > admit_rows and tables.len > 0 and tables[0].fixed_stride != 0)
        @min(sure_need, (2 *| @as(u64, k) *| total_rows) / (total_rows - admit_rows) +| 1)
    else
        sure_need;
    return .{
        .bound = t - 1,
        .identities = set,
        .prefix = if (prefix) .{ .item_rows = item_rows, .sure_need = sure_need, .short_need = short_need } else null,
    };
}

/// The k-th largest count(DISTINCT) of call `a_idx` over the keys of `tables`, each key's values merged across the
/// tables holding it; 0 with fewer than k keys. A merged copy is charged like the set it copies, and freed.
fn kthDistinct(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    stride: usize,
    a_idx: usize,
    k: usize,
) !u64 {
    const Seen = struct { table: usize, group: usize, merged: ?expr_agg.DistinctAcc = null };
    var keys: std.StringArrayHashMapUnmanaged(Seen) = .empty;
    defer for (keys.values()) |*e| if (e.merged) |*m| m.deinit(gpa);
    for (tables, 0..) |*t, ti| for (0..t.groupCount()) |g| {
        const gop = try keys.getOrPut(arena, t.keyAt(g));
        if (!gop.found_existing) {
            gop.value_ptr.* = .{ .table = ti, .group = g };
            continue;
        }
        const e = gop.value_ptr;
        if (e.merged == null) {
            e.merged = .{};
            try e.merged.?.mergeFrom(tables[e.table].accumulators.items[e.group * stride + a_idx].distinct, gpa);
        }
        try e.merged.?.mergeFrom(t.readAcc(g, a_idx, stride).distinct, gpa);
    };
    if (keys.count() < k) return 0;
    const counts = try arena.alloc(u64, keys.count());
    for (keys.values(), counts) |e, *c| c.* = if (e.merged) |m|
        m.count()
    else
        tables[e.table].accumulators.items[e.group * stride + a_idx].distinct.count();
    std.mem.sortUnstable(u64, counts, {}, std.sort.desc(u64));
    return counts[k - 1];
}

/// Discover at most H exact keys per worker. A worker's local Hth first position bounds the global Hth position,
/// so it can stop later discovery; every selected key is still counted through the entire input afterwards.
fn firstAppearanceCut(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    workers: []Worker,
    cursor: *std.atomic.Value(usize),
    tables: []expr_agg.GroupTable,
    order: expr_ast.ResultOrder,
    cfg: SketchTopK,
) !void {
    const k: usize = @intCast(order.offset +| order.limit.?);
    const saved = try arena.dupe(Worker, workers);
    var threshold: std.atomic.Value(u64) = .init(std.math.maxInt(u64));
    for (tables) |*table| table.discovery = .{ .limit = k, .threshold = &threshold };
    defer for (tables) |*table| {
        table.discovery = null;
    };
    const SavedWindow = struct { rows: usize, budget: ?*consumer.DecodeBudget };
    const windows = try arena.alloc(SavedWindow, workers.len);
    var discovery_budget: consumer.DecodeBudget = .{
        .limit = if (tables[0].shared) |budget| budget.limit else std.math.maxInt(usize),
        .workers = workers.len,
    };
    for (workers, windows) |*w, *window| {
        window.* = .{ .rows = w.decode_batch_rows, .budget = w.decode_budget };
        w.decode_batch_rows = owner_groups.batchRows(null);
        if (w.decode_budget == null) w.decode_budget = &discovery_budget;
    }
    defer for (workers, windows) |*w, window| {
        w.decode_batch_rows = window.rows;
        w.decode_budget = window.budget;
    };
    try runPhase(workers, cursor);
    for (workers, windows) |*w, window| {
        w.decode_batch_rows = window.rows;
        w.decode_budget = window.budget;
    }
    for (tables) |*table| table.discovery = null;

    const First = struct { first: u64, table: usize, group: usize };
    var seen: std.StringArrayHashMapUnmanaged(First) = .empty;
    defer seen.deinit(gpa);
    for (tables, 0..) |*table, ti| for (0..table.groupCount()) |group| {
        const entry = try seen.getOrPut(gpa, table.keyAt(group));
        const first: First = .{ .first = table.first.items[group], .table = ti, .group = group };
        if (!entry.found_existing or first.first < entry.value_ptr.first) entry.value_ptr.* = first;
    };
    std.mem.sortUnstable(First, seen.values(), {}, struct {
        fn earlier(_: void, x: First, y: First) bool {
            return x.first < y.first;
        }
    }.earlier);
    const n = @min(k, seen.count());
    const filter = try gpa.alloc(u64, (1 << expr_agg.FingerprintSet.filter_bits) / 64);
    defer gpa.free(filter);
    var set: expr_agg.FingerprintSet = .{ .filter = filter, .map = .empty };
    defer set.map.deinit(gpa);
    @memset(filter, 0);
    try set.map.ensureTotalCapacity(gpa, @intCast(n));
    const identity: expr_agg.Census = .{ .gpa = gpa, .item_rows = &.{}, .fp_mask = censusMask(cfg) };
    for (seen.values()[0..n]) |first| {
        const fp = identity.fingerprint(tables[first.table].routeHash(first.group));
        set.map.putAssumeCapacity(fp, {});
        filter[fp % (1 << expr_agg.FingerprintSet.filter_bits) / 64] |=
            @as(u64, 1) << @intCast(fp % 64);
    }
    // The first scan only discovered keys. Replay every row once for complete counts/payloads; hash collisions
    // merely admit extra keys whose first positions are later than the H retained keys.
    clearTables(gpa, tables);
    const censuses = try arena.alloc(expr_agg.Census, workers.len);
    defer for (censuses) |*c| c.deinit();
    for (censuses) |*c| c.* = .{ .gpa = gpa, .item_rows = &.{}, .admitted = &set, .fp_mask = identity.fp_mask };
    var no_cells = [1]u32{0};
    const sketches = try arena.alloc(expr_agg.CountSketch, workers.len);
    for (sketches, censuses, tables) |*s, *c, *table| {
        s.* = .{ .cells = &no_cells, .shift = 63, .census = c };
        table.sketch = s;
    }
    defer for (tables) |*table| {
        table.sketch = null;
    };
    restoreCounts(workers, saved);
    const t0 = nowMonoNs();
    try runPhase(workers, cursor);
    if (cfg.trace) std.debug.print("first: bounded_keys={d} threshold={d} count_ms={d}\n", .{
        n, threshold.load(.monotonic), @divTrunc(nowMonoNs() - t0, 1_000_000),
    });
}

/// Puts back the row and row-group counts a discarded pass added.
fn restoreCounts(workers: []Worker, saved: []const Worker) void {
    for (workers, saved) |*w, s| {
        w.rows_in = s.rows_in;
        w.rows_scanned = s.rows_scanned;
        w.rows_matched = s.rows_matched;
        w.rgs_in = s.rgs_in;
        w.rgs_pruned = s.rgs_pruned;
        w.rgs_full_match = s.rgs_full_match;
    }
}

/// One pass of `workers` over every work item, from a fresh cursor.
/// Clears an optional phase's expected failures and partial decode evidence before its exact retry.
/// Other failures still propagate. `runPhase` chooses refusals canonically before deciding to retry.
fn clearWorkerErrors(workers: []Worker, expected: anyerror) !void {
    const exact_retry = expected == error.ExceededMemoryBudget or expected == error.CensusAbandoned;
    for (workers) |*w| if (w.err) |we| if (we == expected or
        (exact_retry and consumer.isDecodeError(we)))
    {
        // The optional census scans exactly from the start next. Its partial projection cannot make a payload
        // error final while an earlier refused/abandoned unit may conceal another error. Trial memory is never
        // the query's refusal: discard the trial and let the established scan decide what fits.
        w.err = null;
    };
    if (firstWorkerFailure(workers, null)) |failure| return failure.err;
}

fn runPhase(workers: []Worker, cursor: *std.atomic.Value(usize)) !void {
    cursor.store(0, .monotonic);
    runWorkers(workers);
    if (phaseFailure(workers)) |err| return err;
}

fn phaseFailure(workers: []const Worker) ?anyerror {
    for (workers) |w| if (w.err) |err| if (err == error.CensusAbandoned) return err;
    return if (firstWorkerFailure(workers, null)) |failure| failure.err else null;
}

/// Per partition: every worker's pairs sorted, then each key's distinct values counted. Sorted by key for lookup.
const KeyDistinct = struct { k0: u64, k1: u64, count: u64, claimed: std.atomic.Value(bool) = .init(false) };

const PairFoldTask = struct {
    gpa: std.mem.Allocator,
    budget: *expr_agg.SharedBudget,
    sinks: []expr_agg.DistinctPairs,
    out: [][]KeyDistinct,
    cursor: *std.atomic.Value(usize),
    err: ?anyerror = null,

    fn run(t: *PairFoldTask) void {
        while (true) {
            const p = t.cursor.fetchAdd(1, .monotonic);
            if (p >= expr_agg.DistinctPairs.N) return;
            t.fold(p) catch |e| {
                t.err = e;
                return;
            };
        }
    }

    fn fold(t: *PairFoldTask, p: usize) !void {
        const Pair = expr_agg.DistinctPairs.Pair;
        var n: usize = 0;
        for (t.sinks) |*s| n += s.parts[p].items.len;
        const bytes = n * (@sizeOf(Pair) + @sizeOf(KeyDistinct));
        const got = t.budget.drawExact(bytes) orelse return error.ExceededMemoryBudget;
        defer t.budget.release(got);
        const all = try t.gpa.alloc(Pair, n);
        defer t.gpa.free(all);
        var at: usize = 0;
        for (t.sinks) |*s| {
            @memcpy(all[at..][0..s.parts[p].items.len], s.parts[p].items);
            at += s.parts[p].items.len;
            s.parts[p].clearAndFree(t.gpa);
        }
        std.mem.sortUnstable(Pair, all, {}, struct {
            fn lt(_: void, a: Pair, b: Pair) bool {
                if (a.k0 != b.k0) return a.k0 < b.k0;
                if (a.k1 != b.k1) return a.k1 < b.k1;
                return a.x < b.x;
            }
        }.lt);
        var keys: std.ArrayList(KeyDistinct) = .empty;
        errdefer keys.deinit(t.gpa);
        var i: usize = 0;
        while (i < all.len) {
            var count: u64 = 1;
            var j = i + 1;
            while (j < all.len and all[j].k0 == all[i].k0 and all[j].k1 == all[i].k1) : (j += 1) {
                if (all[j].x != all[j - 1].x) count += 1;
            }
            try keys.append(t.gpa, .{ .k0 = all[i].k0, .k1 = all[i].k1, .count = count });
            i = j;
        }
        t.out[p] = try keys.toOwnedSlice(t.gpa);
    }
};

const PairTableTask = struct {
    tables: []expr_agg.GroupTable,
    keyed: []const []KeyDistinct = &.{},
    agg_idx: usize = 0,
    agg_len: usize = 0,
    gpa: std.mem.Allocator,
    cursor: *std.atomic.Value(usize),
    sinks: ?[]expr_agg.DistinctPairs = null,
    err: ?anyerror = null,

    fn run(t: *PairTableTask) void {
        const Pairs = expr_agg.DistinctPairs;
        while (t.err == null) {
            const ti = t.cursor.fetchAdd(1, .monotonic);
            if (ti >= t.tables.len) return;
            const table = &t.tables[ti];
            if (t.sinks) |sinks| {
                const sink = &sinks[ti];
                if (!sink.active or sink.pending_sets) sink.drainTable(table) catch |e| {
                    t.err = e;
                    return;
                };
                continue;
            }
            for (0..table.groupCount()) |g| {
                const probe = Pairs.pairOf(table.keyAt(g), 0);
                const acc = &table.accumulators.items[g * t.agg_len + t.agg_idx];
                var n: u64 = 0;
                // Only the first table to claim a key carries its count, so the usual merge's sum is exact.
                if (findKeyDistinct(t.keyed[Pairs.partOf(probe)], probe.k0, probe.k1)) |e| {
                    if (e.claimed.cmpxchgStrong(false, true, .monotonic, .monotonic) == null) n = e.count;
                }
                if (acc.* == .distinct) acc.distinct.deinit(t.gpa);
                acc.* = .{ .count = n };
            }
        }
    }
};

fn findKeyDistinct(list: []KeyDistinct, k0: u64, k1: u64) ?*KeyDistinct {
    var lo: usize = 0;
    var hi: usize = list.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const m = &list[mid];
        if (m.k0 == k0 and m.k1 == k1) return m;
        if (m.k0 < k0 or (m.k0 == k0 and m.k1 < k1)) lo = mid + 1 else hi = mid;
    }
    return null;
}

/// Each table owns its stored sets and sink. Drain them in parallel before the shared pair fold, just as the
/// scan produced pairs in parallel; serial expansion would strand every decoder behind one large group.
fn drainDistinctPairs(
    gpa: std.mem.Allocator,
    sinks: []expr_agg.DistinctPairs,
    tables: []expr_agg.GroupTable,
    threads: usize,
) !void {
    var cursor: std.atomic.Value(usize) = .init(0);
    const n = @max(1, @min(threads, tables.len, 64));
    var tasks: [64]PairTableTask = undefined;
    for (tasks[0..n]) |*task| task.* = .{
        .tables = tables,
        .gpa = gpa,
        .cursor = &cursor,
        .sinks = sinks,
    };
    const config: std.Thread.SpawnConfig = .{ .stack_size = WORKER_STACK_SIZE };
    if (n == 1 or !spawn_util.runTree(PairTableTask, tasks[0..n], config, PairTableTask.run)) tasks[0].run();
    for (tasks[0..n]) |task| if (task.err) |e| return e;
}

/// Turn every worker's pairs into exact count(DISTINCT) states on the worker tables: each key's count on the first
/// table to claim it, 0 on the others. NULL values sent no pair, so a key seen only with them counts 0.
fn foldDistinctPairs(
    gpa: std.mem.Allocator,
    budget: *expr_agg.SharedBudget,
    sinks: []expr_agg.DistinctPairs,
    tables: []expr_agg.GroupTable,
    agg_idx: usize,
    agg_len: usize,
    threads: usize,
) !void {
    const N = expr_agg.DistinctPairs.N;
    const keyed = try gpa.alloc([]KeyDistinct, N);
    @memset(keyed, &.{});
    defer {
        for (keyed) |k| gpa.free(k);
        gpa.free(keyed);
    }
    var cursor: std.atomic.Value(usize) = .init(0);
    const n_tasks = @max(1, @min(threads, N, 64));
    var folds: [64]PairFoldTask = undefined;
    for (folds[0..n_tasks]) |*f| f.* = .{
        .gpa = gpa,
        .budget = budget,
        .sinks = sinks,
        .out = keyed,
        .cursor = &cursor,
    };
    const config: std.Thread.SpawnConfig = .{ .stack_size = WORKER_STACK_SIZE };
    if (n_tasks == 1 or !spawn_util.runTree(PairFoldTask, folds[0..n_tasks], config, PairFoldTask.run)) folds[0].run();
    for (folds[0..n_tasks]) |f| if (f.err) |e| return e;
    for (sinks) |*s| s.deinit();
    // Tasks whose spawn failed leave their share to the ones that started, through the shared cursor.
    var table_cursor: std.atomic.Value(usize) = .init(0);
    const n_apply = @max(1, @min(threads, tables.len, 64));
    var applies: [64]PairTableTask = undefined;
    for (applies[0..n_apply]) |*a| a.* = .{
        .tables = tables,
        .keyed = keyed,
        .agg_idx = agg_idx,
        .agg_len = agg_len,
        .gpa = gpa,
        .cursor = &table_cursor,
    };
    if (n_apply == 1 or !spawn_util.runTree(PairTableTask, applies[0..n_apply], config, PairTableTask.run))
        applies[0].run();
}

/// The k-th largest total of the COUNT at `a_idx` over every key of `tables`, 0 with fewer than `k` keys.
fn kthTotal(arena: std.mem.Allocator, tables: []const expr_agg.GroupTable, stride: usize, a_idx: usize, k: usize) !u64 {
    var totals: std.StringArrayHashMapUnmanaged(u64) = .empty;
    for (tables) |*t| for (0..t.groupCount()) |g| {
        const e = try totals.getOrPutValue(arena, t.keyAt(g), 0);
        e.value_ptr.* +|= t.readAcc(g, a_idx, stride).count;
    };
    const vals = totals.values();
    if (vals.len < k) return 0;
    std.mem.sortUnstable(u64, vals, {}, std.sort.desc(u64));
    return vals[k - 1];
}

/// Run a multi-file aggregate.
///
/// `gpa` is used for thread-shared scratch (per-RG arenas, per-worker
/// state). `arena` is used for results that outlive the function call:
/// `MultiAggResult.state` and the parsed metas live in this arena. The
/// answer, `MultiAggResult.output`, is gpa-owned; `MultiAggResult.deinit`
/// frees both.
pub fn runMultiAggregate(gpa: std.mem.Allocator, arena: std.mem.Allocator, args: MultiAggArgs) !MultiAggResult {
    // A budget the established path fits must not fail the query, nor may whether it fails depend on timing. A refused
    // scan runs again, exactly, each time on a narrower path: without every fast path it armed (they charge more of
    // their peak than the paths they stand in for, `FastPath`); then, where several workers' tables were refused, on
    // the forced partitions, a partition's groups folded at a time; then on one worker, which claims row groups in
    // order and so peaks the same every run, but only where one worker may fit (`FastPath.one_table_may_fit`): else
    // its one table must hold all the refused tables held and more, and it only refuses, many times slower. Decode
    // memory the query's ledger refused also runs on one worker (`FastPath.decode_memory`), and there once more on a
    // small decode budget, so the tables have nearly all of the ledger. A plain grouping a cost rule chose over a cut
    // gives way to that cut, whose refusal is final. Each step only narrows (`narrowed`): at most seven general scans,
    // plus the shared-string prefix, an admitted record scan and its serial decode retry before the general chain,
    // and each arms its paths only over inputs a scan reads again, whole, from the start.
    var attempt = args;
    var chain: Chain = .{ .parts_tried = args.partagg };
    const ledger_before = if (args.ledger) |l| l.used.load(.monotonic) else 0;
    var may_fit = false;
    while (true) {
        var taken: std.EnumSet(FastPath) = .{};
        attempt.taken = &taken;
        var merge_memory: core_memory.Charged = undefined;
        if (args.ledger) |l| {
            merge_memory = .{ .child = gpa, .budget = l };
            attempt.merge_memory = &merge_memory;
        }
        if (prepareAggregate(gpa, arena, attempt, false)) |r| return r else |e0| {
            const e = if (args.ledger != null) merge_memory.refusal(e0) else e0;
            if (e == error.CountRankedDistinctDeclined) {
                attempt.count_ranked_distinct = .off;
                try rewindInputs(arena, &attempt);
                continue;
            }
            if (e != error.ExceededMemoryBudget) return e;
            if (args.ledger != null and merge_memory.refused.load(.monotonic)) taken.insert(.merge_memory);
            // What a refused scan freed goes back to the OS too, or the next scan's peak stands on its leftovers.
            core_memory.trimHeap();
            may_fit = may_fit or taken.contains(.one_table_may_fit);
            var next = narrowed(args, attempt, taken, &chain, may_fit) orelse return e;
            if (attempt.inputs.ptr == args.inputs.ptr) try rewindInputs(arena, &next);
            // A refused scan, and the reader it abandoned, gave back all they drew: the next runs on the whole of what
            // the query has left.
            if (args.ledger) |l| std.debug.assert(l.used.load(.monotonic) == ledger_before);
            attempt = next;
        }
    }
}

/// A joined attempt may have returned every gated row group's pages. Replays read the stable mappings,
/// never the reader's ready-but-released window. Allocate the view before abandoning any reader state.
fn rewindInputs(arena: std.mem.Allocator, args: *MultiAggArgs) !void {
    if (!allRescannable(args.inputs)) return error.ExceededMemoryBudget;
    const inputs = try arena.dupe(Input, args.inputs);
    for (inputs) |*input| if (input.plan_bytes) |b| {
        input.bytes = b;
        input.gate = null;
        input.dict_wait = null;
    };
    if (args.start_reads) |s| if (s.abandon) |abandon| abandon(s.ctx);
    args.inputs = inputs;
    args.start_reads = null;
    args.dict_probe = null;
}

/// Whether several tables hold copies of the same keys: of up to 256 keys spread over each, an eighth or more are in
/// another. A sample, and so only a cap on the reruns a refusal tries (`narrowed`), never a proof; no keys at all (an
/// early refusal) says nothing, and counts as copies.
fn holdCopies(tables: []const expr_agg.GroupTable) bool {
    var seen: usize = 0;
    var shared: usize = 0;
    for (tables, 0..) |*t, ti| {
        const n = t.groupCount();
        var g: usize = 0;
        while (g < n) : (g += @max(1, n / 256)) {
            seen += 1;
            const key = t.keyAt(g);
            for (tables, 0..) |*o, oi| if (oi != ti and o.findKey(key) != null) {
                shared += 1;
                break;
            };
        }
    }
    return seen == 0 or shared *| 8 >= seen;
}

/// Whether the query, planned as the one-worker rerun plans it (on one worker, its inputs mapped, no forced
/// partitions or cost-rule plain grouping), takes a cut, which holds far less than the tables a refusal held: one
/// worker's cells fit where several workers' did not, and a mapped input admits the first keys' cut.
fn oneWorkerCuts(arena: std.mem.Allocator, in: PlanInputs) !bool {
    var one = in;
    one.workers = 1;
    one.readers = false;
    one.args.parallelism = 1;
    one.args.partagg = false;
    one.args.plain_rules = false;
    const inputs = try arena.dupe(Input, in.args.inputs);
    for (inputs) |*input| if (input.plan_bytes) |b| {
        input.bytes = b;
        input.gate = null;
    };
    one.args.inputs = inputs;
    return switch (planAggregate(one).dispatch.strategy) {
        .sketch, .first_keys => true,
        .scalar, .plain_hash, .partitioned_hash => false,
    };
}

/// What a refusal chain has run so far (`narrowed`).
const Chain = struct {
    /// The forced partitions (`MultiAggArgs.partagg`), which append to runs; the cost rules' shared partitions
    /// (`FastPath.partitioned`) are not those, and leave it.
    parts_tried: bool,
    /// The one-worker scan has run again on a small decode budget (`narrowed`).
    lean_tried: bool = false,
};

/// Fund a decoder floor before workers start. Whole row groups may borrow headroom; slices retain protected room
/// when that admission refuses. Cancelling the private sample returns the floors beside still-charged live values.
const PrivateDecode = struct {
    held: usize = 0,
    workers: []core_memory.SharedBudget = &.{},
    samples: []core_memory.SharedBudget = &.{},

    fn init(
        a: std.mem.Allocator,
        parent: *core_memory.SharedBudget,
        n: usize,
        limit: ?usize,
        dictionary_peak: u64,
    ) !PrivateDecode {
        const share = @min(limit orelse parent.limit / 2, parent.limit / 4) / n;
        // A floor consumed by a dictionary strands the sample on tiny slices even when it later cancels.
        // Decline before reserving runs or reading rows; leave room for a slice beside the fixed dictionary.
        if (share < @max(huge_pages.huge_page_size, dictionary_peak +| parent.block)) return .{};
        const held = parent.drawExact(share * n) orelse return .{};
        errdefer parent.release(held);
        const workers = try a.alloc(core_memory.SharedBudget, n);
        for (workers) |*w| w.* = .{ .limit = parent.limit, .parent = parent, .funded = share };
        return .{ .held = held, .workers = workers };
    }

    fn fundSamples(self: *PrivateDecode, a: std.mem.Allocator, part: *partagg.PartAgg, width: u64) !bool {
        // Decode loans must not strand every worker before its first flush. Transfer part of the prepaid run
        // ceiling into bounded local-table floors; it is the same charged credit, not another reservation.
        const share = (width +| 64) *| part.cap *| 4 +| part.budget.block;
        const total = share *| self.workers.len;
        const credit = part.run_credit.load(.monotonic);
        if (total > credit) return false;
        const samples = try a.alloc(core_memory.SharedBudget, self.workers.len);
        part.run_credit.store(credit - @as(usize, @intCast(total)), .monotonic);
        for (samples) |*b| b.* = .{ .limit = part.budget.limit, .parent = part.budget, .funded = @intCast(share) };
        self.samples = samples;
        part.sample_floors = samples;
        return true;
    }

    fn release(self: *PrivateDecode) void {
        for (self.workers) |*w| {
            std.debug.assert(w.used.load(.monotonic) == 0);
            w.releaseFloor();
        }
        // A failed worker can still hold a local table; cancellation keeps its live bytes charged until deinit.
        for (self.samples) |*b| b.releaseFloor();
        self.held = 0;
        self.workers = &.{};
        self.samples = &.{};
    }
};

/// The scan to run after `attempt` was refused with `taken` armed, or null when no narrower one can answer and the
/// refusal is the query's. `may_fit`: some refusal so far showed one worker's table may fit (`one_table_may_fit`).
fn narrowed(
    args: MultiAggArgs,
    attempt: MultiAggArgs,
    taken: std.EnumSet(FastPath),
    chain: *Chain,
    may_fit: bool,
) ?MultiAggArgs {
    // A finished windowed source may already have discarded its pages. No budget retry can read it again.
    if (!allRescannable(attempt.inputs)) return null;
    var next = attempt;
    if (taken.contains(.grouped_distinct_bitmap)) {
        next.grouped_distinct_bitmap = .off;
        return next;
    }
    if (taken.contains(.shared_strings)) {
        next.shared_strings = false;
        return next;
    }
    if (taken.contains(.msd_records)) {
        // Retained pages and decoder scratch have been released. Admission required complete rescannability,
        // so a bounded-decoder or unsupported-page refusal can enter the established chain from its start.
        next.msd_records = false;
        return next;
    }
    if (taken.contains(.integer_records)) {
        // Both owned-record layouts use this refusal/restart slot; a query's key type chooses only one layout.
        // Concurrent decode draws can race with one another. Try the same layout serially before giving it up,
        // so a budget its single decoder fits always answers. A width refusal is independent of decoder scheduling.
        if (taken.contains(.decode_memory) and attempt.parallelism != 1) {
            next.parallelism = 1;
            return next;
        }
        next.integer_records = false;
        next.byte_records = false;
        next.msd_records = false;
        next.parallelism = args.parallelism;
        return next;
    }
    if (taken.contains(.private_runs)) {
        next.private_runs = false;
        return next;
    }
    // A rerun never trades a cut for a plain table again. After a cost rule's plain grouping that is the cut it stood
    // in for, planned as if the rule had not run: the chain from here is the cut's.
    next.plain_rules = false;
    if (taken.contains(.plain_rule)) return next;
    if (taken.contains(.dense)) next.dense = false;
    if (taken.contains(.spill)) next.spill = false;
    if (taken.contains(.pairs)) next.distinct_pairs = .off;
    if (taken.contains(.partitioned)) next.partition_cost = false;
    if (taken.contains(.dense) or taken.contains(.spill) or taken.contains(.pairs) or taken.contains(.partitioned))
        return next;
    // Decode memory the ledger refused is least on one worker, whatever the tables held; and least of all there on a
    // ledger of `lean_decode` bytes of its own (the ceiling's slack), which leaves the tables all of the query's, as
    // they had beside an uncharged decode. What does not decode in that refuses.
    const one_decoder = (taken.contains(.decode_memory) or taken.contains(.merge_memory)) and attempt.parallelism != 1;
    if (taken.contains(.decode_memory) and attempt.parallelism == 1 and !chain.lean_tried) if (args.decode_limit) |l| {
        chain.lean_tried = true;
        // Half the ledger as the decode budget: a row group past it slices, on the room the other half leaves.
        next.decode_limit = @min(l, core_memory.lean_decode / 2);
        next.charge_decode = false;
        return next;
    };
    if (!taken.contains(.worker_tables) and !one_decoder) return null;
    if (taken.contains(.worker_tables) and taken.contains(.partitions_fit) and !chain.parts_tried) {
        next.partagg = true;
        chain.parts_tried = true;
        return next;
    }
    if (!may_fit and !one_decoder) return null;
    next.parallelism = 1;
    next.partagg = args.partagg;
    return next;
}

/// Shares all binding and work sizing with execution, but stops before allocating workers or aggregate tables.
pub fn explainAggregate(gpa: std.mem.Allocator, arena: std.mem.Allocator, args: MultiAggArgs) !AggregateExplanation {
    return prepareAggregate(gpa, arena, args, true);
}

fn prepareAggregate(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    comptime explain: bool,
) !if (explain) AggregateExplanation else MultiAggResult {
    if (args.inputs.len == 0) return error.NoInputs;

    // Parallel because footer parsing scales with file count and schema width and can dominate short multi-file scans.
    // `meta_arenas` must outlive this call: `metas` points into them.
    var meta_arenas: []std.heap.ArenaAllocator = &.{};
    defer for (meta_arenas) |*a| a.deinit();

    const t_parse = nowMonoNs();
    const metas: []const schema.FileMetaData = if (args.metas) |m| blk: {
        if (m.len != args.inputs.len) return error.SchemaMismatch;
        break :blk m;
    } else blk: {
        switch (try parseFooters(arena, gpa, args.inputs, args.parallelism, &meta_arenas, args.profiler)) {
            .ok => |parsed| break :blk parsed,
            .failed => |f| {
                Diag.setInput(args.diag, args.inputs[f.index].name, f.err);
                return switch (f.err) {
                    error.EncryptedFile => error.EncryptedFile,
                    error.ExternalColumnChunk => error.ExternalColumnChunk,
                    error.InvalidDecimalType => error.InvalidDecimalType,
                    else => error.NotParquet,
                };
            },
        }
    };
    consumer.setDecodeFailure(null);

    var probe: FailureProbe = .{ .limit = args.max_memory };
    defer probe.releaseGates();
    var execution = args;
    execution.failure_probe = &probe;
    return prepareAggregateWithMetas(gpa, arena, execution, explain, metas, t_parse) catch |err| {
        if (!consumer.isDecodeError(err)) return err;
        defer consumer.resolveDecodeFailure(args.diag, metas, args.inputs);
        const p = probe.context orelse return err;
        // Local read windows can return their entire charge before the bounded probe reads the mapping.
        if (args.start_reads) |start| if (start.abandon) |abandon| abandon(start.ctx);
        var own: core_memory.SharedBudget = .{ .limit = args.max_memory };
        const ledger = args.ledger orelse &own;
        // Independent of worker count and cache windows. The outer ledger accounts for any still-live input bytes.
        var bound: core_memory.SharedBudget = .{ .limit = args.max_memory, .parent = ledger };
        var charged: core_memory.Charged = .{ .child = std.heap.page_allocator, .budget = &bound };
        const failure = canonicalFailurePrefix(charged.allocator(), p);
        consumer.setDecodeFailure(failure.site);
        return failure.err;
    };
}

fn prepareAggregateWithMetas(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    initial_args: MultiAggArgs,
    comptime explain: bool,
    metas: []const schema.FileMetaData,
    t_parse: i64,
) !if (explain) AggregateExplanation else MultiAggResult {
    var args = initial_args;
    var t: Timings = .{};
    const prof = profile.threadOf(args.profiler, .main);

    // Validate schemas match the first file's: same number of leaves
    // and same names *case-insensitively*. Real-world datasets drift on
    // capitalization (NYC Taxi flips `Airport_fee` ↔ `airport_fee`
    // mid-2023). Strict-position-strict-name is too strict; full schema
    // evolution is a bigger lift we defer.
    const meta0 = &metas[0];
    // Columns are bound by leaf index against file 0, so the nesting must match too: the same names in the same order
    // can still put a leaf under a group in one file and at the top level in another.
    for (metas[1..], 1..) |*m, i| {
        const at = metadata.schemaMismatch(meta0.schema.items, m.schema.items, .values) orelse continue;
        if (at >= m.schema.items.len or at >= meta0.schema.items.len) return error.SchemaMismatch;
        Diag.setInput(args.diag, args.inputs[i].name, null);
        Diag.set(args.diag, meta0.schema.items[at].name, .{ .schema_mismatch = .{
            .file = i,
            .first_input = args.inputs[0].name,
            .other = .of(m.schema.items[at].name),
        } });
        return error.SchemaMismatch;
    }

    // 2. Parse aggregate + filter against meta0 (column indexes resolved
    //    against file 0; valid for all files because schemas match).
    const agg_calls: []expr_agg.AggCall = if (args.bound_aggregate) |bound|
        try arena.dupe(expr_agg.AggCall, bound.calls)
    else if (args.group_by != null and args.aggregate.len == 0)
        &.{}
    else
        try expr_parser.parseAggList(arena, args.aggregate, meta0, args.diag);
    if (agg_calls.len == 0 and args.group_by == null) return error.EmptyAggregate;

    var filter_opt: ?filter_ast.Filter = if (args.bound_aggregate) |bound| bound.filter else null;
    if (args.bound_aggregate == null) if (args.filter) |expr_str| {
        if (expr_str.len > 0) {
            filter_opt = try filter_parser.parse(arena, expr_str, meta0, args.diag);
            // `--trust-stats`: leaves trust plausible statistics; a float chunk with no NaN count prunes as NaN-free.
            if (args.trust_stats) filter_opt = try filter_ast.trustStats(arena, filter_opt.?);
        }
    };
    const group_by_items = if (args.bound_aggregate != null) null else if (args.group_by) |gb_str|
        try expr_parser.parseGroupByOf(arena, gb_str, meta0, args.diag, args.select_cols orelse &.{})
    else
        null;
    var group_by_keys: ?[]const expr_ast.Expr = if (args.bound_aggregate) |bound| bound.keys else if (group_by_items) |items| blk: {
        const exprs = try arena.alloc(expr_ast.Expr, items.len);
        for (items, 0..) |item, i| exprs[i] = item.expr;
        break :blk exprs;
    } else null;
    try refuseRepeated(arena, meta0, agg_calls, group_by_keys, args.diag);
    var key_names = try KeyNames.init(arena, meta0, group_by_items orelse &.{});
    key_names.sql = sqlBound(args.select_cols);
    if (args.bound_aggregate == null) try nameUnaliasedAggs(arena, agg_calls, &key_names);
    const agg_sources = try arena.alloc(?schema.SchemaElement, agg_calls.len);
    for (agg_calls, agg_sources) |call, *src| src.* = passThroughSource(call, meta0);
    var group_outputs: ?[]const BoundOutputColumn = if (args.bound_aggregate) |bound| bound.outputs else if (group_by_items != null)
        try bindGroupOutputs(arena, &key_names, agg_calls, meta0, args)
    else blk: {
        try checkAggAliases(agg_calls, args.diag);
        break :blk null;
    };
    if (args.result_order.having) |h| try checkHavingLanes(arena, h.*, group_outputs, agg_calls, group_by_keys);
    const error_group_keys = group_by_keys;
    const error_outputs = group_outputs;
    if (args.dependent_keys and !args.unordered) if (group_by_keys) |keys| {
        const dependencies = try dependentGroupKeys(arena, keys, group_outputs.?);
        group_by_keys = dependencies.keys;
        group_outputs = dependencies.outputs;
    };
    if (!explain) if (args.diag) |diag| {
        diag.execution_started = true;
    };
    const t_parse_end = nowMonoNs();
    t.parse_ns = @intCast(t_parse_end - t_parse);
    profile.record(prof, .parse_query, t_parse, t_parse_end, profile.args(.{}));
    if (args.profiler) |p| p.setColumnsFromMeta(meta0);
    const plan_span = profile.Span.begin(prof);

    if (!explain) if (try countRankedDistinct(gpa, arena, args, metas, agg_calls, group_by_keys, group_outputs, filter_opt)) |r|
        return r;

    // 3. What the query reads, and which columns statistics answer outright. The S3 planner makes the same plan
    //    from the same footers, so every column read here was fetched.
    const plan: agg_plan.Plan = try .init(arena, .{
        .filter = filter_opt,
        .calls = agg_calls,
        .group_keys = group_by_keys,
    }, metas, .fromFlags(args.scan_all, args.trust_stats));

    // 3b. Bloom filters, before any worker decides a row group: every decision then reads the same footers.
    var membership_stats: membership.Stats = .{};
    if (!explain) if (filter_opt) |f| if (probesMembership(args)) {
        const files = try arena.alloc([]const u8, args.inputs.len);
        for (args.inputs, files) |in, *b| b.* = in.bytes;
        const mapped: membership.MappedSource = .{ .files = files };
        membership_stats = try membership.load(arena, gpa, f, metas, mapped.source(), .{ .threads = args.parallelism });
        _ = try nanprobe.load(gpa, f, metas, mapped.source(), .{ .threads = args.parallelism, .compressed = false });
    };

    // 4. Build the flat row-group work list. If we have fewer row groups
    //    than the requested parallelism (e.g. wide scans on few large row groups),
    //    we split each row group's aggregates into chunks (horizontal scaling/sub-RG).
    var raw_work_items: std.ArrayList(struct { file: usize, rg: usize }) = .empty;
    for (metas, 0..) |*m, fi| {
        for (0..m.row_groups.items.len) |ri| try raw_work_items.append(arena, .{ .file = fi, .rg = ri });
    }
    const total_rgs = raw_work_items.items.len;

    const cpu_count = std.Thread.getCpuCount() catch 1;
    const requested = if (args.parallelism == 0) cpu_count else args.parallelism;

    // No row groups (a valid empty file) is `total_rgs == 0`: no work items, and nothing to divide by.
    var chunks_per_rg = if (total_rgs == 0 or total_rgs >= requested) @as(usize, 1) else (requested + total_rgs - 1) / total_rgs;
    if (group_by_keys != null) {
        chunks_per_rg = 1;
    } else {
        if (chunks_per_rg > agg_calls.len) chunks_per_rg = agg_calls.len;
        if (chunks_per_rg < 1) chunks_per_rg = 1;
    }

    // Each chunk of aggregates reads its own columns, the same in every row group, and so does its full-match subset.
    const chunk_columns = try arena.alloc(agg_plan.Columns, chunks_per_rg);
    const base_chunk_size = agg_calls.len / chunks_per_rg;
    const remainder = agg_calls.len % chunks_per_rg;
    const chunk_starts = try arena.alloc(usize, chunks_per_rg + 1);
    for (chunk_starts, 0..) |*start, chunk_idx| start.* = chunk_idx * base_chunk_size + @min(chunk_idx, remainder);
    for (chunk_columns, 0..) |*cols, chunk_idx| {
        cols.* = if (chunks_per_rg == 1)
            plan.columns
        else
            try plan.forCalls(arena, agg_calls[chunk_starts[chunk_idx]..chunk_starts[chunk_idx + 1]]);
    }

    var work_items: std.ArrayList(WorkItem) = .empty;
    // Workers fold string min/max winners into the items' accumulators, and the items own count(DISTINCT) sets from
    // here on; merging below moves both out, so this frees only what a failure leaves behind.
    errdefer for (work_items.items) |item| freeOwnedAccumulatorStrings(gpa, item.accumulators);
    for (raw_work_items.items) |raw| {
        for (chunk_columns, 0..) |cols, chunk_idx| {
            const agg_start = chunk_starts[chunk_idx];
            const agg_len = chunk_starts[chunk_idx + 1] - agg_start;

            // Initialize accumulators for this chunk
            const sub_accs = if (explain or group_by_keys != null)
                try arena.alloc(expr_agg.Accumulator, 0)
            else blk: {
                const arr = try arena.alloc(expr_agg.Accumulator, agg_len);
                for (agg_calls[agg_start .. agg_start + agg_len], arr) |call, *acc| acc.* = expr_agg.Accumulator.init(call);
                break :blk arr;
            };

            try work_items.append(arena, .{
                .file = raw.file,
                .rg = raw.rg,
                .agg_start = agg_start,
                .agg_len = agg_len,
                .columns = cols,
                .accumulators = sub_accs,
            });
            // The sets once the item owns them, so a failure making one frees the others.
            for (agg_calls[agg_start..][0..sub_accs.len], sub_accs) |call, *acc| if (call.func == .count_distinct) {
                const ds = try gpa.create(expr_agg.DistinctSet);
                ds.* = .{};
                acc.* = .{ .distinct = .fromSet(ds) };
            };
        }
    }

    // Size the worker set by BYTES to decode, not row-group count: thread creation has a fixed cost and a query may
    // touch only a small part of a wide schema. 2 MiB per worker (`min_bytes_per_worker`) is a conservative floor.
    var fetch_bytes: u64 = 0;
    for (work_items.items) |item| {
        const rg = &metas[item.file].row_groups.items[item.rg];
        for (rg.columns.items, 0..) |col, ci| {
            if (ci < item.columns.read.len and item.columns.read[ci]) {
                // Larger of two proxies: uncompressed bytes makes BOOLEAN (8 rows per byte) and dictionary-encoded
                // strings (index stream only) look nearly free, so `rows x 4` floors the cost they pay when
                // materialized.
                if (col.meta_data) |cm| {
                    const uncompressed: u64 = @intCast(cm.total_uncompressed_size);
                    const by_rows: u64 = @as(u64, @intCast(rg.num_rows)) *| 4;
                    fetch_bytes +|= @max(uncompressed, by_rows);
                }
            }
        }
    }
    const by_bytes = @max(@as(usize, 1), @as(usize, @intCast(fetch_bytes / @max(1, args.min_bytes_per_worker))));
    var n_workers = @max(@as(usize, 1), @min(@min(requested, work_items.items.len), by_bytes));
    plan_span.end(.plan, profile.args(.{ work_items.items.len, n_workers, total_rgs }));

    var string_record_path: ?RecordAdmission = null;
    if (explain) {
        string_record_path = try inlineSharedStrings(
            gpa,
            arena,
            args,
            metas,
            &plan,
            work_items.items,
            agg_calls,
            group_by_keys,
            group_outputs,
            n_workers,
            t,
            true,
        );
    } else if (try inlineSharedStrings(
        gpa,
        arena,
        args,
        metas,
        &plan,
        work_items.items,
        agg_calls,
        group_by_keys,
        group_outputs,
        n_workers,
        t,
        false,
    )) |result| return result;

    if (!explain) if (try inlineDistinctAnswer(
        gpa,
        arena,
        args,
        metas,
        &plan,
        work_items.items,
        agg_calls,
        n_workers,
        t,
        false,
    )) |result| return result;

    var pair_record_path: ?RecordAdmission = null;
    if (explain) {
        pair_record_path = try inlinePairAnswer(
            gpa,
            arena,
            args,
            metas,
            &plan,
            work_items.items,
            agg_calls,
            group_by_keys,
            group_outputs,
            n_workers,
            t,
            true,
        );
    } else if (try inlinePairAnswer(
        gpa,
        arena,
        args,
        metas,
        &plan,
        work_items.items,
        agg_calls,
        group_by_keys,
        group_outputs,
        n_workers,
        t,
        false,
    )) |result| return result;

    var integer_needs_union = false;
    if (!explain) if (try inlineIntegerAnswer(
        gpa,
        arena,
        &args,
        metas,
        &plan,
        work_items.items,
        agg_calls,
        group_by_keys,
        group_outputs,
        n_workers,
        t,
        .{ .pending = &integer_needs_union },
        false,
    )) |result| return result;

    if (!explain) if (try inlineByteTopAnswer(
        gpa,
        arena,
        args,
        metas,
        &plan,
        work_items.items,
        agg_calls,
        group_by_keys,
        group_outputs,
        n_workers,
        t,
        false,
    )) |result| return result;

    if (!explain) if (try inlineByteAnswer(
        gpa,
        arena,
        args,
        metas,
        &plan,
        work_items.items,
        agg_calls,
        group_by_keys,
        group_outputs,
        n_workers,
        t,
        false,
    )) |result| return result;

    var plan_inputs: PlanInputs = .{
        .args = args,
        .metas = metas,
        .work = work_items.items,
        .calls = agg_calls,
        .keys = group_by_keys,
        .outputs = group_outputs,
        .filter_cols = plan.filter_cols,
        .workers = n_workers,
        .filter = filter_opt,
        .readers = for (args.inputs) |in| {
            if (in.readerBacked()) break true;
        } else false,
    };
    const msd_candidate = (try inlineMsdAnswer(gpa, arena, args, metas, &plan, work_items.items, agg_calls, group_by_keys, group_outputs, n_workers, t, true)) != null;
    const msd_probe = if (msd_candidate) try msdProbeHeaders(args, metas, work_items.items, group_by_keys.?, explain) else null;
    var planning_released = false;
    var ndv_stat: ?NdvStat = null;
    var probe_facts: PlanFacts = .{};
    var planning_why: ?@FieldType(Planning, "why") = null;
    // Freed once the dense tables are built, or as soon as the plan cannot use it.
    var domain: ?agg_dense.Domain = null;
    defer if (domain) |*d| d.deinit(gpa);
    if (args.ndv_policy) if (group_by_keys) |keys| {
        // Prefix discovery takes precedence; refining a global group bound cannot improve that decision.
        const first = planAggregate(plan_inputs).dispatch.strategy;
        const want = args.dense and agg_dense.shapeOk(agg_calls, keys);
        // A reader's union is read before its scan can start: only where some choice can turn on it (a cut the bound
        // can drop, the dense fold's domain, count(DISTINCT) pairs). Mapped inputs union as they always have.
        const union_matters = first == .sketch or want or for (agg_calls) |c| {
            if (c.func == .count_distinct) break true;
        } else false;
        // A global group bound refines nothing for prefix discovery, unless the footers say the codes may resolve few
        // entries in all: the cost rules may then group plainly (`fewEntries`), and the union decides it.
        const guess = ndv.footerEntries(metas, keys) orelse std.math.maxInt(u64);
        const prefix = first == .first_keys and guess > few_entries;
        const allow_union = args.ndv_union and !prefix and (!plan_inputs.readers or union_matters);
        planning_why = if (!args.ndv_union)
            .union_disabled
        else if (prefix) .prefix_cut else if (!allow_union) .reader_no_choice else null;
        // Beside a reader the union may be read for the fold alone: then not where the fold would decline it.
        const fold_only = plan_inputs.readers and first != .sketch and for (agg_calls) |c| {
            if (c.func == .count_distinct) break false;
        } else true;
        const fold: ndv.FoldOnly = if (fold_only) n_workers else null;
        const ranges = try ndv.probeRanges(arena, metas, keys, args.max_memory, true, allow_union, want, fold);
        // A reader holds what it probes beside its window, page by page as it reads it: past the cap its inputs plan
        // from their footers, as they did with no probe. A mapped input reads its dictionaries as it always has.
        const page = std.heap.pageSize();
        var probe_bytes: u64 = msd_probe orelse 0;
        for (ranges) |r| if (args.inputs[r.file].readerBacked()) {
            probe_bytes +|= std.mem.alignForward(u64, r.end, page) - std.mem.alignBackward(u64, r.start, page);
        };
        const probe_ok = probe_bytes <= args.probe_cap orelse ndv.probeCap(args.max_memory);
        if (plan_inputs.readers) {
            probe_facts.probe_ranges = ranges.len;
            probe_facts.probe_bytes = probe_bytes;
            probe_facts.probe_capped = !probe_ok;
        }
        const files = try arena.alloc(ndv.File, args.inputs.len);
        // Dictionaries are read from a mapped file, or from a reader's buffer once its probe of them is in. Explain
        // reads a reader's input through its mapping, as the probe would read it. Without either (S3, a probe past
        // its cap, or a reader no probe was asked of) an input plans from its footer.
        for (args.inputs, files) |input, *file| {
            const waits = input.readerBacked() and input.dict_wait != null;
            const probed = input.readerBacked() and probe_ok and (waits or explain);
            const bytes = if (waits) input.bytes else input.plan_bytes orelse input.bytes;
            file.* = .{
                .bytes = bytes,
                .local = !std.mem.startsWith(u8, input.name, "s3://") and (input.gate == null or probed) and
                    (input.logical_size == 0 or input.logical_size == bytes.len),
                .probed = probed,
                .wait = if (probed and waits) input.dict_wait else null,
            };
        }
        if (!explain) if (args.dict_probe) |dp| for (ranges) |r| {
            const in = args.inputs[r.file];
            if (in.gate == null or (in.readerBacked() and probe_ok)) try dp.add(dp.ctx, r.file, r.rg, r.start, r.end);
        };
        // The reader reads the probes first, then streams row groups into its window while the dictionaries union.
        if (!explain) if (args.start_reads) |s| try s.start(s.ctx);
        ndv_stat = try ndv.collectRetaining(
            gpa,
            arena,
            files,
            metas,
            keys,
            n_workers,
            args.max_memory,
            true,
            allow_union,
            if (want) &domain else null,
            // A prefix plan reads the union only for `fewEntries`: none past its entries, and none past its values.
            .{ .fold_only = fold_only, .limit = if (first == .first_keys) few_union else null },
        );
        if (!explain) if (args.start_reads) |s| if (s.planned) |planned| {
            planned(s.ctx);
            planning_released = true;
        };
        const st = ndv_stat.?;
        probe_facts.planning = .{
            .source = switch (st.source) {
                .unknown => .footers,
                .dictionary_headers => .dictionary_headers,
                .dictionary_union => .dictionary_union,
            },
            .why = if (st.union_complete)
                (if (plan_inputs.readers) .reader_probe else .mapped)
            else if (planning_why) |w|
                w
            else if (plan_inputs.readers and !probe_ok)
                .probe_capped
            else if (st.fold_declined)
                .fold_declines
            else if (st.union_budget_exceeded)
                .union_budget
            else if (st.union_attempted) .union_incomplete else .no_dictionaries,
        };
    };
    if (!explain) if (args.start_reads) |s| try s.start(s.ctx);
    plan_inputs.ndv_stat = ndv_stat;
    if (!explain and integer_needs_union) {
        const bounds: IntegerCountBounds = .{ .refined = ndv_stat };
        if (try inlineIntegerAnswer(
            gpa,
            arena,
            &args,
            metas,
            &plan,
            work_items.items,
            agg_calls,
            group_by_keys,
            group_outputs,
            n_workers,
            t,
            bounds,
            true,
        )) |_| {
            // This owner does not retain the union. Release it before its independently quoted records draw.
            if (domain) |*d| d.deinit(gpa);
            domain = null;
            if (try inlineIntegerAnswer(
                gpa,
                arena,
                &args,
                metas,
                &plan,
                work_items.items,
                agg_calls,
                group_by_keys,
                group_outputs,
                n_workers,
                t,
                bounds,
                false,
            )) |answer| return answer;
        }
    }
    // Generic composite states share their cache-bound admission with execution and EXPLAIN.
    const dense_supported = if (domain) |*d|
        d.axes.len == 1 or agg_dense.countOnly(agg_calls) or agg_dense.sumCall(agg_calls) != null or
            (!agg_dense.orderSensitive(agg_calls) and agg_dense.numericFits(d.ids(), agg_calls))
    else
        false;
    var dense_profitable = true;
    if (args.encoded and dense_supported) if (domain) |*d| {
        const initial = planAggregate(plan_inputs).dispatch;
        if (d.globalFits(n_workers) and allRescannable(args.inputs) and !initial.use_blocks) {
            const stride = expr_agg.fixedGroupStride(group_by_keys.?) orelse 0;
            const quote = agg_dense.charge(
                d,
                n_workers,
                agg_calls,
                ndv_stat.?.rows,
                stride,
                denseLimit(args, agg_calls, group_outputs),
            ).total;
            // Uniform bounds can hide skew. Before replacing dense by survivor-sized state, require a proven
            // share or count a sample. A budget retry disables this cost rule and can restore the lanes.
            if (args.plain_rules and args.filter != null and passShare(plan_inputs) <= selective_share and
                denseLimit(args, agg_calls, group_outputs) != null and
                quote > selectedGroupBytes(ndv_stat.?, agg_calls.len, n_workers, passShare(plan_inputs)))
            {
                var share = provenPassShare(plan_inputs);
                if (share > selective_share) {
                    plan_inputs.sampled_pass = try sampledPassShare(
                        gpa,
                        arena,
                        &plan,
                        metas,
                        args.inputs,
                        work_items.items,
                        .{
                            .fast_levels = args.fast_levels,
                            .level_runs = args.level_runs,
                            .encoded = args.encoded,
                            .expand_limit = args.max_memory,
                        },
                        args.decode_limit,
                    );
                    plan_inputs.sample_unread = plan_inputs.sampled_pass == null;
                    share = if (plan_inputs.sampled_pass) |sampled| share * sampled else 1;
                }
                if (share <= selective_share)
                    dense_profitable = quote <= selectedGroupBytes(ndv_stat.?, agg_calls.len, n_workers, share);
            }
            if (dense_profitable) plan_inputs.dense_bytes = quote;
        }
    };
    var scan_plan = planAggregate(plan_inputs);
    var selected_record_path: ?RecordAdmission = null;
    // Keep the accepted dense choice. Sparse typed identities otherwise have one shared record/finish quote.
    const payload_top = if (agg_plan.OwnerProgram.init(agg_calls)) |p|
        p.len != 0 and p.distinct_arg == null and args.result_order.limit != null
    else
        false;
    if (plan_inputs.dense_bytes == null or !dense_profitable or payload_top) {
        if (explain) {
            selected_record_path = try inlineSelectedCount(
                gpa,
                arena,
                args,
                metas,
                &plan,
                work_items.items,
                agg_calls,
                group_by_keys,
                group_outputs,
                if (domain) |*d| d else null,
                ndv_stat,
                if (plan_inputs.sampled_pass) |sampled|
                    provenPassShare(plan_inputs) * sampled
                else
                    passShare(plan_inputs),
                n_workers,
                t,
                true,
            );
        } else if (try inlineSelectedCount(
            gpa,
            arena,
            args,
            metas,
            &plan,
            work_items.items,
            agg_calls,
            group_by_keys,
            group_outputs,
            if (domain) |*d| d else null,
            ndv_stat,
            if (plan_inputs.sampled_pass) |sampled|
                provenPassShare(plan_inputs) * sampled
            else
                passShare(plan_inputs),
            n_workers,
            t,
            false,
        )) |answer| return answer;
    }
    var packed_record_path: ?RecordAdmission = null;
    // Keep the established small-domain table/dense choice; owners replace a multi-pass count cut.
    if (plan_inputs.readers or scan_plan.dispatch.strategy == .sketch or !dense_profitable) if (domain) |*d| {
        if (explain) {
            packed_record_path = try inlinePackedAnswer(
                gpa,
                arena,
                args,
                metas,
                &plan,
                work_items.items,
                agg_calls,
                group_by_keys,
                group_outputs,
                d,
                n_workers,
                t,
                true,
            );
        } else if (try inlinePackedAnswer(
            gpa,
            arena,
            args,
            metas,
            &plan,
            work_items.items,
            agg_calls,
            group_by_keys,
            group_outputs,
            d,
            n_workers,
            t,
            false,
        )) |answer| return answer;
    };
    var msd_args = args;
    msd_args.msd_records = msd_probe != null;
    // Low-NDV composite keys benefit from reducing rows directly. This existing bound only declines a layout.
    if (args.msd_records_min_rows != 0) if (ndv_stat) |st| if (st.hi < st.rows / 4) {
        msd_args.msd_records = false;
    };
    if (msd_args.msd_records) msd_args.msd_working_bytes = msdWorkspace(args, metas, work_items.items, group_by_keys.?, n_workers, explain);
    if (msd_args.msd_working_bytes == null) msd_args.msd_records = false;
    if (planning_released) {
        if (msd_args.start_reads) |*starter| starter.planned = null;
    }
    if (!explain) if (inlineMsdAnswer(gpa, arena, msd_args, metas, &plan, work_items.items, agg_calls, group_by_keys, group_outputs, n_workers, t, false) catch |e| switch (e) {
        error.OutOfMemory, error.RetainedEncodingUnsupported, error.RetainedOwnershipViolation => return error.ExceededMemoryBudget,
        else => return e,
    }) |result| return result;
    if (!explain and !dense_profitable) if (args.taken) |taken| taken.insert(.plain_rule);
    if (scan_plan.wants_sample) {
        const options: consumer.DecodeOptions = .{
            .fast_levels = args.fast_levels,
            .level_runs = args.level_runs,
            .encoded = args.encoded,
            .expand_limit = args.max_memory,
        };
        const work = work_items.items;
        const limit = args.decode_limit;
        plan_inputs.sampled_pass = try sampledPassShare(gpa, arena, &plan, metas, args.inputs, work, options, limit);
        plan_inputs.sample_unread = plan_inputs.sampled_pass == null;
        scan_plan = planAggregate(plan_inputs);
    }
    scan_plan.facts.probe_ranges = probe_facts.probe_ranges;
    scan_plan.facts.probe_bytes = probe_facts.probe_bytes;
    scan_plan.facts.probe_capped = probe_facts.probe_capped;
    scan_plan.facts.planning = probe_facts.planning;
    if (@import("builtin").is_test and !args.partagg and ndv_stat == null)
        try testing.expectEqualDeep(referenceDispatch(plan_inputs), scan_plan.dispatch);
    const decision = scan_plan.dispatch;
    const part_on = decision.strategy == .partitioned_hash;
    const count_columns: ?agg_plan.Columns = if (decision.count_columns)
        try plan.forCalls(arena, &.{})
    else
        null;
    if (explain) {
        const record_path = string_record_path orelse pair_record_path orelse selected_record_path orelse packed_record_path orelse
            try inlineDistinctAnswer(
                gpa,
                arena,
                args,
                metas,
                &plan,
                work_items.items,
                agg_calls,
                n_workers,
                t,
                true,
            ) orelse try inlineMsdAnswer(
            gpa,
            arena,
            msd_args,
            metas,
            &plan,
            work_items.items,
            agg_calls,
            group_by_keys,
            group_outputs,
            n_workers,
            t,
            true,
        ) orelse try inlineIntegerAnswer(
            gpa,
            arena,
            &args,
            metas,
            &plan,
            work_items.items,
            agg_calls,
            group_by_keys,
            group_outputs,
            n_workers,
            t,
            .{ .refined = ndv_stat },
            true,
        ) orelse
            try inlineByteTopAnswer(
                gpa,
                arena,
                args,
                metas,
                &plan,
                work_items.items,
                agg_calls,
                group_by_keys,
                group_outputs,
                n_workers,
                t,
                true,
            ) orelse
            try inlineByteAnswer(gpa, arena, args, metas, &plan, work_items.items, agg_calls, group_by_keys, group_outputs, n_workers, t, true);
        var explained_items = work_items.items.len;
        // The ordinary owner must quote the same independent ranges it will actually schedule. Inline owners
        // have already quoted their own work layout and do not use this row-subgroup plan.
        if (record_path == null and group_by_keys != null and !orderSensitive(agg_calls) and
            !decision.use_blocks and domain == null and
            (decision.strategy == .plain_hash or decision.strategy == .partitioned_hash))
        {
            var quote_budget: core_memory.SharedBudget = .{ .limit = args.max_memory };
            var quote_charge: core_memory.Charged = .{ .child = gpa, .budget = args.ledger orelse &quote_budget };
            var quote_arena = std.heap.ArenaAllocator.init(quote_charge.allocator());
            defer quote_arena.deinit();
            if (splitRowGroups(quote_arena.allocator(), args, metas, &plan, work_items.items, @min(requested, by_bytes)) catch null) |split| {
                explained_items = split.len;
                n_workers = @min(@min(requested, by_bytes), split.len);
                scan_plan.dispatch.tables = n_workers;
            }
        }
        const names = try arena.alloc([]const u8, plan.columns.read.len);
        const labels = try metadata.leafLabels(arena, meta0);
        for (labels.names, names, 0..) |label, *name, i| {
            name.* = if (label) |n| try arena.dupe(u8, n) else try std.fmt.allocPrint(arena, "#{d}", .{i});
        }
        return .{
            .plan = scan_plan,
            .column_names = names,
            .columns = plan.columns,
            .count_columns = count_columns,
            .workers = if (record_path) |path| switch (path.layout) {
                .integer_group_stream,
                .integer_sum_top_h,
                .integer_count_top_h,
                .packed_count_top_h,
                .integer_distinct_top_h,
                .pair_distinct,
                => @min(n_workers, owner_groups.max_workers),
                else => n_workers,
            } else n_workers,
            .work_items = explained_items,
            .record_path = record_path,
            .dense = record_path == null and decision.strategy == .plain_hash and
                if (plan_inputs.dense_bytes) |bytes|
                    bytes <= if (args.ledger) |l| l.available() else args.max_memory
                else
                    false,
        };
    }
    // Tables still share one pool. Only a prepaid private plan's decoders protect funded worker floors.
    var own_budget = expr_agg.SharedBudget{ .limit = args.max_memory };
    const group_budget = args.ledger orelse &own_budget;
    // Non-rescannable sources must diagnose while their bytes are held, beside live peer workers.
    // Reserve the error-only quota before any of those workers or tables can draw.
    if (!allRescannable(args.inputs)) if (args.failure_probe) |p| {
        try p.reserveStream(group_budget, streamProbeBytes(args.inputs, metas, &plan));
    };
    defer if (args.failure_probe) |p| p.releaseStream();
    // Header walks and dictionary backing are charged to the plan, and released only after every range joins.
    // Optional-plan refusal never poisons worker decode allocators or changes the established fallback.
    var subgroup_charge: core_memory.Charged = .{ .child = gpa, .budget = group_budget };
    var subgroup_arena = std.heap.ArenaAllocator.init(subgroup_charge.allocator());
    defer subgroup_arena.deinit();
    var worker_work = work_items.items;
    if (group_by_keys != null and !orderSensitive(agg_calls) and !decision.use_blocks and domain == null and
        (decision.strategy == .plain_hash or decision.strategy == .partitioned_hash))
    {
        const split_span = profile.Span.begin(prof);
        if (splitRowGroups(subgroup_arena.allocator(), args, metas, &plan, work_items.items, @min(requested, by_bytes)) catch null) |split| {
            worker_work = split;
            n_workers = @min(@min(requested, by_bytes), worker_work.len);
        } else _ = subgroup_arena.reset(.free_all);
        // `plan` is the scan-count marker. Bill this work to planning without inventing another scan or I/O job.
        split_span.end(.plan_ranges, profile.args(.{}));
    }
    // Shared optional header memo: charged separately so a declined hint cannot poison decoder flags.
    var hint_charge: core_memory.Charged = .{ .child = std.heap.page_allocator, .budget = group_budget };
    var cache_hints: consumer.CacheHints = .{ .allocator = hint_charge.allocator() };
    defer cache_hints.deinit();
    if (args.auto_decode_batches and args.decode_batch_rows == 0 and args.expr_batch_rows != 0 and
        consumer.cacheHintsWanted(agg_calls)) cache_hints.initShards(n_workers) catch {};
    var private_decode: PrivateDecode = .{};
    // Declared before region cleanup: their actual allocations go before their funding returns to the query.
    defer private_decode.release();
    const workers = try arena.alloc(Worker, n_workers);
    for (workers) |*w| {
        w.region = null;
        w.scratch_region = null;
    }
    // A process about to exit leaves the regions to it: unmapping them delays the answer. A failed scan may be run
    // again (`runMultiAggregate`), so it gives them back.
    defer if (!args.leave_regions) releaseRegions(workers);
    errdefer releaseRegions(workers);
    var decode_budget: ?consumer.DecodeBudget = if (args.decode_limit) |l|
        .{ .limit = l, .workers = n_workers }
    else
        null;
    // One budget shared by every worker table, not per-worker quotas: work is claimed off a shared cursor, so which
    // worker meets the group-heavy row groups is unknowable in advance — fixed quotas made `-j2` reject queries `-j1`
    // ran on identical data. Fully initialized before any worker exists, so none can insert against an unpublished
    // budget.
    // A refusal chain's last scan decodes beside the query's ledger, on a ledger of its own (`narrowed`).
    var lean_budget = expr_agg.SharedBudget{ .limit = core_memory.lean_decode };
    // Shared partitions retain their own reservation slack alongside the workers' local tables.
    group_budget.block = expr_agg.SharedBudget.blockFor(
        args.max_memory,
        n_workers + if (part_on) partagg.n_parts else @as(usize, 0),
    );
    const distinct_wide_parts = try arena.alloc(bool, agg_calls.len);
    for (agg_calls, distinct_wide_parts) |call, *wide| wide.* = call.func == .count_distinct and
        scalarDistinctWideParts(call.arg.?, metas, work_items.items);
    for (work_items.items) |item| {
        for (item.accumulators, 0..) |*acc, ai| {
            if (acc.* == .distinct) if (acc.distinct.heap()) |ds| {
                if (group_by_keys == null and n_workers > 1) {
                    if (distinct_wide_parts[item.agg_start + ai])
                        try ds.initStringPartitions(gpa, group_budget)
                    else
                        try ds.initPartitions(gpa, group_budget);
                } else {
                    ds.shared = group_budget;
                }
            };
        }
    }

    // GROUP BY tables. One per worker, unless results depend on the order partials merge in and order is asked for:
    // then one per fixed block of the work list, so which rows fold into which table, and the order the tables merge
    // in, doesn't depend on the number of workers or their timing (see `BlockMerge`).
    var block_bounds: ?[]usize = null;
    const use_blocks = decision.use_blocks;
    const n_tables = if (worker_work.ptr != work_items.items.ptr) n_workers else decision.tables;
    if (use_blocks) {
        const bounds = try arena.alloc(usize, n_tables + 1);
        for (bounds, 0..) |*b, i| b.* = i * work_items.items.len / n_tables;
        block_bounds = bounds;
    }
    // A dense fold (below) needs one table more, after the workers': the one its lanes merge into.
    const dense_wanted = dense_supported and dense_profitable and domain != null and domain.?.globalFits(n_workers) and
        decision.strategy == .plain_hash and !use_blocks and !part_on;
    const all_tables = try arena.alloc(expr_agg.GroupTable, n_tables + @intFromBool(dense_wanted));
    const group_tables = all_tables[0..n_tables];
    // Integer and float keys are a fixed-width image: the per-row lookup mixes those bytes in an open-addressed
    // table instead of copying each new key into a string map. String and decimal keys stay on that map.
    const fixed_stride: u8 = if (group_by_keys) |ks| expr_agg.fixedGroupStride(ks) orelse 0 else 0;
    for (all_tables) |*gt| {
        // Zero local ceiling: everything is drawn from the shared pool, so an idle table reserves nothing others
        // could use.
        gt.* = expr_agg.GroupTable.init(gpa, 0);
        gt.shared = group_budget;
        gt.fixed_stride = fixed_stride;
        // A lone SUM's ranking merge paid more to unpack its state than the smaller scan saved.
        if ((!dense_wanted or agg_dense.countOnly(agg_calls)) and !use_blocks and
            (agg_calls.len != 1 or agg_calls[0].func == .count))
            gt.compact.configure(agg_calls);
    }
    // A process about to exit (`leave_regions`) leaves the tables to it: freeing tens of millions of keys one by one
    // is serial time the answer would wait for. Builds that check for leaks free them, so a real leak still shows.
    // Cleared once an answer is built that the query encodes next and the ledger has no room for beside the tables.
    var leave_tables = args.leave_regions and !std.debug.runtime_safety;
    defer if (!leave_tables) for (all_tables) |*gt| gt.deinit();
    errdefer if (leave_tables) for (all_tables) |*gt| gt.deinit();
    var block_cursor = std.atomic.Value(usize).init(0);
    var merged_table = expr_agg.GroupTable.init(gpa, 0);
    merged_table.shared = group_budget;
    merged_table.fixed_stride = fixed_stride;
    defer if (!leave_tables) merged_table.deinit();
    errdefer if (leave_tables) merged_table.deinit();
    var part_state: ?partagg.PartAgg = null;
    defer if (!leave_tables) if (part_state) |*p| p.deinit();
    // A refused scan runs again: what it held goes back, to the OS and to the query's ledger.
    errdefer if (leave_tables) if (part_state) |*p| p.deinit();
    defer if (part_state) |*p| {
        if (p.private_reserved) if (args.taken) |taken| taken.insert(.private_runs);
    };
    // Fixed-width keys fold into an open-addressed table cheap enough that moving near-unique ones to runs cost more
    // than it saved; string keys, copied into a byte map per worker, gain.
    const rescannable = allRescannable(args.inputs);
    // Exact dictionary domains fold by global id when the plan groups in per-worker
    // tables: no group lookups per row group and no hash merge. Taken only when walking every worker's lanes costs no
    // more than the lookups it replaces (one per dictionary entry per row group), and when the domain and every lane
    // fit the shared budget, drawn before any worker starts.
    const dense_cut = denseLimit(args, agg_calls, group_outputs);
    const dense_rule = if (plan_inputs.dense_bytes != null and decision.strategy == .plain_hash) rule: {
        var ordinary = plan_inputs;
        ordinary.dense_bytes = null;
        break :rule planAggregate(ordinary).dispatch.strategy != .plain_hash;
    } else false;
    if (dense_rule) if (args.taken) |taken| taken.insert(.plain_rule);
    var dense_identity: ?key_pack.Plan = null;
    defer if (dense_identity) |*identity| identity.deinit(gpa);
    var dense_lanes: []agg_dense.Lanes = &.{};
    var dense_charge: usize = 0;
    defer group_budget.release(dense_charge);
    defer for (dense_lanes) |*l| l.deinit(gpa);
    // The table the lanes merge into is reserved with them, and handed to it as it is built.
    var dense_table_charge: usize = 0;
    if (dense_wanted) dense: {
        const d = &domain.?;
        if (!rescannable) break :dense;
        const quote = agg_dense.charge(d, n_workers, agg_calls, ndv_stat.?.rows, fixed_stride, dense_cut);
        dense_table_charge = quote.table;
        dense_charge = group_budget.drawExact(quote.total) orelse {
            // Only the lanes justified this plain plan: retry the displaced strategy before consuming rows.
            if (dense_rule) return error.ExceededMemoryBudget;
            break :dense;
        };
        var positions: ?agg_dense.Ordinals = null;
        if (d.axes.len > 1 and agg_dense.sumCall(agg_calls) != null) {
            dense_identity = try key_pack.Plan.init(gpa, group_by_keys.?, d);
            if (dense_identity == null or dense_identity.?.kind() != .dense_u32) break :dense;
            if (ndv_stat.?.rows < @as(u64, 1) << 31) {
                if (work_items.items.len > d.axes[0].trans.len) break :dense;
                const starts = try arena.alloc(u32, work_items.items.len + 1);
                starts[0] = 0;
                var total: u64 = 0;
                for (work_items.items, 0..) |item, i| {
                    const rows = metas[item.file].row_groups.items[item.rg].num_rows;
                    total = std.math.add(u64, total, @intCast(@max(0, rows))) catch break :dense;
                    if (total >= @as(u64, 1) << 31) break :dense;
                    starts[i + 1] = @intCast(total);
                }
                positions = agg_dense.Ordinals.init(starts) orelse break :dense;
                if (positions.?.rows() != ndv_stat.?.rows) break :dense;
            }
        }
        dense_lanes = try arena.alloc(agg_dense.Lanes, n_workers);
        for (dense_lanes) |*l| l.* = .{
            .domain = d,
            .calls = agg_calls,
            .rows = ndv_stat.?.rows,
            .positions = positions,
        };
        if (args.taken) |taken| taken.insert(.dense);
    }
    if (dense_lanes.len == 0) {
        group_budget.release(dense_charge);
        dense_charge = 0;
        dense_table_charge = 0;
        if (dense_identity) |*identity| identity.deinit(gpa);
        dense_identity = null;
        if (dense_rule) return error.ExceededMemoryBudget;
        if (domain) |*d| {
            d.deinit(gpa);
            domain = null;
        }
    }
    const spill_on = dense_lanes.len == 0 and !part_on and args.spill and
        decision.strategy == .plain_hash and !use_blocks and fixed_stride == 0 and partAggSupported(args, agg_calls, group_by_keys != null) and rescannable;
    if (args.taken) |taken| {
        if (spill_on) taken.insert(.spill);
        // Chosen by the cost rules rather than asked for, a partitioned plan has the plain one to fall back to.
        if (part_on and !args.partagg and rescannable) taken.insert(.partitioned);
        const shared = decision.strategy == .plain_hash or part_on;
        if (shared and n_workers > 1 and rescannable) taken.insert(.worker_tables);
        if (decision.strategy == .plain_hash and !use_blocks and partAggSupported(args, agg_calls, true) and
            (if (group_outputs) |outs| countCut(outs, agg_calls, args.result_order) == null else true))
            taken.insert(.partitions_fit);
        if (rescannable and (scan_plan.reasons.contains(.few_dictionary_entries) or
            scan_plan.reasons.contains(.selective_filter)))
        {
            var cut_inputs = plan_inputs;
            cut_inputs.args.plain_rules = false;
            if (!std.meta.eql(planAggregate(cut_inputs).dispatch, decision)) taken.insert(.plain_rule);
        }
    }
    // A partitioned plan the cost rules chose (long strings, worker-copy pressure) merges into shared partition
    // tables; `ZPQ_PARTAGG=1` and a worker that moves at run time append to runs.
    const armed = spill_on;
    if (part_on or spill_on) {
        part_state = try partagg.PartAgg.init(
            gpa,
            group_budget,
            agg_calls,
            fixed_stride,
            mergeAccOwned,
            args.part_cap,
            args.part_probe,
            n_workers,
            part_on and !args.partagg,
        );
        part_state.?.compact = group_tables[0].compact.stride != 0;
        if (part_state.?.compact) for (part_state.?.parts) |*p| p.table.compact.configure(agg_calls);
        if (part_on and !args.partagg and args.private_runs and rescannable and n_workers > 1 and
            agg_calls.len == 1 and agg_calls[0].func == .count)
        {
            if (group_by_keys) |keys| if (keys.len > 1) if (ndv_stat) |stat| {
                const run_width = @max(stat.key_bytes, stat.run_key_bytes);
                if (stat.string_keys and stat.key_bytes >= 32 and stat.rows >= 65536) {
                    private_decode = try PrivateDecode.init(
                        arena,
                        group_budget,
                        n_workers,
                        args.decode_limit,
                        stat.run_dictionary_peak,
                    );
                    if (private_decode.held > 0 and part_state.?.reservePrivate(stat.rows, run_width) and
                        try private_decode.fundSamples(arena, &part_state.?, run_width))
                    {
                        part_state.?.private_rows = stat.rows;
                        part_state.?.private_key_bytes = run_width;
                        part_state.?.decoder_floors = private_decode.workers;
                        for (group_tables, private_decode.samples) |*table, *sample| table.shared = sample;
                    } else {
                        if (part_state.?.private_reserved) part_state.?.cancelPrivate();
                        private_decode.release();
                    }
                }
            };
        }
        part_state.?.spill_groups = args.spill_groups;
        part_state.?.spill_rows = args.spill_rows;
    }
    // `.auto` without a dictionary bound lets each worker decide from its first rows (`pairsPayRuntime`).
    const pairs_from_start = switch (args.distinct_pairs) {
        .auto => pairsPay(ndv_stat),
        .on => true,
        .off => false,
    };
    const pairs_call: ?usize = if (args.distinct_pairs != .off and decision.strategy == .plain_hash and !use_blocks and
        rescannable)
        distinctPairsCall(agg_calls, fixed_stride)
    else
        null;
    if (pairs_call != null) if (args.taken) |taken| taken.insert(.pairs);
    var pair_sinks: []expr_agg.DistinctPairs = &.{};
    defer for (pair_sinks) |*ps| ps.deinit();
    if (pairs_call) |ai| {
        pair_sinks = try arena.alloc(expr_agg.DistinctPairs, n_tables);
        for (pair_sinks, group_tables) |*ps, *gt| {
            ps.* = .{
                .gpa = gpa,
                .budget = group_budget,
                .table = gt,
                .agg_idx = ai,
                .active = pairs_from_start,
                .allow_coded_sets = args.distinct_pairs == .auto,
            };
        }
    }
    var block_merge: ?BlockMerge = if (use_blocks) .{
        .tables = group_tables,
        .merged = &merged_table,
        .calls = agg_calls,
        .gpa = gpa,
        .done = blk: {
            const d = try arena.alloc(std.atomic.Value(bool), n_tables);
            @memset(d, .init(false));
            break :blk d;
        },
        .ahead = n_workers,
    } else null;

    var winners: WinnerCharge = .{ .ledger = if (group_by_keys == null) args.ledger else group_budget };
    errdefer winners.settle(0);
    defer if (group_by_keys != null and !leave_tables) winners.settle(0);
    var work_cursor = std.atomic.Value(usize).init(0);
    for (workers, 0..) |*w, wi| {
        w.* = .{
            .gpa = gpa,
            .inputs = args.inputs,
            .metas = metas,
            .work = worker_work,
            .cursor = &work_cursor,
            .agg_calls = agg_calls,
            .plan = &plan,
            .decode_options = .{
                .fast_levels = args.fast_levels,
                .level_runs = args.level_runs,
                .encoded = args.encoded,
                .expand_limit = args.max_memory,
            },
            .expr_batch_rows = args.expr_batch_rows,
            .decode_batch_rows = args.decode_batch_rows,
            .auto_decode_batches = args.auto_decode_batches,
            .cache_hints = &cache_hints,
            .scan_workers = n_workers,
            .retire_after_run = args.leave_regions and (args.ledger != null or private_decode.held > 0) and
                switch (decision.strategy) {
                    .scalar, .plain_hash, .partitioned_hash => true,
                    .first_keys, .sketch => false,
                },
            .error_outputs = error_outputs,
            .error_group_keys = error_group_keys,
            .failure_probe = args.failure_probe,
            .profiler = args.profiler,
            .index = wi,
            .group_by_keys = group_by_keys,
            .group_tables = group_tables,
            .part = if (part_state) |*p| p else null,
            .pairs = if (pair_sinks.len > 0) &pair_sinks[wi] else null,
            .dense = if (dense_lanes.len > 0) &dense_lanes[wi] else null,
            .pairs_pilot_rows = args.pairs_pilot_rows,
            .pairs_rechecks = args.pairs_rechecks,
            .local = .{ .runs = if (part_state) |*p| &p.runs[wi] else null, .armed = armed },
            .blocks = block_bounds,
            .block_cursor = &block_cursor,
            .block_merge = if (block_merge) |*m| m else null,
            .items_per_rg = chunks_per_rg,
            .count_columns = count_columns,
            .decode_budget = if (decode_budget) |*b| b else null,
            .ledger = if (private_decode.held > 0)
                &private_decode.workers[wi]
            else if (args.charge_decode or args.ledger == null) args.ledger else &lean_budget,
            .winners = if (winners.ledger != null) &winners else null,
        };
    }

    // 5. Spawn, join, propagate first error. Time the whole parallel
    //    region as one wall-clock span (real elapsed decode), separate
    //    from the per-worker CPU sum in `core.decode_ns`.
    const t_decode = nowMonoNs();
    if (decision.count_agg == null) if (args.sketch_topk) |cfg| if (cfg.outcome) |o| {
        o.* = .ineligible;
    };
    const order = args.result_order;
    const passes: anyerror!void = switch (decision.strategy) {
        .first_keys => firstAppearanceCut(gpa, arena, workers, &work_cursor, group_tables, order, args.sketch_topk.?),
        .sketch => certifiedTopK(
            gpa,
            arena,
            workers,
            &work_cursor,
            group_tables,
            agg_calls,
            order,
            decision.count_agg.?,
            args.sketch_topk.?,
            decision,
        ),
        .scalar, .plain_hash, .partitioned_hash => runWorkers(workers),
    };
    // A cut's passes return their refusal themselves: what decode memory the workers drew is noted on the way out.
    passes catch |original| {
        const e = if (firstWorkerFailure(workers, args.failure_probe)) |f| chosen: {
            consumer.setDecodeFailure(f.site);
            break :chosen f.err;
        } else original;
        if (e == error.ExceededMemoryBudget) if (args.taken) |taken| {
            for (workers) |*w| if (decodeHeld(w) and rescannable) taken.insert(.decode_memory);
        };
        return e;
    };
    const t_decode_end = nowMonoNs();
    t.decode_wall_ns = @intCast(t_decode_end - t_decode);
    profile.record(prof, .scan, t_decode, t_decode_end, profile.args(.{n_workers}));
    const decode_held = for (workers) |*w| {
        if (decodeHeld(w)) break true;
    } else false;
    // The last pass is done: nothing decodes into the regions again, so the merge does not hold them. Under a ledger
    // they go even for a process about to exit, as their charge would sit beside the merge and the answer.
    if (!args.leave_regions or args.ledger != null or private_decode.held > 0) releaseRegionsParallel(workers);
    private_decode.release();
    cache_hints.deinit();
    if (firstWorkerFailure(workers, args.failure_probe)) |failure| {
        const e = failure.err;
        if (e == error.ExceededMemoryBudget) if (args.taken) |taken| {
            if (decode_held and rescannable) taken.insert(.decode_memory);
            if (taken.contains(.worker_tables)) {
                if ((decision.strategy == .plain_hash and holdCopies(group_tables)) or
                    try oneWorkerCuts(arena, plan_inputs)) taken.insert(.one_table_may_fit);
            }
        };
        consumer.setDecodeFailure(failure.site);
        return e;
    }
    // Past the scan a refusal is the merge's, which one worker's table goes without (a scan that answers drops this).
    if (args.taken) |taken| taken.insert(.one_table_may_fit);
    // The merge and the answer may hold a fixed allowance past the budget, beside the tables they are built from:
    // the ceiling's slack (`memory.finalize_allowance`), so a small answer never refuses a query its tables fit.
    if (args.ledger != null) group_budget.limit += core_memory.finalize_allowance;
    defer if (args.ledger != null) {
        group_budget.limit -= core_memory.finalize_allowance;
    };
    const merge_span = profile.Span.begin(prof);
    // The lanes merge by id into the spare table; the lanes and the domain go as soon as it is built (to the OS with
    // the process, when it is about to exit, as the tables do). Row groups no lane took sit in the worker tables, which
    // then merge with it as usual.
    var dense_merged = false;
    var dense_verified = false;
    var dense_direct: ?*agg_dense.Lanes = null;
    // Left to the exit with the tables, but freed if a later refusal runs the scan again (`runMultiAggregate`).
    var left_lanes: []agg_dense.Lanes = &.{};
    var left_domain: ?agg_dense.Domain = null;
    errdefer {
        for (left_lanes) |*l| l.deinit(gpa);
        if (left_domain) |*d| d.deinit(gpa);
    }
    if (dense_lanes.len > 0) {
        dense_verified = for (group_tables) |gt| {
            if (gt.groupCount() != 0) break false;
        } else true;
        const dense_table = &all_tables[n_tables];
        const dense_keys = group_by_keys.?;
        var dense_lookup: usize = 0;
        for (dense_keys) |key| dense_lookup = @max(dense_lookup, key.col_ref.col_idx + 1);
        group_budget.release(dense_table_charge);
        dense_charge -= dense_table_charge;
        const cut = if (dense_cut) |h| only_lanes: {
            if (!agg_dense.countOnly(agg_calls) and dense_keys.len == 1) break :only_lanes null;
            for (group_tables) |*table| if (table.groupCount() != 0) break :only_lanes null;
            break :only_lanes @as(?usize, h);
        } else null;
        const dense_start = if (prof != null) nowMonoNs() else 0;
        const direct = only_lanes: {
            if (agg_dense.sumCall(agg_calls) == null or dense_keys.len < 2) break :only_lanes false;
            for (group_outputs.?) |out| if (out.derived != null) break :only_lanes false;
            for (group_tables) |gt| if (gt.groupCount() != 0) break :only_lanes false;
            break :only_lanes true;
        };
        if (direct) {
            dense_direct = try agg_dense.merge(gpa, arena, dense_lanes, n_workers);
        } else try agg_dense.intoTable(gpa, arena, dense_lanes, dense_keys, dense_table, dense_lookup, n_workers, cut);
        if (prof != null) profile.record(
            prof,
            .dense_fold,
            dense_start,
            nowMonoNs(),
            profile.args(.{ if (dense_direct) |d| d.groupCount() else dense_table.groupCount(), n_workers }),
        );
        // Direct answers borrow the lanes and domain until this frame returns.
        if (dense_direct == null) {
            if (leave_tables) {
                left_lanes = dense_lanes;
                left_domain = domain;
            } else {
                for (dense_lanes) |*l| l.deinit(gpa);
                domain.?.deinit(gpa);
            }
            dense_lanes = &.{};
            domain = null;
            group_budget.release(dense_charge);
            dense_charge = 0;
        }
        dense_merged = true;
    }
    // Coded sets stay on their ordinary union when no worker emitted a pair. Otherwise every complete identity
    // joins the same pair fold, including sets a coded chunk retained beside an active sink.
    var pairs_used = false;
    for (pair_sinks) |*ps| pairs_used = pairs_used or
        (ps.active and (!ps.allow_coded_sets or ps.hasPairs()));
    if (pairs_used) {
        try drainDistinctPairs(gpa, pair_sinks, group_tables, n_workers);
        try foldDistinctPairs(gpa, group_budget, pair_sinks, group_tables, pairs_call.?, agg_calls.len, n_workers);
    }
    // Once one worker has moved to the partition runs every table goes there, so each key is in one partition.
    const spilled = part_on or (armed and part_state.?.spilled.load(.monotonic));
    if (spilled) {
        const ps = &part_state.?;
        if (armed) for (workers) |*w| if (w.local.armed) try ps.flush(&w.local, &group_tables[w.index]);
        try ps.foldRuns(n_workers);
    }

    // 6. Merge per-work-item accumulators into one final slice.
    var accumulators = try arena.alloc(expr_agg.Accumulator, agg_calls.len);
    for (agg_calls, accumulators) |call, *acc| acc.* = expr_agg.Accumulator.init(call);
    errdefer freeOwnedAccumulatorStrings(gpa, accumulators);
    for (agg_calls, accumulators, 0..) |call, *acc, ci| if (call.func == .count_distinct) {
        const ds = try gpa.create(expr_agg.DistinctSet);
        ds.* = .{};
        acc.* = .{ .distinct = .fromSet(ds) };
        if (group_by_keys == null and n_workers > 1) {
            if (distinct_wide_parts[ci])
                try ds.initStringPartitions(gpa, group_budget)
            else
                try ds.initPartitions(gpa, group_budget);
        } else {
            ds.shared = group_budget;
        }
    };
    // These sets outlive `group_budget`, which lives in this frame: they give their reservations back to it before
    // it goes, and forget it.
    defer for (accumulators) |*acc| if (acc.* == .distinct) acc.distinct.detach();
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    var answer_charge: usize = 0;
    errdefer group_budget.release(answer_charge);
    var rows_in: i64 = 0;
    var rows_scanned: i64 = 0;
    var rows_matched: i64 = 0;
    var rgs_in: usize = 0;
    var rgs_pruned: usize = 0;
    var rgs_full_match: usize = 0;

    var group_col_types: ?[]const GroupColType = null;

    if (group_by_keys) |keys| {
        for (workers) |w| {
            rows_in += w.rows_in;
            rows_scanned += w.rows_scanned;
            rows_matched += w.rows_matched;
            rgs_in += w.rgs_in;
            rgs_pruned += w.rgs_pruned;
            rgs_full_match += w.rgs_full_match;
            t.core.decode_ns += w.timings.decode_ns;
            t.core.eval_ns += w.timings.eval_ns;
            t.core.encode_ns += w.timings.encode_ns;
        }

        // `group_refs` is the whole merge input, in table order: a filter that drops refs before this point still
        // folds only what remains. Blocks have already merged, in input order, into one table.
        //
        // Equal keys meet in a hash table instead of a sort on the key bytes. Long keys that share a prefix make
        // those comparisons the query. Worker maps store an 8-bit fingerprint, not the hash, so each ref is hashed
        // once here. One table already has distinct keys and only needs first-appearance order.
        //
        // Merge maps borrow source keys. Under a ledger the merge's maps, lists and scratch are drawn from it
        // (`MultiAggArgs.merge_memory`), the full merge's and a result cut's alike, so a cut never refuses a budget
        // the merge it stands in for answers; the accumulators' own values stay on `gpa`. A refusal here is the
        // merge's, which the one-worker rerun goes without.
        const lists = if (args.merge_memory) |m| m.allocator() else gpa;
        const result_cut = resultCut(group_outputs.?, agg_calls, args.result_order, args.unordered);
        const out_tables: []expr_agg.GroupTable = if (use_blocks)
            (&merged_table)[0..1]
        else if (dense_merged) blk: {
            for (group_tables) |gt| if (gt.groupCount() > 0) break :blk all_tables;
            break :blk all_tables[n_tables..];
        } else group_tables;
        // An answer cut to its first rows by a COUNT, descending, merges only the groups that could make the cut.
        if (result_cut == null or !result_cut.?.ranking_first)
            try premergeLargeDistinctSets(gpa, arena, out_tables, agg_calls, n_workers);
        // COUNT-only ranks go straight to parallel partition heaps. DISTINCT cardinality bounds can discard
        // expensive losing sets before the payload merge; that merge still runs on the requested workers.
        const first_parallel = n_workers > 1 and args.result_order.keys.len == 0 and
            args.result_order.having == null and args.result_order.hidden.len == 0;
        const first_k = if (args.result_order.limit) |limit|
            std.math.cast(usize, args.result_order.offset +| limit)
        else
            null;
        const candidates = if (first_parallel and first_k != null)
            try firstCandidatesParallel(lists, out_tables, first_k.?, n_workers)
        else if (n_workers == 1 or (result_cut != null and
            agg_calls[result_cut.?.a_idx].func == .count_distinct))
            try topKCandidates(arena, out_tables, group_outputs.?, agg_calls, args.result_order)
        else
            null;
        defer if (first_parallel) if (candidates) |kept| lists.free(kept);
        // One table already holds complete ranks; its top-H heap avoids materializing every losing group.
        const cut: ?[]const u32 = if (dense_direct) |d|
            try agg_dense.reached(arena, d, dense_cut)
        else if (n_workers == 1 and candidates == null and out_tables.len == 1)
            try resultLimitGroups(
                arena,
                &out_tables[0],
                group_outputs.?,
                agg_calls,
                args.result_order,
                args.unordered,
                null,
            )
        else
            null;
        var total_group_refs: usize = 0;
        if (cut) |ids| {
            total_group_refs = ids.len;
        } else if (candidates) |keys_kept| {
            total_group_refs = keys_kept.len * out_tables.len;
        } else for (out_tables) |gt| {
            total_group_refs += gt.groupCount();
        }
        const group_refs_buf = try lists.alloc(MergeGroupRef, total_group_refs);
        defer lists.free(group_refs_buf);
        var ref_i: usize = 0;
        if (cut == null and candidates == null) {
            finishGroupRanges(out_tables, group_refs_buf, null, n_workers, false);
            ref_i = total_group_refs;
        } else for (out_tables, 0..) |gt, ti| {
            if (cut) |ids| {
                if (ti == 0) for (ids) |gi| {
                    group_refs_buf[ref_i] = .{ .table = 0, .group = gi };
                    ref_i += 1;
                };
            } else if (candidates) |keys_kept| {
                for (keys_kept) |key| if (gt.findKey(key)) |gi| {
                    group_refs_buf[ref_i] = .{ .table = @intCast(ti), .group = gi };
                    ref_i += 1;
                };
            }
        }
        const group_refs = group_refs_buf[0..ref_i];

        const outputs = group_outputs.?;

        var key_types = try gpa.alloc(KeyType, keys.len);
        defer gpa.free(key_types);
        for (keys, 0..) |key_expr, idx| {
            key_types[idx] = keyTypeFromExpr(key_expr);
        }

        const col_types = try arena.alloc(GroupColType, outputs.len);
        for (outputs, col_types) |out, *ct| ct.* = switch (out.source) {
            .key => |k_idx| .{
                .nullable = true,
                .lane = switch (key_types[k_idx]) {
                    .i64, .u64 => .i64,
                    .f64 => .f64,
                    .string => .string,
                    .dec => .dec,
                },
                .dec = if (key_types[k_idx] == .dec) key_types[k_idx].dec else null,
                .source = if (out.derived != null) null else if (keys[k_idx] == .col_ref)
                    leafSchemaElem(meta0, keys[k_idx].col_ref.col_idx)
                else if (keys[k_idx].isBoolean()) boolean_answer else null,
            },
            .agg => |a_idx| .{
                .nullable = agg_calls[a_idx].func != .count,
                .lane = switch (agg_calls[a_idx].result) {
                    .i64 => .i64,
                    .f64 => .f64,
                    .bytes => .string,
                    .avg_f64 => if (agg_calls[a_idx].state) .avg else .f64,
                    .dec => .dec,
                    .avg_dec => if (agg_calls[a_idx].state) .avg_dec else .dec,
                },
                .dec = switch (agg_calls[a_idx].result) {
                    .dec, .avg_dec => expr_agg.resultDec(agg_calls[a_idx]),
                    else => null,
                },
                .source = agg_sources[a_idx],
            },
        };
        group_col_types = col_types;

        var slots: std.ArrayList(MergedSlot) = .empty;
        defer slots.deinit(lists);
        // Accumulators moved out of the source tables when several tables share keys. Empty when there is one table:
        // its groups are already distinct, so rows read that table directly.
        var merged_accs: std.ArrayList(expr_agg.Accumulator) = .empty;
        defer {
            freeAccumulatorRanges(gpa, merged_accs.items, n_workers);
            merged_accs.deinit(lists);
        }
        var folded = out_tables.len > 1 or (n_workers > 1 and result_cut != null and dense_direct == null);
        // Set when the merge left each group's state in its source table (`mergeInPlace`).
        var in_place_tables: []const expr_agg.GroupTable = &.{};
        // Partition tables already hold each key once. Their accumulators move into `merged_accs`; the keys stay
        // borrowed until the rows are built.
        if (dense_direct) |d| {
            try slots.ensureTotalCapacity(lists, group_refs.len);
            for (group_refs) |ref| slots.appendAssumeCapacity(.{
                .key = &.{},
                .first = d.position(ref.group),
                .idx = ref.group,
            });
            folded = false;
        } else if (spilled) {
            const ps = &part_state.?;
            try fillFromPartitions(
                gpa,
                lists,
                arena,
                ps.parts,
                agg_calls,
                group_outputs.?,
                args.result_order,
                args.unordered,
                result_cut,
                n_workers,
                &slots,
                &merged_accs,
            );
            folded = true;
        } else if (folded) {
            if (candidates) |keys_kept| {
                try mergeCandidates(gpa, lists, out_tables, keys_kept, agg_calls, n_workers, &slots, &merged_accs);
            } else {
                // Pairs left their count(DISTINCT) a count in every table: it merges as one, in place or under a cut.
                const merge_calls = if (pairs_used) try countedCalls(arena, agg_calls, pairs_call.?) else agg_calls;
                const in_place = mergesInPlace(merge_calls, result_cut);
                try mergeFoldedRefs(
                    gpa,
                    lists,
                    out_tables,
                    group_refs,
                    merge_calls,
                    n_workers,
                    result_cut,
                    in_place,
                    &slots,
                    &merged_accs,
                );
                if (in_place) in_place_tables = out_tables;
            }
        } else {
            const gt = &out_tables[0];
            try slots.ensureTotalCapacity(lists, group_refs.len);
            if (cut == null and candidates == null) {
                slots.items.len = group_refs.len;
                finishGroupRanges(out_tables, null, slots.items, n_workers, false);
            } else for (group_refs) |ref| {
                slots.appendAssumeCapacity(.{
                    .key = gt.keyAt(ref.group),
                    .first = gt.first.items[ref.group],
                    .idx = ref.group,
                });
            }
        }
        if (folded) if (result_cut) |rc| {
            if (rc.ranking_first) {
                try keepResultTop(gpa, lists, agg_calls, rc, &slots, &merged_accs);
            } else try keepCountTop(gpa, lists, agg_calls, .{ .a_idx = rc.a_idx, .k = rc.k }, &slots, &merged_accs);
        };
        if (!args.unordered) try sortSlotsByFirst(lists, slots.items, n_workers);

        // Owned by `output` from allocation on, every slot valid at every step, so its `deinit` frees a partly built
        // answer: unbuilt values NULL. One slab holds every row's cells (`AggOutput.slab`), not an allocation a row.
        var row_src: RowSource = .{
            .slots = slots.items,
            .outputs = outputs,
            .calls = agg_calls,
            .key_types = key_types,
            .key_exprs = keys,
            .accs = if (folded) merged_accs.items else out_tables[0].accumulators.items,
            .folded = folded,
            .in_place = in_place_tables,
            .single = if (folded) null else &out_tables[0],
            .fixed_keys = if (spilled) fixed_stride != 0 else out_tables[0].fixed_stride != 0,
            .dense = dense_direct,
            .identity = if (dense_identity) |*identity| identity else null,
        };
        // A small cut owns its few surviving strings instead of retaining every source arena.
        if (dense_direct == null and order.keys.len == 0 and order.limit == null and order.offset == 0 and
            order.having == null and order.hidden.len == 0)
        {
            const source_tables = try arena.alloc(*expr_agg.GroupTable, if (spilled) part_state.?.parts.len else out_tables.len);
            if (spilled) {
                for (part_state.?.parts, source_tables) |*p, *dest| dest.* = &p.table;
            } else for (out_tables, source_tables) |*gt, *dest| dest.* = gt;
            output.arena_credit = try output.takeTableArenas(gpa, source_tables, group_budget);
            output.arena_ledger = args.ledger;
            row_src.borrowed_strings = output.borrowed_strings;
        }
        const as_is = order.keys.len == 0 and order.limit == null and order.offset == 0 and order.having == null and
            order.hidden.len == 0;
        const typed = args.typed_answer and as_is;
        // The answer is drawn from the ledger before it is built, beside the tables and merge it is built from, and
        // stays drawn while the query holds it (the engine's ledger outlives it). Refused, it is the merge's refusal:
        // on one worker the tables it reads are one.
        const winner_copies = row_src.winnerStringBytes();
        if (args.ledger != null or winner_copies != 0) {
            const bytes = (if (args.ledger != null)
                answerBytesParallel(slots.items, col_types, if (row_src.borrowed_strings.len != 0) &.{} else key_types, typed, n_workers) +|
                    row_src.denseStringBytes()
            else
                0) +| winner_copies;
            answer_charge += group_budget.drawExact(bytes) orelse {
                if (args.taken) |taken| taken.insert(.merge_memory);
                return error.ExceededMemoryBudget;
            };
        }
        if (typed) {
            output.typed = .{ .rows = 0, .columns = &.{} };
            try buildGroupColumns(gpa, &output.typed.?, row_src, col_types, n_workers);
            // Its encoding draws up to three times its bytes (`consumer.aggEncodeCharge`) from the ledger.
            if (leave_tables and args.ledger != null and group_budget.available() < answer_charge *| 3) {
                leave_tables = false;
                for (left_lanes) |*l| l.deinit(gpa);
                if (left_domain) |*d| d.deinit(gpa);
                left_lanes = &.{};
                left_domain = null;
            }
        } else {
            const rows = try gpa.alloc([]const AggValue, slots.items.len);
            @memset(rows, &.{});
            output.group_rows = rows;
            try buildGroupRows(gpa, &output.slab, row_src, rows, n_workers);
        }

        const cols = try gpa.alloc([]const u8, outputs.len);
        @memset(cols, "");
        output.group_cols = cols;
        for (outputs, cols) |out, *col| col.* = try gpa.dupe(u8, out.name);

        // Result strings either own their copy or borrow the arenas now held by output. The table
        // payload/storage can be released before returning; the deferred deinit then finds it empty.
        if (!leave_tables) {
            finishGroupRanges(out_tables, null, null, n_workers, true);
            for (out_tables) |*gt| {
                gt.deinitStorage();
                gt.* = expr_agg.GroupTable.init(gpa, 0);
            }
        }
    } else {
        // Merge each work item exactly ONCE: `work` is shared and claimed dynamically, so folding it per worker would
        // merge every item n_workers times — inflating sums and double-freeing the string min/max winner.
        for (work_items.items) |item| {
            for (item.accumulators, 0..) |*sub_acc, i| {
                const call = agg_calls[item.agg_start + i];
                if (call.func != .count_distinct) {
                    try mergeOwnedAccumulator(&accumulators[item.agg_start + i], sub_acc, gpa);
                }
            }
        }
        for (agg_calls, 0..) |call, ci| {
            if (call.func != .count_distinct) continue;
            const dst_acc = &accumulators[ci];
            const dst_ds = dst_acc.distinct.heap() orelse continue;
            if (dst_ds.parts) |dst_parts| {
                // Under pressure, finish and release one source partition at a time instead of growing several
                // destination maps concurrently against the last shared credit.
                const n_threads = if (group_budget.tight()) 1 else @min(n_workers, dst_parts.len);
                const tasks = try arena.alloc(DistinctMergeTask, n_threads);
                var cursor = std.atomic.Value(usize).init(0);
                for (tasks) |*task| task.* = .{
                    .gpa = gpa,
                    .dst_parts = dst_parts,
                    .work_items = work_items.items,
                    .agg_idx = ci,
                    .cursor = &cursor,
                };
                const config: std.Thread.SpawnConfig = .{ .stack_size = WORKER_STACK_SIZE };
                if (!spawn_util.runTree(DistinctMergeTask, tasks, config, DistinctMergeTask.run)) {
                    DistinctMergeTask.run(&tasks[0]);
                }
                for (tasks) |task| if (task.err) |e| return e;

                for (work_items.items) |item| {
                    if (ci >= item.agg_start and ci < item.agg_start + item.agg_len) {
                        const sub_acc = &item.accumulators[ci - item.agg_start];
                        if (sub_acc.* == .distinct) if (sub_acc.distinct.heap()) |ds| {
                            ds.deinit(gpa);
                            gpa.destroy(ds);
                            sub_acc.* = .{ .distinct = .{} };
                        };
                    }
                }
            } else {
                for (work_items.items) |item| {
                    if (ci >= item.agg_start and ci < item.agg_start + item.agg_len) {
                        const sub_acc = &item.accumulators[ci - item.agg_start];
                        try mergeOwnedAccumulator(dst_acc, sub_acc, gpa);
                    }
                }
            }
        }
        for (workers) |w| {
            rows_in += w.rows_in;
            rows_scanned += w.rows_scanned;
            rows_matched += w.rows_matched;
            rgs_in += w.rgs_in;
            rgs_pruned += w.rgs_pruned;
            rgs_full_match += w.rgs_full_match;
            t.core.decode_ns += w.timings.decode_ns;
            t.core.eval_ns += w.timings.eval_ns;
            t.core.encode_ns += w.timings.encode_ns;
        }
    }

    merge_span.end(.merge, profile.args(.{}));

    // 7. Materialize into gpa, so the answer outlives the arena the caller will eventually deinit.
    const finalize_span = profile.Span.begin(prof);
    defer finalize_span.end(.finalize, profile.args(.{}));
    if (group_by_keys == null) {
        // The merge freed every losing winner; the answer copies the ones left.
        const kept = ownedWinnerBytes(accumulators);
        winners.settle(kept);
        try winners.adjust(kept, kept * 2);
        const items = try gpa.alloc(AggOutputItem, agg_calls.len);
        @memset(items, .{ .alias = "", .value = .null_val });
        output.aggs = items;
        for (agg_calls, items, accumulators) |call, *item, acc| {
            item.alias = try gpa.dupe(u8, call.alias);
            item.value = try materializeOne(gpa, call, acc);
        }
    }

    var bytes_in: u64 = 0;
    for (args.inputs) |in| bytes_in += if (in.logical_size != 0) in.logical_size else in.bytes.len;

    return .{
        .files_in = args.inputs.len,
        .rows_in = rows_in,
        .rows_scanned = rows_scanned,
        .rows_matched = rows_matched,
        .bytes_in = bytes_in,
        .row_groups_in = rgs_in,
        .row_groups_pruned = rgs_pruned,
        .row_groups_full_match = rgs_full_match,
        .cols_stat_pruned = plan.cols_stat_pruned,
        .membership = membership_stats,
        .timings = t,
        .output = output,
        .part_agg = spilled,
        .distinct_pairs = pairs_used,
        .dense_aggregate = dense_merged and dense_verified,
        .reasons = scan_plan.reasons,
        .visible_cols = if (args.result_order.hidden.len > 0) args.select_cols.?.len else null,
        .state = .{
            .accumulators = accumulators,
            .agg_calls = agg_calls,
            .group_col_types = group_col_types,
            .agg_sources = agg_sources,
        },
    };
}

/// Each temporary query owns a child ledger. Existing executor reservations and actual allocations both draw
/// conservatively; the whole phase retires before its remaining diagnostic/output credit returns to the parent.
const RankedPhase = struct {
    budget: core_memory.SharedBudget = undefined,
    charged: core_memory.Charged = undefined,
    arena_budget: core_memory.SharedBudget = undefined,
    arena_charged: core_memory.Charged = undefined,
    arena: std.heap.ArenaAllocator = undefined,

    fn init(p: *RankedPhase, gpa: std.mem.Allocator, parent: *core_memory.SharedBudget, limit: usize) void {
        p.budget = .{ .limit = limit, .parent = parent };
        p.charged = .{ .child = gpa, .budget = &p.budget };
        p.arena_budget = .{ .limit = limit, .parent = parent };
        p.arena_charged = .{ .child = gpa, .budget = &p.arena_budget };
        p.arena = .init(p.arena_charged.allocator());
    }

    fn deinit(p: *RankedPhase) void {
        p.arena.deinit();
        p.budget.release(p.budget.used.load(.monotonic));
    }
};



fn rankedColumn(col: expr_ast.ColRef) bool {
    return col.expr_type == .i64 and !col.unsigned_32 and !col.unsigned_64 and
        (col.physical_type == .INT32 or col.physical_type == .INT64);
}

fn sameRankedKey(a: AggValue, b: AggValue) bool {
    return switch (a) {
        .i => |v| b == .i and v == b.i,
        .null_val => b == .null_val,
        else => false,
    };
}

fn countRankedDistinct(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    filter: ?filter_ast.Filter,
) anyerror!?MultiAggResult {
    if (args.count_ranked_distinct == .off or args.scan_all or args.unordered or !args.dense or
        !args.ndv_union or !allRescannable(args.inputs)) return null;
    const keys = keys_opt orelse return null;
    const outputs = outputs_opt orelse return null;
    if (keys.len != 1 or keys[0] != .col_ref or !rankedColumn(keys[0].col_ref) or args.result_order.having != null or
        args.result_order.hidden.len != 0) return null;
    for (outputs) |out| if (out.derived != null) return null;
    const cut = countCut(outputs, calls, args.result_order) orelse return null;
    if (cut.k == 0 or calls[cut.a_idx].func != .count or calls[cut.a_idx].arg != null) return null;
    var distinct: ?usize = null;
    var payload = false;
    for (calls, 0..) |call, ai| {
        if (call.where != null or call.state or call.offset != 0) return null;
        switch (call.func) {
            .count => if (call.arg != null) return null,
            .count_distinct => {
                if (distinct != null or call.arg == null) return null;
                distinct = ai;
            },
            .sum, .avg => payload = true,
            else => return null,
        }
        if (call.arg) |arg| if (arg != .col_ref or !rankedColumn(arg.col_ref)) return null;
    }
    const di = distinct orelse return null;
    if (!payload) return null;

    var own: core_memory.SharedBudget = .{ .limit = args.max_memory };
    const ledger = args.ledger orelse &own;
    var phase: RankedPhase = undefined;
    phase.init(gpa, ledger, args.max_memory);
    defer phase.deinit();
    return countRankedAttempt(gpa, arena, args, metas, calls, keys, outputs, filter, cut, di, ledger, &phase) catch |e| {
        return switch (e) {
            error.OutOfMemory, error.ExceededMemoryBudget, error.CountRankedDistinctDeclined => error.CountRankedDistinctDeclined,
            else => e,
        };
    };
}

fn countRankedAttempt(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    calls: []const expr_agg.AggCall,
    keys: []const expr_ast.Expr,
    outputs: []const BoundOutputColumn,
    filter: ?filter_ast.Filter,
    cut: CountCut,
    di: usize,
    ledger: *core_memory.SharedBudget,
    phase: *RankedPhase,
) anyerror!?MultiAggResult {
    const a = phase.arena.allocator();
    const ordinary = try a.alloc(expr_agg.AggCall, calls.len - 1);
    const ordinary_outputs = try a.alloc(BoundOutputColumn, calls.len);
    ordinary_outputs[0] = .{ .source = .{ .key = 0 }, .name = "__ranked_key" };
    var oi: usize = 0;
    for (calls, 0..) |call, ai| {
        if (ai == di) continue;
        ordinary[oi] = call;
        ordinary[oi].alias = try std.fmt.allocPrint(a, "__ranked_agg_{d}", .{oi});
        ordinary[oi].default_name = null;
        ordinary_outputs[oi + 1] = .{ .source = .{ .agg = oi }, .name = ordinary[oi].alias };
        oi += 1;
    }
    const ordinary_bound: BoundAggregate = .{ .calls = ordinary, .keys = keys, .outputs = ordinary_outputs, .filter = filter };
    var first = args;
    first.inputs = try a.dupe(Input, args.inputs);
    for (@constCast(first.inputs)) |*input| {
        const bytes = input.plan_bytes orelse input.bytes;
        if (input.logical_size != 0 and bytes.len != input.logical_size) return null;
        input.bytes = bytes;
        input.gate = null;
        input.dict_wait = null;
    }
    first.metas = metas;
    first.start_reads = null;
    first.dict_probe = null;
    first.count_ranked_distinct = .off;
    first.bound_aggregate = &ordinary_bound;
    first.select_cols = null;
    first.column_order = null;
    first.sketch_topk = null;
    first.partagg = false;
    first.partition_cost = false;
    first.plain_rules = false;
    first.typed_answer = false;
    first.record_answer = false;
    first.leave_regions = false;
    first.ledger = &phase.budget;
    const rank = [_]expr_ast.OrderKey{.{ .column = 1 + cut.a_idx - @intFromBool(cut.a_idx > di), .descending = true }};
    first.result_order = .{ .keys = &rank, .limit = cut.k };
    const explanation = try explainAggregate(phase.charged.allocator(), a, first);
    if (!explanation.dense) return null;
    // The mapping is complete before abandoning a streaming reader; any subsequent refusal replays that mapping.
    if (args.start_reads) |start| if (start.abandon) |abandon| abandon(start.ctx);
    var counted = try runMultiAggregate(phase.charged.allocator(), a, first);
    defer counted.deinit(phase.charged.allocator());
    if (!counted.dense_aggregate) return error.CountRankedDistinctDeclined;
    const original = try a.dupe([]const AggValue, counted.output.group_rows orelse return error.CountRankedDistinctDeclined);
    try counted.output.applyResultOrder(phase.charged.allocator(), first.result_order);
    const retained = counted.output.group_rows.?;
    const predicates = try a.alloc(filter_ast.Filter, retained.len);
    const key = keys[0].col_ref;
    for (retained, predicates) |row, *predicate| {
        predicate.* = switch (row[0]) {
            .i => |v| if (key.physical_type == .INT32)
                .{ .int32 = .{ .col_idx = key.col_idx, .op = .Eq, .value = std.math.cast(i32, v) orelse return error.CountRankedDistinctDeclined, .stored = true } }
            else
                .{ .int64 = .{ .col_idx = key.col_idx, .op = .Eq, .value = std.math.cast(i64, v) orelse return error.CountRankedDistinctDeclined, .stored = true } },
            .null_val => .{ .null_check = .{ .col_idx = key.col_idx, .is_not = false } },
            else => return error.CountRankedDistinctDeclined,
        };
    }
    const winners_filter: filter_ast.Filter = .{ .or_filter = .{ .children = predicates } };
    const retained_filter: filter_ast.Filter = if (filter) |f|
        .{ .and_filter = .{ .children = try a.dupe(filter_ast.Filter, &.{ f, winners_filter }) } }
    else
        winners_filter;
    var second_phase: RankedPhase = undefined;
    second_phase.init(gpa, ledger, args.max_memory);
    defer second_phase.deinit();
    var second = first;
    const distinct_bound: BoundAggregate = .{
        .calls = calls[di..][0..1],
        .keys = keys,
        .outputs = &.{ .{ .source = .{ .key = 0 }, .name = "__ranked_key" }, .{ .source = .{ .agg = 0 }, .name = "__ranked_distinct" } },
        .filter = retained_filter,
    };
    second.bound_aggregate = &distinct_bound;
    second.result_order = .{};
    second.ledger = &second_phase.budget;
    var reduced: ?MultiAggResult = null;
    defer if (reduced) |*r| r.deinit(second_phase.charged.allocator());
    const distinct_rows = if (retained.len == 0) &.{} else blk: {
        reduced = try runMultiAggregate(second_phase.charged.allocator(), second_phase.arena.allocator(), second);
        break :blk reduced.?.output.group_rows orelse return error.CountRankedDistinctDeclined;
    };
    if (distinct_rows.len != retained.len) return error.CountRankedDistinctDeclined;

    const bytes = retained.len *| (outputs.len *| @sizeOf(AggValue) +| @sizeOf([]const AggValue)) +|
        outputs.len *| (@sizeOf([]const u8) +| @sizeOf(GroupColType)) +| outputNamesBytes(outputs);
    _ = ledger.drawExact(bytes) orelse return error.CountRankedDistinctDeclined;
    var credit = bytes;
    defer if (credit != 0) ledger.release(credit);
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    const names = try gpa.alloc([]const u8, outputs.len);
    @memset(names, "");
    output.group_cols = names;
    for (outputs, names) |out, *name| name.* = try gpa.dupe(u8, out.name);
    const rows = try gpa.alloc([]const AggValue, retained.len);
    @memset(rows, &.{});
    output.group_rows = rows;
    output.slab = try gpa.alloc(AggValue, retained.len * outputs.len);
    const types = try arena.alloc(GroupColType, outputs.len);
    for (outputs, types) |out, *ty| ty.* = switch (out.source) {
        .key => .{ .lane = .i64, .nullable = true, .source = leafSchemaElem(&metas[0], keys[0].col_ref.col_idx) },
        .agg => |ai| .{ .lane = if (calls[ai].func == .avg) .f64 else .i64, .nullable = calls[ai].func != .count, .source = passThroughSource(calls[ai], &metas[0]) },
    };
    var ri: usize = 0;
    // The result program still receives first-appearance order before applying its own COUNT sort and offset.
    for (original) |prior| for (retained) |winner| {
        if (prior.ptr != winner.ptr) continue;
        const drow = found: for (distinct_rows) |dr| {
            if (sameRankedKey(winner[0], dr[0])) break :found dr;
        } else return error.CountRankedDistinctDeclined;
        const row = output.slab[ri * outputs.len ..][0..outputs.len];
        rows[ri] = row;
        for (outputs, row) |out, *value| value.* = switch (out.source) {
            .key => winner[0],
            .agg => |ai| if (ai == di) drow[1] else winner[1 + ai - @intFromBool(ai > di)],
        };
        ri += 1;
    };
    if (ri != retained.len) return error.CountRankedDistinctDeclined;
    var result = counted;
    result.output = output;
    result.state = .{ .accumulators = &.{}, .agg_calls = calls, .group_col_types = types };
    result.count_ranked_distinct = true;
    result.dense_aggregate = false;
    if (reduced) |r| result.timings.decode_wall_ns +|= r.timings.decode_wall_ns;
    if (args.ledger) |parent| {
        result.output.arena_ledger = parent;
        result.output.arena_credit = bytes;
        credit = 0;
    }
    return result;
}

/// A missing footer bound warrants a bounded look at the first page. It can only decline: later keys still face
/// the exact width guard. A corrupt sample also declines, so the ordinary scan preserves decode error precedence.
fn byteSampleMayFit(
    gpa: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    work: []const WorkItem,
    key_col: usize,
) !bool {
    return shortSampleMayFit(gpa, args, metas, work, key_col, 16);
}

fn shortSampleMayFit(
    gpa: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    work: []const WorkItem,
    key_col: usize,
    comptime width: usize,
) !bool {
    for (work) |item| {
        // Readers have not started. Do not fault their mapping for an optional cost probe.
        if (args.inputs[item.file].gate != null) continue;
        const rg = &metas[item.file].row_groups.items[item.rg];
        const cm = rg.columns.items[key_col].meta_data orelse return false;
        if (rg.num_rows == 0) continue;
        if (cm.statistics) |st| if (st.min_value != null or st.max_value != null or
            st.min != null or st.max != null) continue;
        const cap = 4 << 20;
        if (args.ledger) |l| _ = l.drawExact(cap) orelse return false;
        defer if (args.ledger) |l| l.release(cap);
        const buf = gpa.alloc(u8, cap) catch return false;
        defer gpa.free(buf);
        var fixed = std.heap.FixedBufferAllocator.init(buf);
        const a = fixed.allocator();
        var reader = (consumer.SliceReader.init(a, a, rg, &metas[item.file], .{
            .bytes = args.inputs[item.file].plan_bytes orelse args.inputs[item.file].bytes,
            .byte_origin = 0,
        }, key_col, .{ .encoded = args.encoded, .expand_limit = cap }) catch return false) orelse return false;
        defer reader.deinit();
        const sampled: usize = @intCast(@min(rg.num_rows, 64));
        const col = reader.next(a, sampled) catch return false;
        const strings = col.string;
        for (0..sampled) |i| {
            if (strings.def_levels) |d| if (d[i] < strings.max_def) continue;
            const value = if (strings.codes) |codes| strings.dict[codes[i]] else strings.values[i];
            if (value.len > width) return false;
        }
        return true;
    }
    return true;
}

/// Only a cost probe. Its read failure or an oversized header declines before decoded rows are consumed.
fn msdProbeHeaders(args: MultiAggArgs, metas: []const schema.FileMetaData, work: []const WorkItem, keys: []const expr_ast.Expr, explain: bool) !?u64 {
    for (args.inputs) |input| if (input.gate != null and
        (!input.readerBacked() or input.dict_wait == null or args.dict_probe == null or args.start_reads == null)) return null;
    var bytes: u64 = 0;
    for (work) |item| for (keys) |key| {
        const cm = metas[item.file].row_groups.items[item.rg].columns.items[key.col_ref.col_idx].meta_data orelse return null;
        const off = cm.dictionary_page_offset orelse cm.data_page_offset;
        if (off < 0 or cm.total_compressed_size < 0) return null;
        if (args.inputs[item.file].readerBacked()) bytes +|= @as(u64, @min(@as(u64, @intCast(cm.total_compressed_size)), 4096)) + 8192;
    };
    if (bytes > args.probe_cap orelse ndv.probeCap(args.max_memory)) return null;
    if (!explain) if (args.dict_probe) |probe| for (work) |item| for (keys) |key| {
        const cm = metas[item.file].row_groups.items[item.rg].columns.items[key.col_ref.col_idx].meta_data.?;
        const start: u64 = @intCast(cm.dictionary_page_offset orelse cm.data_page_offset);
        const len: u64 = @min(@as(u64, @intCast(cm.total_compressed_size)), 4096);
        try probe.add(probe.ctx, item.file, item.rg, start, start + len);
    };
    return bytes;
}

fn msdWorkspace(args: MultiAggArgs, metas: []const schema.FileMetaData, work: []const WorkItem, keys: []const expr_ast.Expr, workers: usize, explain: bool) ?usize {
    var largest: usize = 0;
    for (work) |item| {
        const input = args.inputs[item.file];
        if (!explain) if (input.dict_wait) |wait| wait.wait(wait.ctx, item.rg) catch return null;
        const src = if (explain) input.plan_bytes orelse input.bytes else input.bytes;
        var entries: [2]usize = @splat(0);
        for (keys, 0..) |key, i| {
            const cm = metas[item.file].row_groups.items[item.rg].columns.items[key.col_ref.col_idx].meta_data.?;
            const start = std.math.cast(usize, cm.dictionary_page_offset orelse cm.data_page_offset) orelse return null;
            const len = std.math.cast(usize, cm.total_compressed_size) orelse return null;
            if (start > src.len or len > src.len - start) return null;
            var reader = thrift_mod.Reader.init(src[start..][0..@min(len, 4096)]);
            const header = schema.PageHeader.read(&reader) catch return null;
            switch (header.type) {
                .DICTIONARY_PAGE => {
                    const h = header.dictionary_page_header orelse return null;
                    if (h.num_values < 0) return null;
                    entries[i] = @intCast(h.num_values);
                },
                .DATA_PAGE, .DATA_PAGE_V2 => {},
                else => return null,
            }
        }
        const rg = &metas[item.file].row_groups.items[item.rg];
        const f = rg.columns.items[keys[1].col_ref.col_idx].meta_data.?;
        const rows = std.math.cast(usize, rg.num_rows) orelse return null;
        // Whole-row views, definition/code arrays and their arena growth, dictionary slices, and numeric scratch.
        // Retained key payloads are separate. The same fixed credit covers every worker's high-water mark.
        const need = rows *| 128 +| entries[0] *| 64 +| entries[1] *| 32 +|
            column_mod.inflateLimit(f) *| 4 +| (4 << 20);
        largest = @max(largest, need);
    }
    return largest *| workers;
}

fn inlineMsdAnswer(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    n_workers: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const order = args.result_order;
    if (!args.msd_records or !allRescannable(args.inputs) or
        order.having != null or order.hidden.len != 0 or order.keys.len != 1 or calls.len != 1) return null;
    const keys = keys_opt orelse return null;
    const outputs = outputs_opt orelse return null;
    for (outputs) |out| if (out.derived != null) return null;
    if (keys.len != 2 or keys[0] != .col_ref or keys[1] != .col_ref or outputs.len != 3) return null;
    const key = keys[0].col_ref;
    const f = keys[1].col_ref;
    if (key.physical_type != .BYTE_ARRAY or key.expr_type != .str or f.physical_type != .INT32 or
        f.expr_type != .i64 or f.unsigned_32) return null;
    const call = calls[0];
    if (call.func != .count or call.arg != null or call.where != null or call.offset != 0 or call.state or call.result != .i64)
        return null;
    const limit = order.limit orelse return null;
    const k = std.math.cast(usize, order.offset +| limit) orelse return null;
    if (limit == 0 or k == 0 or k > 1024 or !order.keys[0].descending) return null;
    const ordered = outputs[order.keys[0].column].source;
    if (ordered != .agg or ordered.agg != 0) return null;
    var seen: u8 = 0;
    for (outputs) |out| seen |= @as(u8, 1) << @intCast(switch (out.source) {
        .key => |i| i,
        .agg => @as(usize, 2),
    });
    if (seen != 7) return null;
    var rows: usize = 0;
    var raw: usize = 0;
    var largest_capacity: usize = 0;
    for (work) |item| {
        const rg = &metas[item.file].row_groups.items[item.rg];
        if (rg.num_rows < 0) return null;
        rows +|= @intCast(rg.num_rows);
        const cm = rg.columns.items[key.col_idx].meta_data orelse return null;
        const f_cm = rg.columns.items[f.col_idx].meta_data orelse return null;
        if (cm.type != .BYTE_ARRAY or f_cm.type != .INT32) return null;
        if (cm.total_uncompressed_size < 0 or cm.total_compressed_size < 0) return null;
        // Expansion encodings have a different physical ownership bound. Decline them before consumption.
        for (cm.encodings.items) |enc| switch (enc) {
            .PLAIN, .RLE, .BIT_PACKED, .RLE_DICTIONARY, .PLAIN_DICTIONARY => {},
            else => return null,
        };
        const capacity = column_mod.inflateLimit(cm) +| @as(usize, @intCast(cm.total_compressed_size));
        if (capacity >= @as(u64, 1) << 32) return null;
        raw +|= capacity;
        largest_capacity = @max(largest_capacity, capacity);
    }
    if (rows < args.msd_records_min_rows or rows >= 1 << 30) return null;
    // Each surviving key is contained in one retained chunk. Repeated dictionary keys can win for different f,
    // so reserve H copies of the largest chunk bound, not merely the sum of unique retained bytes. Decoder
    // workspace is dead before those copies are made and can fund the same credit without another parent draw.
    const names_credit = outputNamesBytes(outputs);
    const output_credit = names_credit +| k *| largest_capacity +|
        k *| (@sizeOf([]const AggValue) + outputs.len * @sizeOf(AggValue));
    const cache_count = msd_groups.cacheRows(args.msd_cache_rows);
    const quote = msd_groups.State.reservation(rows, n_workers, k, raw, work.len, cache_count) +|
        msd_groups.State.phaseFunding(args.msd_working_bytes orelse 0, output_credit);
    if (quote > args.max_memory) return null;
    if (explain_only) return .{ .layout = .msd_count_top_h, .reservation = quote };
    const working = args.msd_working_bytes orelse return null;
    const capacities = arena.alloc(usize, work.len) catch return null;
    const starts = arena.alloc(u32, work.len) catch return null;
    var at: usize = 0;
    for (work, capacities, starts) |item, *capacity, *start| {
        const rg = &metas[item.file].row_groups.items[item.rg];
        const cm = rg.columns.items[key.col_idx].meta_data.?;
        capacity.* = column_mod.inflateLimit(cm) +| @as(usize, @intCast(cm.total_compressed_size));
        start.* = @intCast(at);
        at += @intCast(rg.num_rows);
    }
    const state = (try msd_groups.State.initPrepaid(gpa, args.ledger, rows, n_workers, key.col_idx, f.col_idx, k, capacities, working, output_credit, cache_count)) orelse return null;
    defer {
        const release = profile.Span.begin(profile.threadOf(args.profiler, .main));
        state.deinit();
        release.end(.msd_release, profile.args(.{}));
    }
    const sinks = arena.alloc(consumer.RecordSink, n_workers) catch return null;
    for (sinks, state.locals) |*sink, *local| sink.* = .{ .msd = local };
    if (args.taken) |taken| taken.insert(.msd_records);
    var decoded_args = args;
    decoded_args.ledger = &state.decode_budget;
    decoded_args.decode_limit = working;
    decoded_args.taken = null;
    const run = try runRecordWorkers(
        gpa,
        arena,
        decoded_args,
        metas,
        plan,
        work,
        calls,
        keys,
        sinks,
        starts,
        outputs,
        timings,
    );
    state.releaseDecode();
    const final_start = nowMonoNs();
    const kept = try state.finishSelected(@intCast(run.rows_matched));
    const prof = profile.threadOf(args.profiler, .main);
    profile.record(prof, .msd_fold, final_start, nowMonoNs(), profile.args(.{ state.prefix_len, state.output_credit, cache_count }));
    const materialize = nowMonoNs();
    var answer_bytes = names_credit +| kept.len * (@sizeOf([]const AggValue) + outputs.len * @sizeOf(AggValue));
    for (kept) |group| if (group.record.key()) |bytes| {
        answer_bytes +|= bytes.len;
    };
    // The admission bound includes every surviving key and row. A defensive refusal retries the established
    // executor; it never requests additional parent credit after consumption.
    if (answer_bytes > state.output_credit) return error.ExceededMemoryBudget;
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    const names = try gpa.alloc([]const u8, outputs.len);
    @memset(names, "");
    output.group_cols = names;
    const types = try arena.alloc(GroupColType, outputs.len);
    for (outputs, types, names) |out, *ty, *name| {
        name.* = try gpa.dupe(u8, out.name);
        ty.* = switch (out.source) {
            .key => |i| .{ .lane = if (i == 0) .string else .i64, .nullable = true, .source = leafSchemaElem(&metas[0], keys[i].col_ref.col_idx) },
            .agg => .{ .lane = .i64, .nullable = false },
        };
    }
    const owned = names_credit +| try buildMsdTopRows(gpa, &output, kept, outputs);
    if (args.ledger != null) state.charged -= owned;
    profile.record(prof, .msd_output, materialize, nowMonoNs(), profile.args(.{}));
    var bytes_in: u64 = 0;
    for (args.inputs) |input| bytes_in += if (input.logical_size != 0) input.logical_size else input.bytes.len;
    return .{
        .files_in = args.inputs.len,
        .rows_in = run.rows_in,
        .rows_scanned = run.rows_scanned,
        .rows_matched = run.rows_matched,
        .bytes_in = bytes_in,
        .row_groups_in = run.row_groups_in,
        .row_groups_pruned = run.row_groups_pruned,
        .row_groups_full_match = run.row_groups_full_match,
        .cols_stat_pruned = plan.cols_stat_pruned,
        .timings = run.timings,
        .output = output,
        .part_agg = true,
        .state = .{ .accumulators = &.{}, .agg_calls = calls, .group_col_types = types },
    };
}

/// Copy the surviving keys before releasing their retained decoder pages. Partial results own every allocation.
fn buildMsdTopRows(gpa: std.mem.Allocator, output: *AggOutput, groups: []const msd_groups.Group, outputs: []const BoundOutputColumn) !usize {
    const rows_out = try gpa.alloc([]const AggValue, groups.len);
    @memset(rows_out, &.{});
    output.group_rows = rows_out;
    const slab = try gpa.alloc(AggValue, groups.len * outputs.len);
    @memset(slab, .null_val);
    output.slab = slab;
    var owned: usize = groups.len * (@sizeOf([]const AggValue) + outputs.len * @sizeOf(AggValue));
    for (groups, rows_out, 0..) |g, *row, i| {
        const cells = slab[i * outputs.len ..][0..outputs.len];
        row.* = cells;
        for (outputs, cells) |out, *cell| cell.* = switch (out.source) {
            .key => |idx| if (idx == 0) if (g.record.key()) |bytes| str: {
                const copy = try gpa.dupe(u8, bytes);
                owned += bytes.len;
                break :str .{ .s = copy };
            } else .null_val else if (g.record.fValue()) |v| .{ .i = v } else .null_val,
            .agg => .{ .i = g.count },
        };
    }
    return owned;
}

fn inlineByteTopAnswer(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    n_workers: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const order = args.result_order;
    const limit = order.limit orelse return null;
    if (limit == 0) return null;
    if (!args.byte_records or !allRescannable(args.inputs) or
        order.keys.len != 1 or order.having != null or order.hidden.len != 0 or calls.len != 1 or
        n_workers > 64) return null;
    const keys = keys_opt orelse return null;
    const outputs = outputs_opt orelse return null;
    for (outputs) |out| if (out.derived != null) return null;
    if (keys.len != 1 or keys[0] != .col_ref or outputs.len != 2) return null;
    const key = keys[0].col_ref;
    if (key.physical_type != .BYTE_ARRAY or key.expr_type != .str) return null;
    const call = calls[0];
    if (args.filter != null and call.func != .count) return null;
    if (call.where != null or call.offset != 0 or call.state or call.result != .i64) return null;
    // COUNT(*) has no value lane; SUM needs one signed INT64 column.
    var value_col: usize = 0;
    switch (call.func) {
        .count => if (call.arg != null) return null,
        .sum => {
            const value = call.arg orelse return null;
            if (value != .col_ref or value.col_ref.physical_type != .INT64 or value.col_ref.expr_type != .i64 or
                value.col_ref.unsigned_64) return null;
            value_col = value.col_ref.col_idx;
        },
        else => return null,
    }
    const rank = order.keys[0];
    if (rank.column >= outputs.len or outputs[rank.column].source != .agg) return null;
    const h = limit +| order.offset;
    if (h == 0 or h > 1024) return null;
    var seen: u8 = 0;
    var names_bytes: usize = outputs.len * @sizeOf([]const u8);
    for (outputs) |out| {
        seen |= if (out.source == .key) @as(u8, 1) else 2;
        names_bytes +|= out.name.len;
    }
    if (seen != 3) return null;
    const starts = arena.alloc(u32, work.len) catch return null;
    var rows: usize = 0;
    for (work, starts) |item, *start| {
        if (!owner_groups.admitsRows(.bytes, rows)) return null;
        start.* = @intCast(rows);
        const rg = &metas[item.file].row_groups.items[item.rg];
        if (rg.num_rows < 0) return null;
        rows +|= @intCast(rg.num_rows);
        // Stored bounds can only decline. Every consumed key still proves its exact length.
        if (rg.columns.items[key.col_idx].meta_data) |cm| if (cm.statistics) |st| {
            for ([_]?[]const u8{ st.min_value, st.max_value, st.min, st.max }) |bound| if (bound) |b|
                if (b.len > 15) return null;
        };
    }
    if (rows < args.byte_records_min_rows or !owner_groups.admitsRows(.bytes, rows)) return null;
    if (args.byte_records_min_rows != 0) if (ndv.footerEntries(metas, keys)) |guess|
        if (guess < rows / 4) return null;
    const producer_rows = if (args.decode_batch_rows != 0)
        args.decode_batch_rows
    else
        owner_groups.batchRows(args.byte_top_batch_rows);
    const output_credit = names_bytes +| @as(usize, @intCast(h)) *|
        (@sizeOf([]const AggValue) + outputs.len * @sizeOf(AggValue) + 15);
    return switch (call.func) {
        inline .sum, .count => |func| runByteTop(
            if (func == .sum) .sum_top else .count_top,
            gpa,
            arena,
            args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            n_workers,
            timings,
            explain_only,
            .{ .key = key, .value_col = value_col, .rows = rows, .h = @intCast(h), .descending = rank.descending, .starts = starts, .producer_rows = producer_rows, .output_credit = output_credit, .names_bytes = names_bytes },
        ),
        else => unreachable,
    };
}

const ByteTopShape = struct {
    key: expr_ast.ColRef,
    value_col: usize,
    rows: usize,
    h: usize,
    descending: bool,
    starts: []u32,
    producer_rows: usize,
    output_credit: usize,
    names_bytes: usize,
};

fn runByteTop(
    comptime kind: owner_groups.Kind,
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys: []const expr_ast.Expr,
    outputs: []const BoundOutputColumn,
    n_workers: usize,
    timings: Timings,
    comptime explain_only: bool,
    shape: ByteTopShape,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const Topk = owner_groups.Owner(kind, .bytes);
    const key = shape.key;
    const rows = shape.rows;
    const starts = shape.starts;
    const producer_rows = shape.producer_rows;
    const output_credit = shape.output_credit;
    const names_bytes = shape.names_bytes;
    const parts = Topk.partitionCount(rows, n_workers, producer_rows, args.byte_top_partitions);
    const quote = Topk.State.reservation(rows, n_workers, parts, shape.h, output_credit);
    if (quote > args.max_memory) return null;
    if (explain_only) return .{ .layout = if (kind == .sum_top) .byte_sum_top_h else .byte_count_top_h, .reservation = quote };
    if (!try shortSampleMayFit(gpa, args, metas, work, key.col_idx, 15)) return null;
    const s = (Topk.State.init(
        gpa,
        args.ledger,
        rows,
        n_workers,
        key.col_idx,
        shape.value_col,
        .{ .k = shape.h, .descending = shape.descending },
        parts,
        output_credit,
    ) catch return null) orelse
        return null;
    defer s.deinit();
    if (args.taken) |taken| taken.insert(.integer_records);
    const sinks = arena.alloc(consumer.RecordSink, n_workers) catch return error.ExceededMemoryBudget;
    for (sinks, s.locals) |*sink, *local| sink.* = if (kind == .sum_top) .{ .byte_top = local } else .{ .byte_count_top = local };
    var decoded = args;
    decoded.decode_batch_rows = producer_rows;
    const run = runRecordWorkers(
        gpa,
        arena,
        decoded,
        metas,
        plan,
        work,
        calls,
        keys,
        sinks,
        starts,
        outputs,
        timings,
    ) catch |e| {
        if (s.width_refused.load(.monotonic)) if (args.taken) |taken| taken.remove(.decode_memory);
        return e;
    };
    const start = nowMonoNs();
    s.finishSelected(@intCast(run.rows_matched)) catch |e|
        return if (e == error.OutOfMemory) error.ExceededMemoryBudget else e;
    const prof = profile.threadOf(args.profiler, .main);
    const fold_end = start + @as(i64, @intCast(s.fold_ns));
    const release_end = fold_end + @as(i64, @intCast(s.release_ns));
    profile.record(prof, .byte_top_fold, start, fold_end, profile.args(.{ parts, decoded.decode_batch_rows }));
    profile.record(prof, .byte_release, fold_end, release_end, profile.args(.{}));
    profile.record(prof, .byte_top_select, release_end, nowMonoNs(), profile.args(.{}));
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    const names = gpa.alloc([]const u8, outputs.len) catch return error.ExceededMemoryBudget;
    @memset(names, "");
    output.group_cols = names;
    const types = arena.alloc(GroupColType, outputs.len) catch return error.ExceededMemoryBudget;
    for (outputs, types, names) |out, *ty, *name| {
        name.* = gpa.dupe(u8, out.name) catch return error.ExceededMemoryBudget;
        ty.* = .{
            .lane = if (out.source == .key) .string else .i64,
            .nullable = out.source == .key or kind != .count_top,
            .source = if (out.source == .key) leafSchemaElem(&metas[0], key.col_idx) else null,
        };
    }
    const answer_bytes = buildByteTopRows(kind, gpa, &output, s.top(), outputs) catch |e|
        return if (e == error.OutOfMemory) error.ExceededMemoryBudget else e;
    const owned = answer_bytes +| names_bytes;
    if (owned > s.output_credit) return error.ExceededMemoryBudget;
    // This small answer remains drawn until the query ledger dies, as with the other aggregate answers.
    if (args.ledger != null) s.charged -= owned;
    var bytes_in: u64 = 0;
    for (args.inputs) |in| bytes_in += if (in.logical_size != 0) in.logical_size else in.bytes.len;
    return .{
        .files_in = args.inputs.len,
        .rows_in = run.rows_in,
        .rows_scanned = run.rows_scanned,
        .rows_matched = run.rows_matched,
        .bytes_in = bytes_in,
        .row_groups_in = run.row_groups_in,
        .row_groups_pruned = run.row_groups_pruned,
        .row_groups_full_match = run.row_groups_full_match,
        .cols_stat_pruned = plan.cols_stat_pruned,
        .timings = run.timings,
        .output = output,
        .part_agg = true,
        .state = .{ .accumulators = &.{}, .agg_calls = calls, .group_col_types = types },
    };
}

fn buildByteTopRows(
    comptime kind: owner_groups.Kind,
    gpa: std.mem.Allocator,
    output: *AggOutput,
    groups: []const owner_groups.Full.Group,
    outputs: []const BoundOutputColumn,
) !usize {
    const rows = try gpa.alloc([]const AggValue, groups.len);
    @memset(rows, &.{});
    output.group_rows = rows;
    const slab = try gpa.alloc(AggValue, groups.len * outputs.len);
    @memset(slab, .null_val);
    output.slab = slab;
    var owned = groups.len * (@sizeOf([]const AggValue) + outputs.len * @sizeOf(AggValue));
    for (groups, rows, 0..) |*g, *row, i| {
        const cells = slab[i * outputs.len ..][0..outputs.len];
        row.* = cells;
        for (outputs, cells) |out, *cell| cell.* = switch (out.source) {
            .key => key: {
                const bytes = g.keyBytes() orelse break :key .null_val;
                const copy = try gpa.dupe(u8, bytes);
                owned += bytes.len;
                break :key .{ .s = copy };
            },
            .agg => if (owner_groups.Owner(kind, .bytes).rank(g.*)) |v| .{ .i = v } else .null_val,
        };
    }
    return owned;
}

fn inlineByteAnswer(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    n_workers: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const order = args.result_order;
    if (!args.byte_records or !allRescannable(args.inputs) or !(args.typed_answer or args.record_answer) or
        args.filter != null or
        order.keys.len != 0 or order.limit != null or order.offset != 0 or order.having != null or
        order.hidden.len != 0 or calls.len != 2) return null;
    const keys = keys_opt orelse return null;
    const outputs = outputs_opt orelse return null;
    for (outputs) |out| if (out.derived != null) return null;
    if (keys.len != 1 or keys[0] != .col_ref or outputs.len != 3) return null;
    const key = keys[0].col_ref;
    if (key.physical_type != .BYTE_ARRAY or key.expr_type != .str) return null;
    var count: ?usize = null;
    var value: ?usize = null;
    for (calls, 0..) |call, i| {
        if (call.where != null or call.offset != 0 or call.state or call.result != .i64) return null;
        switch (call.func) {
            .count => {
                if (call.arg != null or count != null) return null;
                count = i;
            },
            .sum => {
                const arg = call.arg orelse return null;
                if (arg != .col_ref or arg.col_ref.physical_type != .INT64 or arg.col_ref.expr_type != .i64 or
                    arg.col_ref.unsigned_64 or value != null) return null;
                value = arg.col_ref.col_idx;
            },
            else => return null,
        }
    }
    if (count == null or value == null) return null;
    var seen: u8 = 0;
    for (outputs) |out| seen |= @as(u8, 1) << @intCast(switch (out.source) {
        .key => @as(usize, 0),
        .agg => |ai| ai + 1,
    });
    if (seen != 7) return null;
    const starts = try arena.alloc(u32, work.len);
    var rows: usize = 0;
    for (work, starts) |item, *start| {
        if (!owner_groups.admitsRows(.bytes, rows)) return null;
        start.* = @intCast(rows);
        const rg = &metas[item.file].row_groups.items[item.rg];
        if (rg.num_rows < 0) return null;
        rows +|= @intCast(rg.num_rows);
        // Bounds can cheaply decline a long-key shape, but never certify short keys: every decoded key is checked.
        if (rg.columns.items[key.col_idx].meta_data) |cm| if (cm.statistics) |st| {
            for ([_]?[]const u8{ st.min_value, st.max_value, st.min, st.max }) |bound| if (bound) |b|
                if (b.len > 16) return null;
        };
    }
    if (rows < args.byte_records_min_rows or !owner_groups.admitsRows(.bytes, rows) or
        owner_groups.Full.State.reservation(rows, n_workers, owner_groups.full_parts, 0, 0) > args.max_memory) return null;
    if (args.byte_records_min_rows != 0) if (ndv.footerEntries(metas, keys)) |guess|
        if (guess < rows / 4) return null;
    if (explain_only) return .{ .layout = .byte_group_stream, .reservation = owner_groups.Full.State.reservation(rows, n_workers, owner_groups.full_parts, 0, 0) };
    if (!try byteSampleMayFit(gpa, args, metas, work, key.col_idx)) return null;
    const state = (try owner_groups.Full.State.init(gpa, args.ledger, rows, n_workers, key.col_idx, value.?, {}, owner_groups.full_parts, 0)) orelse
        return null;
    state.wide_sums = args.record_answer and !args.typed_answer;
    errdefer state.deinit();
    if (args.taken) |taken| taken.insert(.integer_records);
    const sinks = try arena.alloc(consumer.RecordSink, n_workers);
    for (sinks, state.locals) |*sink, *local| sink.* = .{ .bytes = local };
    const run = runRecordWorkers(
        gpa,
        arena,
        args,
        metas,
        plan,
        work,
        calls,
        keys,
        sinks,
        starts,
        outputs,
        timings,
    ) catch |e| {
        if (state.width_refused.load(.monotonic)) if (args.taken) |taken| taken.remove(.decode_memory);
        return e;
    };
    const prof = profile.threadOf(args.profiler, .main);
    const begin = nowMonoNs();
    try state.finishSelected(@intCast(run.rows_matched));
    const scatter_end = begin + @as(i64, @intCast(state.partition_ns));
    const fold_end = scatter_end + @as(i64, @intCast(state.fold_ns));
    const release_end = fold_end + @as(i64, @intCast(state.release_ns));
    profile.record(prof, .byte_partition, begin, scatter_end, profile.args(.{}));
    profile.record(prof, .byte_fold, scatter_end, fold_end, profile.args(.{}));
    profile.record(prof, .byte_release, fold_end, release_end, profile.args(.{}));
    profile.record(prof, .byte_order, release_end, nowMonoNs(), profile.args(.{}));
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    const names = try gpa.alloc([]const u8, outputs.len);
    @memset(names, "");
    output.group_cols = names;
    const types = try arena.alloc(GroupColType, outputs.len);
    for (outputs, types, names) |out, *ty, *name| {
        name.* = try gpa.dupe(u8, out.name);
        ty.* = .{
            .lane = if (out.source == .key) .string else .i64,
            .nullable = out.source == .key or out.source.agg != count.?,
            .source = if (out.source == .key) leafSchemaElem(&metas[0], key.col_idx) else null,
        };
    }
    output.byte_stream = .{ .state = state, .outputs = outputs, .count_call = count.? };
    var bytes_in: u64 = 0;
    for (args.inputs) |in| bytes_in += if (in.logical_size != 0) in.logical_size else in.bytes.len;
    return .{
        .files_in = args.inputs.len,
        .rows_in = run.rows_in,
        .rows_scanned = run.rows_scanned,
        .rows_matched = run.rows_matched,
        .bytes_in = bytes_in,
        .row_groups_in = run.row_groups_in,
        .row_groups_pruned = run.row_groups_pruned,
        .row_groups_full_match = run.row_groups_full_match,
        .cols_stat_pruned = plan.cols_stat_pruned,
        .timings = run.timings,
        .output = output,
        .part_agg = true,
        .state = .{ .accumulators = &.{}, .agg_calls = calls, .group_col_types = types },
    };
}

/// Sparse numeric images cannot promote to the bitmap: spreading their merge over the wide fanout is useful.
/// A compact footer range retains the numeric fanout that makes bitmap promotion profitable. This prices traffic
/// only: no value is skipped, and a later value outside the hint still joins the exact set.
fn scalarDistinctWideParts(arg: expr_ast.Expr, metas: []const schema.FileMetaData, work: []const WorkItem) bool {
    if (arg.typeOf() != .i64) return true;
    if (arg != .col_ref) return false;
    const c = arg.col_ref;
    const width: usize = switch (c.physical_type) {
        .INT32 => 4,
        .INT64 => 8,
        else => return true,
    };
    var lo: i128 = std.math.maxInt(i128);
    var hi: i128 = std.math.minInt(i128);
    for (work) |item| {
        const meta = &metas[item.file];
        const rg = &meta.row_groups.items[item.rg];
        if (rg.num_rows == 0) continue;
        const b = @import("parquet/statistics.zig").chunkStats(rg, c.col_idx, meta, .corroborated).bounds orelse return false;
        if (b.min.len != width or b.max.len != width) return false;
        const low: i128 = if (width == 4)
            if (c.unsigned_32) std.mem.readInt(u32, b.min[0..4], .little) else std.mem.readInt(i32, b.min[0..4], .little)
        else if (c.unsigned_64) std.mem.readInt(u64, b.min[0..8], .little) else std.mem.readInt(i64, b.min[0..8], .little);
        const high: i128 = if (width == 4)
            if (c.unsigned_32) std.mem.readInt(u32, b.max[0..4], .little) else std.mem.readInt(i32, b.max[0..4], .little)
        else if (c.unsigned_64) std.mem.readInt(u64, b.max[0..8], .little) else std.mem.readInt(i64, b.max[0..8], .little);
        lo = @min(lo, low);
        hi = @max(hi, high);
    }
    if (lo > hi) return false;
    const bytes = (@as(u128, @intCast(hi - lo)) + 64) / 64 * @sizeOf(u64);
    return bytes > @import("hw.zig").l2BytesPerWorkerOr(256 << 10);
}

/// A footer-range cost hint shared by scalar and grouped distinct admission; it never supplies an answer.
const IntegerRangeHint = struct {
    known: bool = true,
    lo: i64 = std.math.maxInt(i64),
    hi: i64 = std.math.minInt(i64),

    fn include(self: *@This(), rg: *const schema.RowGroup, meta: *const schema.FileMetaData, ci: usize) void {
        if (rg.num_rows <= 0) return;
        const bounds = @import("parquet/statistics.zig").chunkStats(rg, ci, meta, .corroborated).bounds;
        if (bounds) |b| {
            if (b.min.len == 8 and b.max.len == 8) {
                self.lo = @min(self.lo, std.mem.readInt(i64, b.min[0..8], .little));
                self.hi = @max(self.hi, std.mem.readInt(i64, b.max[0..8], .little));
                return;
            }
        }
        self.known = false;
    }

    fn small(self: @This(), rows: usize) bool {
        if (!self.known or self.lo > self.hi) return false;
        const span: u128 = @intCast(@as(i128, self.hi) - self.lo + 1);
        return span < rows / 4;
    }
};

const BitmapSink = struct {
    const Source = struct { file: usize, rg: usize };
    state: *grouped_bitmap.State,
    worker: usize,
    domain: *const agg_dense.Domain,
    keys: []const expr_ast.Expr,
    sources: []const Source,
    value_column: usize,
    item: ?usize = null,
    refused: *std.atomic.Value(bool),

    fn startErased(ctx: *anyopaque, _: u64, item: usize) void {
        const s: *BitmapSink = @ptrCast(@alignCast(ctx));
        s.item = item;
    }

    fn batchErased(ctx: *anyopaque, source: consumer.SelectedBatch, lookup: []const ?usize) anyerror!void {
        const s: *BitmapSink = @ptrCast(@alignCast(ctx));
        s.batch(source, lookup) catch |e| {
            if (e != error.BitmapDomainDeclined) return e;
            s.refused.store(true, .monotonic);
            return error.ExceededMemoryBudget;
        };
    }

    fn batch(s: *BitmapSink, source: consumer.SelectedBatch, lookup: []const ?usize) !void {
        try source.validate();
        const item = s.item orelse return error.BadColumn;
        if (item >= s.sources.len or s.value_column >= lookup.len) return error.BadColumn;
        const at = s.sources[item];
        var bindings: [1]agg_dense.CountAxis = undefined;
        if (!try s.domain.bind(s.keys, at.file, at.rg, source.batch, lookup, &bindings))
            return error.BitmapDomainDeclined;
        const pos = lookup[s.value_column] orelse return error.BadColumn;
        if (pos >= source.batch.cols.len) return error.BadColumn;
        const col = switch (source.batch.cols[pos]) {
            .i64 => |c| c,
            else => return error.BitmapDomainDeclined,
        };
        if (col.levels_only_rows != 0) return error.BitmapDomainDeclined;
        if (col.max_rep != 0 or col.rowCount() < source.batch.num_rows) return error.BadColumn;
        if (col.def_levels) |dl| if (dl.len < source.batch.num_rows) return error.BadColumn;
        for (0..source.batch.num_rows) |row| {
            if (source.selected) |selected| if (!selected.isActive(row)) continue;
            const group = try agg_dense.productId(&bindings, row, true);
            const is_null = if (col.def_levels) |dl| dl[row] < col.max_def else false;
            const value: ?i64 = if (is_null) null else if (col.codes) |codes| blk: {
                const code = codes[row];
                if (code >= col.dict.len) return error.BadColumn;
                break :blk col.dict[code];
            } else col.values[row];
            const index = try s.state.geometry.index(value);
            const input_row: u64 = if (source.input_rows) |rows| rows[row] else @intCast(row);
            const ordinal = std.math.cast(u32, try std.math.add(u64, source.input_base, input_row)) orelse
                return error.BadColumn;
            try s.state.add(s.worker, @intCast(group), index, ordinal);
        }
    }
};

fn inlineBitmapAnswer(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    requested: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    if (args.grouped_distinct_bitmap == .off or !args.integer_records or !args.encoded or !args.ndv_union or
        args.distinct_pairs != .auto or !allRescannable(args.inputs) or work.len == 0 or calls.len != 1) return null;
    const call = calls[0];
    if (call.func != .count_distinct or call.arg == null or call.arg.? != .col_ref or call.where != null or
        call.state or call.offset != 0 or call.result != .i64) return null;
    const x = call.arg.?.col_ref;
    if (x.physical_type != .INT64 or x.expr_type != .i64 or x.unsigned_64) return null;
    const keys = keys_opt orelse return null;
    if (keys.len != 1 or keys[0] != .col_ref or keys[0].col_ref.expr_type != .i64) return null;
    const key = keys[0].col_ref;
    if (key.physical_type != .INT32 and key.physical_type != .INT64) return null;
    const outputs = outputs_opt orelse return null;
    for (outputs) |out| if (out.derived != null) return null;
    const input_rows = RecordOrdinals.rows(metas) orelse return null;
    if (input_rows >= @as(usize, 1) << 31) return null;
    const hw = @import("hw.zig");
    const l2 = hw.l2BytesPerWorker();
    if (args.grouped_distinct_bitmap == .auto) {
        if (l2 == 0) return null;
        // Reject expensive discovery from footers alone: probing hundreds of cold headers can delay a decline.
        var dictionary_bytes: u64 = 0;
        for (metas) |meta| for (meta.row_groups.items) |rg| {
            if (rg.num_rows == 0) continue;
            if (key.col_idx >= rg.columns.items.len) return null;
            const cm = rg.columns.items[key.col_idx].meta_data orelse return null;
            if (!ndv.fullCoverage(&cm)) return null;
            const start = cm.dictionary_page_offset orelse return null;
            if (start < 0 or cm.data_page_offset <= start) return null;
            dictionary_bytes +|= @intCast(cm.data_page_offset - start);
            if (dictionary_bytes > l2) return null;
        };
    }
    var rows: usize = 0;
    var range: IntegerRangeHint = .{};
    for (work) |item| {
        const meta = &metas[item.file];
        const rg = &meta.row_groups.items[item.rg];
        const cm = rg.columns.items[x.col_idx].meta_data orelse return null;
        if (meta.getColumnLevels(cm.path_in_schema.items).max_rep != 0) return null;
        rows +|= @intCast(rg.num_rows);
        range.include(rg, meta, x.col_idx);
    }
    if (rows == 0 or !range.known or range.lo > range.hi or
        (args.grouped_distinct_bitmap == .auto and rows < args.integer_records_min_rows)) return null;
    const workers = @max(1, @min(requested, work.len));
    const l3 = hw.l3BytesPerActiveWorker(workers) *| workers;
    const minimum = grouped_bitmap.Geometry.plan(1, range.lo, range.hi, workers, l2, l3, args.grouped_distinct_bitmap) orelse return null;
    var private_ledger: core_memory.SharedBudget = .{ .limit = args.max_memory };
    const ledger = args.ledger orelse &private_ledger;
    var charged: core_memory.Charged = .{ .child = gpa, .budget = ledger };
    var armed = false;
    return bitmapAnswer(gpa, arena, charged.allocator(), ledger, args, metas, plan, work, calls, keys, outputs, rows, workers, l2, l3, minimum, timings, &armed, explain_only) catch |e| {
        if (e == error.OutOfMemory and charged.refused.load(.monotonic)) {
            if (armed) return error.ExceededMemoryBudget;
            return null;
        }
        return e;
    };
}

fn bitmapAnswer(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    charged: std.mem.Allocator,
    ledger: *core_memory.SharedBudget,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys: []const expr_ast.Expr,
    outputs: []const BoundOutputColumn,
    rows: usize,
    workers: usize,
    l2: usize,
    l3: usize,
    minimum: grouped_bitmap.Geometry,
    timings: Timings,
    armed: *bool,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    var temporary = std.heap.ArenaAllocator.init(charged);
    defer temporary.deinit();
    const a = temporary.allocator();
    const files = try a.alloc(ndv.File, args.inputs.len);
    for (files, args.inputs) |*f, in| f.* = .{
        .bytes = in.plan_bytes orelse in.bytes,
        .local = !std.mem.startsWith(u8, in.name, "s3://"),
    };
    const row_bytes = minimum.words * @sizeOf(u64);
    // Header bounds reject expensive identity probes; they are only a cost gate, never group presence evidence.
    const stat = try ndv.collect(charged, a, files, metas, keys, workers, ledger.available(), false);
    if (args.grouped_distinct_bitmap == .auto and (stat.entries == null or stat.covered_rows != stat.rows or
        stat.dictionary_bytes > l2 or stat.lo *| row_bytes > l3 / 2)) return null;
    const identity_limit = @min(rows + 1, (if (args.grouped_distinct_bitmap == .auto) l3 / 2 else ledger.available()) / row_bytes);
    var domain = (try ndv.retainIdentity(charged, a, files, metas, keys, workers, ledger.available(), identity_limit)) orelse return null;
    defer domain.deinit(charged);
    const geometry = grouped_bitmap.Geometry.plan(domain.ids(), minimum.lo, @intCast(@as(i128, minimum.lo) + minimum.width - 1), workers, l2, l3, args.grouped_distinct_bitmap) orelse return null;
    const state_bytes = geometry.bytes() orelse return null;
    if (state_bytes > ledger.available()) return null;
    if (explain_only) return .{
        .layout = .grouped_distinct_bitmap,
        .reservation = state_bytes +| domain.bytes,
        .partitions = geometry.parts,
    };
    var identity = (try key_pack.Plan.init(charged, keys, &domain)) orelse return null;
    defer identity.deinit(charged);
    if (identity.encoding.source != .dictionary) return null;
    var state = try grouped_bitmap.State.init(charged, geometry);
    defer state.deinit();
    const starts = try a.alloc(u32, work.len);
    if (!RecordOrdinals.fill(metas, work, starts)) return error.BadColumn;
    const sources = try a.alloc(BitmapSink.Source, work.len);
    for (sources, work) |*s, item| s.* = .{ .file = item.file, .rg = item.rg };
    const adapters = try a.alloc(BitmapSink, workers);
    const sinks = try a.alloc(consumer.RecordSink, workers);
    var refused: std.atomic.Value(bool) = .init(false);
    for (adapters, sinks, 0..) |*s, *sink, i| {
        s.* = .{ .state = &state, .worker = i, .domain = &domain, .keys = keys, .sources = sources, .value_column = calls[0].arg.?.col_ref.col_idx, .refused = &refused };
        sink.* = .{ .selected = .{ .ctx = s, .startFn = BitmapSink.startErased, .batchFn = BitmapSink.batchErased } };
    }
    // FailureProbe retains worker diagnostics until prepareAggregate has replayed its canonical error prefix.
    var worker_credit = workers *| (@sizeOf(Worker) +| @sizeOf(expr_agg.GroupTable));
    _ = ledger.drawExact(worker_credit) orelse return null;
    defer ledger.release(worker_credit);
    armed.* = true;
    if (args.taken) |taken| taken.insert(.grouped_distinct_bitmap);
    var scan_args = args;
    scan_args.ledger = ledger;
    if (scan_args.decode_batch_rows == 0) scan_args.decode_batch_rows = owner_groups.batchRows(null);
    const run = runRecordWorkers(gpa, arena, scan_args, metas, plan, work, calls, keys, sinks, starts, outputs, timings) catch |e| {
        if (refused.load(.monotonic)) if (args.taken) |taken| taken.remove(.decode_memory);
        return e;
    };
    const span = profile.Span.begin(profile.threadOf(args.profiler, .main));
    state.finish(WORKER_STACK_SIZE);
    span.end(.merge, profile.args(.{geometry.parts}));
    var n: usize = 0;
    for (state.first[0..geometry.groups]) |first| if (first != grouped_bitmap.none) {
        n += 1;
    };
    const slots = try a.alloc(MergedSlot, n);
    var at: usize = 0;
    for (state.first[0..geometry.groups], 0..) |first, id| if (first != grouped_bitmap.none) {
        slots[at] = .{ .key = &.{}, .first = first, .idx = id };
        at += 1;
    };
    if (!args.unordered) try sortSlotsByFirst(a, slots, workers);
    const View = struct {
        fn key(_: *const anyopaque, i: usize) u128 {
            return i;
        }
        fn integer(ctx: *const anyopaque, i: usize, _: usize) anyerror!?i128 {
            const s: *const grouped_bitmap.State = @ptrCast(@alignCast(ctx));
            return s.counts[i];
        }
        fn value(ctx: *const anyopaque, _: std.mem.Allocator, i: usize, call: usize) anyerror!AggValue {
            return .{ .i = (try integer(ctx, i, call)).? };
        }
    };
    const types = try arena.alloc(GroupColType, outputs.len);
    const key_types = try a.alloc(KeyType, keys.len);
    for (keys, key_types) |key, *ty| ty.* = keyTypeFromExpr(key);
    for (outputs, types) |out, *ty| ty.* = .{
        .lane = .i64,
        .nullable = true,
        .source = if (out.source == .key) leafSchemaElem(&metas[0], keys[out.source.key].col_ref.col_idx) else null,
    };
    const row_source: RowSource = .{ .slots = slots, .outputs = outputs, .calls = calls, .key_types = key_types, .key_exprs = keys, .accs = &.{}, .folded = false, .fixed_keys = false, .identity = &identity, .owner = .{ .ctx = &state, .key = View.key, .integer = View.integer, .value = View.value } };
    const typed = args.typed_answer and args.result_order.keys.len == 0 and args.result_order.limit == null and
        args.result_order.offset == 0 and args.result_order.having == null and args.result_order.hidden.len == 0;
    var output_charge = answerBytesParallel(slots, types, key_types, typed, workers) +| outputNamesBytes(outputs);
    _ = ledger.drawExact(output_charge) orelse return error.ExceededMemoryBudget;
    defer ledger.release(output_charge);
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    const names = try gpa.alloc([]const u8, outputs.len);
    @memset(names, "");
    output.group_cols = names;
    for (outputs, names) |out, *name| name.* = try gpa.dupe(u8, out.name);
    if (typed) {
        output.typed = .{ .rows = 0, .columns = &.{} };
        try buildGroupColumns(gpa, &output.typed.?, row_source, types, workers);
    } else {
        const out_rows = try gpa.alloc([]const AggValue, n);
        @memset(out_rows, &.{});
        output.group_rows = out_rows;
        try buildGroupRows(gpa, &output.slab, row_source, out_rows, workers);
    }
    for (work) |item| freeOwnedAccumulatorStrings(gpa, item.accumulators);
    if (args.ledger != null) {
        output_charge = 0;
        worker_credit = 0;
    }
    var result = pairResult(args, plan, run, output, .{ .accumulators = &.{}, .agg_calls = calls, .group_col_types = types });
    result.distinct_pairs = false;
    result.grouped_distinct_bitmap = true;
    return result;
}

/// A DISTINCT program uses one exact pair identity, plus optional count(*) calls sharing its duplicate weights.
/// Other aggregates retain the ordinary partition merge; no partial result crosses an identity refusal.
fn inlinePairAnswer(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    requested: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    if (try inlineBitmapAnswer(gpa, arena, args, metas, plan, work, calls, keys_opt, outputs_opt, requested, timings, explain_only)) |answer| return answer;
    if (!args.integer_records or args.distinct_pairs == .off or !allRescannable(args.inputs) or work.len == 0)
        return null;
    var distinct: ?usize = null;
    for (calls, 0..) |call, i| {
        if (call.where != null or call.state or call.offset != 0 or call.result != .i64) return null;
        if (call.func == .count_distinct) {
            if (distinct != null or call.arg == null or call.arg.? != .col_ref) return null;
            distinct = i;
        } else if (call.func != .count or call.arg != null) return null;
    }
    const di = distinct orelse return null;
    const keys = keys_opt orelse &.{};
    const outputs = outputs_opt orelse &.{};
    if (args.distinct_pairs == .auto and keys.len == 0) return null;
    // Single-key owners use a checked raw certificate, so dictionary fallback pages cannot force a replay.
    // String identities keep the existing sets/sketch choice; forced owners still exercise retained dictionaries.
    const automatic_single = args.distinct_pairs == .auto and keys.len == 1;
    for (outputs) |out| if (out.derived != null) return null;
    const input_rows = RecordOrdinals.rows(metas) orelse return null;
    if (input_rows >= @as(usize, 1) << 31) return null;
    var rows: usize = 0;
    for (work) |item| rows +|= @intCast(metas[item.file].row_groups.items[item.rg].num_rows);
    if (rows == 0 or (rows < args.integer_records_min_rows and args.distinct_pairs != .on)) return null;
    const axes = try arena.alloc(expr_ast.Expr, keys.len + 1);
    @memcpy(axes[0..keys.len], keys);
    axes[keys.len] = calls[di].arg.?;
    for (axes) |axis| {
        if (axis != .col_ref) return null;
        const c = axis.col_ref;
        if (c.expr_type != .i64 and c.expr_type != .str) return null;
        for (work) |item| {
            const cm = metas[item.file].row_groups.items[item.rg].columns.items[c.col_idx].meta_data orelse return null;
            if (metas[item.file].getColumnLevels(cm.path_in_schema.items).max_rep != 0) return null;
        }
    }
    // Rescannable readers retain a complete mapping for planning/replay. Union only dictionary pages from that
    // mapping; it never borrows a released remote window or depends on the streaming reader's current position.
    const files = try arena.alloc(ndv.File, args.inputs.len);
    for (args.inputs, files) |input, *file| {
        const bytes = input.plan_bytes orelse input.bytes;
        if (input.logical_size != 0 and input.logical_size != bytes.len) return null;
        file.* = .{ .bytes = bytes, .local = !std.mem.startsWith(u8, input.name, "s3://") };
    }
    const workers = @min(requested, owner_groups.max_workers);
    var domain: ?agg_dense.Domain = null;
    defer if (domain) |*d| d.deinit(gpa);
    var raw = if (automatic_single) try pairRawIdentity(gpa, arena, metas, axes, args.scan_all) else null;
    errdefer if (raw) |*p| p.deinit(gpa);
    if (automatic_single and raw == null) return null;
    // The retained dictionary identity cannot bind a chunk containing non-dictionary data. Decline known
    // fallback before building its union; missing encoding_stats remain speculative, and forced owners replay.
    if (raw == null and args.distinct_pairs == .auto) for (axes) |axis| for (work) |item| {
        const cm = metas[item.file].row_groups.items[item.rg].columns.items[axis.col_ref.col_idx].meta_data.?;
        if (cm.encoding_stats) |stats| for (stats.items) |e| {
            if (e.count <= 0 or (e.page_type != @backingInt(schema.PageType.DATA_PAGE) and
                e.page_type != @backingInt(schema.PageType.DATA_PAGE_V2))) continue;
            if (e.encoding != @backingInt(schema.Encoding.PLAIN_DICTIONARY) and
                e.encoding != @backingInt(schema.Encoding.RLE_DICTIONARY)) return null;
        };
    };
    if (raw == null and args.encoded and args.ndv_union)
        domain = try ndv.retainIdentity(gpa, arena, files, metas, axes, workers, args.max_memory, input_rows + 1);
    var identity = if (raw) |p| p else (try key_pack.Plan.init(gpa, axes, if (domain) |*d| d else null)) orelse return null;
    raw = null;
    defer identity.deinit(gpa);
    const top = if (keys_opt != null) countCut(outputs, calls, args.result_order) else null;
    if (identity.fitsBits(u64)) {
        if (top) |cut| if (cut.k > 0) return pairAnswerBits(
            u64,
            true,
            gpa,
            arena,
            args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            &identity,
            di,
            rows,
            input_rows,
            workers,
            cut,
            timings,
            explain_only,
        );
        return pairAnswerBits(
            u64,
            false,
            gpa,
            arena,
            args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            &identity,
            di,
            rows,
            input_rows,
            workers,
            null,
            timings,
            explain_only,
        );
    }
    if (top) |cut| if (cut.k > 0) return pairAnswerBits(
        u128,
        true,
        gpa,
        arena,
        args,
        metas,
        plan,
        work,
        calls,
        keys,
        outputs,
        &identity,
        di,
        rows,
        input_rows,
        workers,
        cut,
        timings,
        explain_only,
    );
    return pairAnswerBits(
        u128,
        false,
        gpa,
        arena,
        args,
        metas,
        plan,
        work,
        calls,
        keys,
        outputs,
        &identity,
        di,
        rows,
        input_rows,
        workers,
        null,
        timings,
        explain_only,
    );
}

fn pairRawIdentity(gpa: std.mem.Allocator, arena: std.mem.Allocator, metas: []const schema.FileMetaData, axes: []const expr_ast.Expr, scan_all: bool) !?key_pack.Plan {
    const fields = try arena.alloc(key_pack.RawField, axes.len);
    for (axes, fields) |axis, *field| {
        if (axis != .col_ref) return null;
        const key = axis.col_ref;
        if (key.physical_type != .INT32 and key.physical_type != .INT64) return null;
        field.* = .{ .bits = if (key.physical_type == .INT32) 32 else 64, .signed = !key.unsigned_32 and !key.unsigned_64 };
        if (scan_all) continue;
        var lo: i128 = std.math.maxInt(i128);
        var hi: i128 = std.math.minInt(i128);
        const complete = complete: for (metas) |*meta| {
            for (meta.row_groups.items) |*rg| {
                if (rg.num_rows == 0) continue;
                const bounds = @import("parquet/statistics.zig").chunkStats(rg, key.col_idx, meta, .corroborated).bounds orelse break :complete false;
                const width: usize = if (key.physical_type == .INT32) 4 else 8;
                if (bounds.min.len != width or bounds.max.len != width) break :complete false;
                const low: i128 = if (width == 4)
                    if (key.unsigned_32) std.mem.readInt(u32, bounds.min[0..4], .little) else std.mem.readInt(i32, bounds.min[0..4], .little)
                else if (key.unsigned_64) std.mem.readInt(u64, bounds.min[0..8], .little) else std.mem.readInt(i64, bounds.min[0..8], .little);
                const high: i128 = if (width == 4)
                    if (key.unsigned_32) std.mem.readInt(u32, bounds.max[0..4], .little) else std.mem.readInt(i32, bounds.max[0..4], .little)
                else if (key.unsigned_64) std.mem.readInt(u64, bounds.max[0..8], .little) else std.mem.readInt(i64, bounds.max[0..8], .little);
                lo = @min(lo, low);
                hi = @max(hi, high);
            }
        } else true;
        if (!complete or lo > hi) continue;
        var bits: u7 = 1;
        while (bits < field.bits) : (bits += 1) {
            const candidate: key_pack.RawField = .{ .bits = bits, .signed = field.signed };
            _ = candidate.encode(lo) catch continue;
            _ = candidate.encode(hi) catch continue;
            field.bits = bits;
            break;
        }
    }
    return key_pack.Plan.initFields(gpa, axes, null, fields);
}

/// A covered local key dictionary bounds the number of per-RG sets. A compact argument range makes the
/// existing sets/bitmaps a credible alternative; unknown or wide domains keep the pair owner's admission.
fn pairLocalSetWork(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys: []const expr_ast.Expr,
    distinct: usize,
    rows: usize,
    workers: usize,
) !?usize {
    if (!args.plain_rules or args.distinct_pairs != .auto or args.integer_records_min_rows == 0 or args.scan_all or
        !args.ndv_union or keys.len != 1 or plan.query.filter != null) return null;
    const arg = calls[distinct].arg.?.col_ref;
    if (arg.physical_type != .INT64 or arg.unsigned_64) return null;
    var range: IntegerRangeHint = .{};
    for (work) |item| range.include(&metas[item.file].row_groups.items[item.rg], &metas[item.file], arg.col_idx);
    if (!range.small(rows)) return null;
    const files = try arena.alloc(ndv.File, args.inputs.len);
    for (args.inputs, files) |input, *file| file.* = .{
        .bytes = input.plan_bytes orelse input.bytes,
        .local = !std.mem.startsWith(u8, input.name, "s3://"),
    };
    // Headers only: neither decompress nor build another union to decide whether to avoid this owner.
    const stat = try ndv.collect(gpa, arena, files, metas, keys, workers, args.max_memory, false);
    const entries = std.math.cast(usize, stat.entries orelse return null) orelse return null;
    const key_bytes: usize = 1 + if (keys[0].col_ref.physical_type == .INT32) @as(usize, 4) else 8;
    const key_table_bytes = expr_agg.GroupTable.variableEntryBytes(key_bytes, calls.len);
    // A cache-resident local group index also permits effective pair-cache coalescing. Its joint value NDV is
    // unknown: comparing worst-case owner rows with just the set objects would systematically underprice sets.
    // Keep the existing pair trial in that case; only price a table that exceeds its active workers' L2 shares here.
    const l2 = @import("hw.zig").l2BytesPerWorkerOr(640 << 10);
    if (entries *| key_table_bytes <= workers *| l2) return null;
    const set_bytes = key_table_bytes +| @sizeOf(expr_agg.DistinctSet);
    // Read the key/value and table pointers, then visit the local distinct values in the final set merge.
    return entries *| set_bytes +| rows *| (key_bytes + @sizeOf(u64) * 2 + @sizeOf(usize) * 2);
}

fn pairAnswerBits(
    comptime Bits: type,
    comptime top: bool,
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys: []const expr_ast.Expr,
    outputs: []const BoundOutputColumn,
    identity: *const key_pack.Plan,
    distinct: usize,
    rows: usize,
    input_rows: usize,
    workers: usize,
    cut: ?CountCut,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const P = @import("owner_distinct.zig").Pipeline(Bits);
    const G = P.Groups;
    const F = @import("owner_result.zig").Full(G.Group);
    const T = @import("owner_result.zig").Top(G.Group, bool, struct {
        fn worse(by_distinct: bool, a: G.Group, b: G.Group) std.math.Order {
            const x = if (by_distinct) a.integer(0).? else a.weight;
            const y = if (by_distinct) b.integer(0).? else b.weight;
            return if (x != y) std.math.order(x, y) else std.math.order(b.first, a.first);
        }
    }.worse);
    const prefix = try P.Prefix.init(identity);
    const cost = @import("owner_cost.zig");
    const pq = cost.quote(Bits, &.{}, u32, rows, rows, workers, 0, args.byte_top_partitions) orelse return null;
    var null_rows: usize = 0;
    for (work) |item| {
        const rg = metas[item.file].row_groups.items[item.rg];
        const cm = rg.columns.items[identity.keys[identity.keys.len - 1].col_idx].meta_data.?;
        const n = if (cm.statistics) |st| st.null_count orelse rg.num_rows else rg.num_rows;
        if (n < 0 or n > rg.num_rows) return null;
        null_rows +|= @intCast(n);
    }
    var pair_bound: usize = rows;
    if (identity.encoding.source == .dictionary) {
        var product: u128 = 1;
        for (identity.radices) |r| product = std.math.mul(u128, product, r) catch rows;
        pair_bound = @intCast(@min(rows, product));
    }
    // A NULL presence row or one completed pair is the only possible second-stage contribution. Its duplicate
    // weight still uses the original row bound. Global DISTINCT therefore reserves by values, never rows twice.
    // Footer NULL counts are speculative: the weighted owner requests whole-attempt replay if physical records
    // exceed this quote, even when scatter tail capacity happened to accommodate them.
    const group_records = @min(rows, pair_bound +| null_rows);
    const gq = cost.quote(
        Bits,
        &.{.present_count},
        u32,
        group_records,
        group_records,
        workers,
        0,
        args.byte_top_partitions,
    ) orelse return null;
    if (top and args.plain_rules and args.distinct_pairs == .auto and args.integer_records_min_rows != 0) {
        // Ask the existing admission, including its compression/range, schema, top-H and memory checks. This
        // prices a real alternative, not a raw integer plan that cannot execute this query.
        var legacy_args = args;
        if (try inlineIntegerAnswer(gpa, arena, &legacy_args, metas, plan, work, calls, keys, outputs, workers, timings, .{ .refined = null }, true)) |legacy| {
            if (legacy.layout == .integer_distinct_top_h) {
                const O = owner_groups.IntSumTop;
                // One key-owner reduction sorts its complete (key,value) records and counts directly into H.
                // The packed route materializes pair groups and then reduces them by group a second time.
                const legacy_work = rows *| (@sizeOf(O.Record) + @sizeOf(O.Group) + @sizeOf(u64)) +|
                    workers *| cut.?.k *| @sizeOf(O.Group);
                const pair_work = pq.work +| gq.work +| workers *| cut.?.k *| @sizeOf(G.Group);
                if (legacy_work <= pair_work) {
                    if (!explain_only) if (args.taken) |taken| taken.insert(.plain_rule);
                    return null;
                }
            }
        }
    }
    if (try pairLocalSetWork(gpa, arena, args, metas, plan, work, calls, keys, distinct, rows, workers)) |sets| {
        if (sets <= pq.work +| gq.work) {
            if (!explain_only) if (args.taken) |taken| taken.insert(.plain_rule);
            return null;
        }
    }
    const result_credit = if (top) T.bytes(workers, cut.?.k) else F.bytes(workers, gq.parts);
    const domain_bytes = if (identity.domain) |d| d.bytes else 0;
    const pack_rows = owner_groups.batchRows(null);
    const scratch = domain_bytes +| identity.retainedBytes() +| workers *| pack_rows *| @sizeOf(Bits) +|
        workers *| (identity.keys.len *| @sizeOf(key_pack.Plan.Binding) +| @sizeOf(P.Sink) +|
            @sizeOf(P.Reducer) +| @sizeOf(consumer.RecordSink) +| @sizeOf(Worker) +| @sizeOf(expr_agg.GroupTable)) +|
        work.len *| (@sizeOf(P.Sink.Source) +| @sizeOf(u32));
    const peak = scratch +| pq.records +| gq.records +| @max(pq.finish, gq.finish) +| result_credit;
    if (peak > args.max_memory) return null;
    if (explain_only) return .{ .layout = .pair_distinct, .reservation = peak };
    var private_ledger: core_memory.SharedBudget = .{ .limit = args.max_memory };
    const ledger = args.ledger orelse &private_ledger;
    _ = ledger.drawExact(scratch) orelse return null;
    var held: usize = 0;
    defer ledger.release(scratch - held);
    const pairs = (try P.Pairs.State.init(gpa, ledger, input_rows, rows, workers, pq.parts)) orelse return null;
    var leave_records = false;
    defer if (!leave_records) pairs.deinit();
    const groups = (try G.State.initWeighted(
        gpa,
        ledger,
        input_rows,
        rows,
        group_records,
        workers,
        gq.parts,
    )) orelse return null;
    defer if (!leave_records) groups.deinit();
    const result = if (top)
        T.init(gpa, ledger, workers, cut.?.k, cut.?.a_idx == distinct)
    else
        F.init(gpa, ledger, workers, gq.parts);
    var receiver = result catch |e| {
        if (e == error.ExceededMemoryBudget) return null;
        return e;
    };
    defer receiver.deinit();
    var temporary = std.heap.ArenaAllocator.init(gpa);
    defer temporary.deinit();
    const a = temporary.allocator();
    const starts = try a.alloc(u32, work.len);
    if (!RecordOrdinals.fill(metas, work, starts)) return error.BadColumn;
    const sources = try a.alloc(P.Sink.Source, work.len);
    for (sources, work) |*s, item| s.* = .{ .file = item.file, .rg = item.rg };
    const adapters = try a.alloc(P.Sink, workers);
    const sinks = try a.alloc(consumer.RecordSink, workers);
    const reducers = try a.alloc(P.Reducer, workers);
    var refused: std.atomic.Value(bool) = .init(false);
    for (adapters, sinks, reducers, pairs.locals, groups.locals) |*s, *sink, *r, *pl, *gl| {
        s.* = .{
            .pairs = pl,
            .groups = gl,
            .identity = identity,
            .prefix = prefix,
            .sources = sources,
            .bindings = try a.alloc(key_pack.Plan.Binding, identity.keys.len),
            .pack_buffer = try a.alloc(Bits, pack_rows),
            .refused = &refused,
        };
        sink.* = .{ .selected = .{ .ctx = s, .startFn = P.Sink.startErased, .batchFn = P.Sink.batchErased } };
        r.* = .{ .local = gl, .prefix = prefix, .count_rows = calls.len > 1 };
    }
    if (args.taken) |taken| taken.insert(.integer_records);
    const pair_keys = try a.alloc(expr_ast.Expr, identity.keys.len);
    for (pair_keys, identity.keys) |*k, ref| k.* = .{ .col_ref = ref };
    const run = runRecordWorkers(
        gpa,
        arena,
        args,
        metas,
        plan,
        work,
        calls,
        pair_keys,
        sinks,
        starts,
        outputs,
        timings,
    ) catch |e| {
        if (refused.load(.monotonic)) if (args.taken) |taken| taken.remove(.decode_memory);
        return e;
    };
    const span = profile.Span.begin(profile.threadOf(args.profiler, .main));
    try pairs.finish(reducers, P.Reducer.receive);
    try groups.finish(receiver.receivers, if (top) T.Receiver.receive else F.Receiver.receive);
    span.end(.merge, profile.args(.{gq.parts}));
    const top_groups = if (top) receiver.finish() else &.{};
    const n = if (top) top_groups.len else receiver.count();
    const slots = try a.alloc(MergedSlot, n);
    if (top) {
        for (top_groups, slots, 0..) |g, *s, i| s.* = .{ .key = &.{}, .first = g.first, .idx = i };
    } else try receiver.fill(MergedSlot, slots, struct {
        fn make(g: G.Group, index: u64) MergedSlot {
            return .{ .key = &.{}, .first = g.first, .idx = @intCast(index) };
        }
    }.make);
    if (!args.unordered) try sortSlotsByFirst(a, slots, workers);
    const View = struct {
        groups: []const G.Group,
        full: ?*F,
        distinct: usize,
        fn at(v: *const @This(), i: usize) *const G.Group {
            return if (v.full) |f| f.at(i) else &v.groups[i];
        }
        fn key(ctx: *const anyopaque, i: usize) u128 {
            const v: *const @This() = @ptrCast(@alignCast(ctx));
            return v.at(i).key;
        }
        fn integer(ctx: *const anyopaque, i: usize, call: usize) anyerror!?i128 {
            const v: *const @This() = @ptrCast(@alignCast(ctx));
            return if (call == v.distinct) v.at(i).integer(0) else v.at(i).weight;
        }
        fn value(ctx: *const anyopaque, _: std.mem.Allocator, i: usize, call: usize) anyerror!AggValue {
            return .{ .i = (try integer(ctx, i, call)).? };
        }
    };
    const view: View = .{ .groups = top_groups, .full = if (top) null else receiver, .distinct = distinct };
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    const names_credit = outputNamesBytes(outputs);
    var output_charge: usize = 0;
    defer ledger.release(output_charge);
    if (args.group_by == null) {
        output_charge = calls.len *| @sizeOf(AggOutputItem);
        for (calls) |c| output_charge +|= c.alias.len;
        _ = ledger.drawExact(output_charge) orelse {
            output_charge = 0;
            return error.ExceededMemoryBudget;
        };
        const items = try gpa.alloc(AggOutputItem, calls.len);
        @memset(items, .{ .alias = "", .value = .null_val });
        output.aggs = items;
        const accs = try arena.alloc(expr_agg.Accumulator, calls.len);
        for (items, calls, accs, 0..) |*item, call, *acc, ci| {
            const count: u64 = if (n == 0) 0 else @intCast((try View.integer(&view, slots[0].idx, ci)).?);
            item.* = .{ .alias = try gpa.dupe(u8, call.alias), .value = .{ .i = count } };
            acc.* = .{ .count = count };
        }
        for (work) |item| freeOwnedAccumulatorStrings(gpa, item.accumulators);
        // The retained scalar output is released by the enclosing query ledger with its output.
        const finished = try countedCalls(arena, calls, distinct);
        const sources_out = try arena.alloc(?schema.SchemaElement, calls.len);
        @memset(sources_out, null);
        if (args.ledger != null) {
            held = workers *| (@sizeOf(Worker) +| @sizeOf(expr_agg.GroupTable));
            output_charge = 0;
        }
        return pairResult(args, plan, run, output, .{
            .accumulators = accs,
            .agg_calls = finished,
            .agg_sources = sources_out,
        });
    }
    const types = try arena.alloc(GroupColType, outputs.len);
    const key_types = try a.alloc(KeyType, keys.len);
    for (keys, key_types) |key, *ty| ty.* = keyTypeFromExpr(key);
    var key_bytes: usize = 0;
    for (outputs, types) |out, *ty| {
        ty.* = .{
            .lane = if (out.source == .key and key_types[out.source.key] == .string) .string else .i64,
            .nullable = out.source == .key or calls[out.source.agg].func != .count,
            .source = if (out.source == .key) leafSchemaElem(&metas[0], keys[out.source.key].col_ref.col_idx) else null,
        };
        if (out.source == .key) if (identity.domain) |d| switch (d.axes[out.source.key].values) {
            .bytes => |values| {
                var widest: usize = 0;
                for (values) |v| widest = @max(widest, v.len);
                key_bytes +|= widest;
            },
            else => {},
        };
    }
    const row_source: RowSource = .{
        .slots = slots,
        .outputs = outputs,
        .calls = calls,
        .key_types = key_types,
        .key_exprs = keys,
        .accs = &.{},
        .folded = false,
        .fixed_keys = false,
        .identity = identity,
        .owner = .{ .ctx = &view, .key = View.key, .integer = View.integer, .value = View.value },
    };
    const typed = args.typed_answer and args.result_order.keys.len == 0 and args.result_order.limit == null and
        args.result_order.offset == 0 and args.result_order.having == null and args.result_order.hidden.len == 0;
    output_charge = answerBytesParallel(slots, types, key_types, typed, workers) +| names_credit +| n *| key_bytes;
    _ = ledger.drawExact(output_charge) orelse {
        output_charge = 0;
        return error.ExceededMemoryBudget;
    };
    const names = try gpa.alloc([]const u8, outputs.len);
    @memset(names, "");
    output.group_cols = names;
    for (outputs, names) |out, *name| name.* = try gpa.dupe(u8, out.name);
    if (typed) {
        output.typed = .{ .rows = 0, .columns = &.{} };
        try buildGroupColumns(gpa, &output.typed.?, row_source, types, workers);
    } else {
        const out_rows = try gpa.alloc([]const AggValue, n);
        @memset(out_rows, &.{});
        output.group_rows = out_rows;
        try buildGroupRows(gpa, &output.slab, row_source, out_rows, workers);
    }
    for (work) |item| freeOwnedAccumulatorStrings(gpa, item.accumulators);
    if (args.ledger != null) {
        held = workers *| (@sizeOf(Worker) +| @sizeOf(expr_agg.GroupTable));
        output_charge = 0; // retain the successful output credit in the query's enclosing ledger
    }
    // Keep the records and their full charge until process exit, as the ordinary table path does. A top-H
    // answer owns its copied keys and never reads these states again; all failure paths still deinitialize them.
    leave_records = top and args.leave_regions and !std.debug.runtime_safety;
    return pairResult(args, plan, run, output, .{ .accumulators = &.{}, .agg_calls = calls, .group_col_types = types });
}

fn pairResult(
    args: MultiAggArgs,
    plan: *const agg_plan.Plan,
    run: RecordRun,
    output: AggOutput,
    state: ScanState,
) MultiAggResult {
    var bytes_in: u64 = 0;
    for (args.inputs) |input| bytes_in +|= if (input.logical_size != 0) input.logical_size else input.bytes.len;
    return .{
        .files_in = args.inputs.len,
        .rows_in = run.rows_in,
        .rows_scanned = run.rows_scanned,
        .rows_matched = run.rows_matched,
        .bytes_in = bytes_in,
        .row_groups_in = run.row_groups_in,
        .row_groups_pruned = run.row_groups_pruned,
        .row_groups_full_match = run.row_groups_full_match,
        .cols_stat_pruned = plan.cols_stat_pruned,
        .timings = run.timings,
        .output = output,
        .distinct_pairs = true,
        .part_agg = true,
        .state = state,
    };
}

// Scalar cardinality reuses count-only owner records and the complete partition fold.
fn inlineDistinctAnswer(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    n_workers: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const order = args.result_order;
    if (args.group_by != null or args.filter != null or !allRescannable(args.inputs) or calls.len != 1 or
        n_workers > 64 or
        order.keys.len != 0 or order.limit != null or order.offset != 0 or order.having != null or
        order.hidden.len != 0) return null;
    const call = calls[0];
    if (call.func != .count_distinct or call.where != null or call.offset != 0 or call.state or
        call.result != .i64) return null;
    const arg = call.arg orelse return null;
    if (arg != .col_ref) return null;
    const key = arg.col_ref;
    const codec: owner_groups.Codec = if (key.physical_type == .INT64 and key.expr_type == .i64 and
        !key.unsigned_64) .int64 else if (key.physical_type == .BYTE_ARRAY and key.expr_type == .str)
        .bytes
    else
        return null;
    if (if (codec == .int64) !args.integer_records else !args.byte_records) return null;
    const threshold = if (codec == .int64) args.integer_records_min_rows else args.byte_records_min_rows;
    const starts = try arena.alloc(u32, work.len);
    var rows: usize = 0;
    var key_range: IntegerRangeHint = .{};
    for (work, starts) |item, *start| {
        if (rows >= std.math.maxInt(u32)) return null;
        start.* = @intCast(rows);
        const meta = &metas[item.file];
        const rg = &meta.row_groups.items[item.rg];
        const cm = rg.columns.items[key.col_idx].meta_data orelse return null;
        if (meta.getColumnLevels(cm.path_in_schema.items).max_rep != 0) return null;
        if (codec == .bytes) if (cm.statistics) |st| {
            for ([_]?[]const u8{ st.min_value, st.max_value, st.min, st.max }) |bound| if (bound) |bytes|
                if (bytes.len > 15) return null;
        };
        const n = rg.num_rows;
        if (n < 0) return null;
        rows +|= @intCast(n);
        if (codec == .int64 and threshold != 0) key_range.include(rg, meta, key.col_idx);
    }
    if (rows == 0 or rows < threshold) return null;
    // A narrow footer range favors D1 even when PLAIN pages make dictionary cardinality unknown.
    // This only declines the owner attempt; ordinary decoding still validates every value.
    if (codec == .int64 and threshold != 0 and key_range.small(rows)) return null;
    if (threshold != 0) if (ndv.footerEntries(metas, &.{arg})) |guess| if (guess < rows / 4) return null;
    switch (codec) {
        inline else => |c| {
            const Owner = owner_groups.Owner(.count_top, c);
            if (!owner_groups.admitsRows(c, rows)) return null;
            const batch_rows = if (args.decode_batch_rows != 0)
                args.decode_batch_rows
            else
                owner_groups.batchRows(args.byte_top_batch_rows);
            const parts = Owner.partitionCount(rows, n_workers, batch_rows, args.byte_top_partitions);
            const credit = @sizeOf(AggOutputItem) +| call.alias.len;
            const quote = Owner.State.reservation(rows, n_workers, parts, 0, credit);
            if (quote > args.max_memory) return null;
            if (explain_only) return .{
                .layout = if (c == .int64) .integer_distinct else .byte_distinct,
                .reservation = quote,
            };
            if (c == .bytes and !try shortSampleMayFit(gpa, args, metas, work, key.col_idx, 15)) return null;
            const state = (try Owner.State.initCardinality(
                gpa,
                args.ledger,
                rows,
                n_workers,
                key.col_idx,
                parts,
                credit,
            )) orelse return null;
            defer state.deinit();
            if (args.taken) |taken| taken.insert(.integer_records);
            const sinks = try arena.alloc(consumer.RecordSink, n_workers);
            for (sinks, state.locals) |*sink, *local|
                sink.* = if (c == .int64) .{ .integer_count_top = .{ .local = local } } else .{ .byte_count_top = local };
            var decoded = args;
            decoded.decode_batch_rows = batch_rows;
            const run = runRecordWorkers(
                gpa,
                arena,
                decoded,
                metas,
                plan,
                work,
                calls,
                &.{arg},
                sinks,
                starts,
                &.{},
                timings,
            ) catch |e| {
                if (state.width_refused.load(.monotonic)) if (args.taken) |taken| taken.remove(.decode_memory);
                return e;
            };
            const merge_span = profile.Span.begin(profile.threadOf(args.profiler, .main));
            state.finishSelected(@intCast(run.rows_matched)) catch |e|
                return if (e == error.OutOfMemory) error.ExceededMemoryBudget else e;
            merge_span.end(.merge, profile.args(.{parts}));
            // Scalar writers finalize ScanState, so retain the finished count as well as the JSON value.
            const finished_calls = try countedCalls(arena, calls, 0);
            const finished = try arena.alloc(expr_agg.Accumulator, 1);
            finished[0] = .{ .count = @intCast(state.group_count) };
            const alias = gpa.dupe(u8, call.alias) catch return error.ExceededMemoryBudget;
            errdefer gpa.free(alias);
            const items = gpa.alloc(AggOutputItem, 1) catch return error.ExceededMemoryBudget;
            items[0] = .{ .alias = alias, .value = .{ .i = @intCast(state.group_count) } };
            if (args.ledger != null) state.charged -= credit;
            for (work) |item| freeOwnedAccumulatorStrings(gpa, item.accumulators);
            var bytes_in: u64 = 0;
            for (args.inputs) |in| bytes_in += if (in.logical_size != 0) in.logical_size else in.bytes.len;
            return .{
                .files_in = args.inputs.len,
                .rows_in = run.rows_in,
                .rows_scanned = run.rows_scanned,
                .rows_matched = run.rows_matched,
                .bytes_in = bytes_in,
                .row_groups_in = run.row_groups_in,
                .row_groups_pruned = run.row_groups_pruned,
                .row_groups_full_match = run.row_groups_full_match,
                .cols_stat_pruned = plan.cols_stat_pruned,
                .timings = run.timings,
                .output = .{ .aggs = items },
                .state = .{ .accumulators = finished, .agg_calls = finished_calls, .agg_sources = &.{null} },
            };
        },
    }
}

fn outputNamesBytes(outputs: []const BoundOutputColumn) usize {
    var bytes = outputs.len *| @sizeOf([]const u8);
    for (outputs) |out| bytes +|= out.name.len;
    return bytes;
}

/// Equal-width raw numeric identities avoid a dictionary-wide comparison on every sliced callback. Retain coded
/// identities where they make the physical record narrower, or where strings have no raw numeric image.
fn ownerIdentity(
    gpa: std.mem.Allocator,
    keys: []const expr_ast.Expr,
    domain: ?*const agg_dense.Domain,
) !?key_pack.Plan {
    var best = try key_pack.Plan.init(gpa, keys, null);
    errdefer if (best) |*p| p.deinit(gpa);
    if (domain) |d| if (best == null or !best.?.fitsBits(u64)) {
        var coded = (try key_pack.Plan.init(gpa, keys, d)) orelse return best;
        if (best == null or coded.fitsBits(u64)) {
            if (best) |*p| p.deinit(gpa);
            return coded;
        }
        coded.deinit(gpa);
    };
    return best;
}

fn inlineSharedStrings(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    workers: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const order = args.result_order;
    if (!args.shared_strings or !allRescannable(args.inputs) or !args.plain_rules or
        order.keys.len != 0 or order.limit != null or order.offset != 0 or order.having != null or
        order.hidden.len != 0) return null;
    const scalar = keys_opt == null;
    const key = if (keys_opt) |keys| blk: {
        if (keys.len != 1) return null;
        for (calls) |call| {
            if (call.where != null or call.func == .count_distinct or call.state or call.offset != 0) return null;
            if (call.arg) |arg| {
                if (arg != .col_ref or arg.col_ref.expr_type != .i64 or arg.isBoolean()) return null;
            } else if (call.func != .count) return null;
        }
        for (outputs_opt.?) |out| if (out.derived != null) return null;
        break :blk keys[0];
    } else blk: {
        if (calls.len != 1 or calls[0].func != .count_distinct or calls[0].where != null or calls[0].state)
            return null;
        break :blk calls[0].arg orelse return null;
    };
    if (key != .col_ref or key.col_ref.expr_type != .str or key.col_ref.physical_type != .BYTE_ARRAY)
        return null;
    // Complete dictionaries already avoid row-wise byte hashing. Route wide PLAIN/fallback bytes directly;
    // short keys keep their existing fixed/coded owner. Encoded width is a cost hint, never an identity bound.
    var coded = true;
    var key_bytes: u128 = 0;
    var key_rows: u128 = 0;
    for (work) |item| {
        const rg = &metas[item.file].row_groups.items[item.rg];
        const cm = rg.columns.items[key.col_ref.col_idx].meta_data orelse return null;
        coded = coded and ndv.fullCoverage(&cm);
        key_bytes += @intCast(@max(0, cm.total_uncompressed_size));
        key_rows += @intCast(@max(0, rg.num_rows));
    }
    if (coded or key_bytes < key_rows * (2 * @sizeOf([]const u8))) return null;
    // Packed record scans use an original flat ordinal. Width refusal leaves the established string route intact.
    const rows = RecordOrdinals.rows(metas) orelse return null;
    if (rows >= @as(usize, 1) << 31) return null;
    const folded_calls: []const expr_agg.AggCall = if (scalar) &.{} else calls;
    const worker_credit = workers * (@sizeOf(Worker) + @sizeOf(expr_agg.GroupTable));
    const setup = worker_credit + work.len * @sizeOf(u32) + workers * @sizeOf(consumer.RecordSink) +
        (if (outputs_opt) |outs| outs.len * @sizeOf(GroupColType) else 0);
    const quote = setup +| string_table.State.setupBytes(workers, args.max_memory);
    if (quote > args.max_memory / 4 or
        (args.ledger != null and quote > args.ledger.?.available())) return null;
    if (explain_only) return .{
        .layout = .shared_string_table,
        .reservation = quote,
        .partitions = @as(usize, 1) << partagg.partBits(args.max_memory),
    };
    var own_ledger: core_memory.SharedBudget = .{ .limit = args.max_memory };
    const ledger = args.ledger orelse &own_ledger;
    _ = ledger.drawExact(setup) orelse return null;
    var held: usize = 0;
    defer ledger.release(setup - held);
    var state = (try string_table.State.init(
        gpa,
        ledger,
        folded_calls,
        key.col_ref.col_idx,
        scalar,
        workers,
    )) orelse return null;
    defer state.deinit();
    state.bind();
    const starts = try arena.alloc(u32, work.len);
    if (!RecordOrdinals.fill(metas, work, starts)) return null;
    const sinks = try arena.alloc(consumer.RecordSink, workers);
    for (sinks, state.locals) |*sink, *local| sink.* = .{ .selected = .{
        .ctx = local,
        .startFn = string_table.Sink.startErased,
        .batchFn = string_table.Sink.batchErased,
    } };
    const previous_block = ledger.block;
    ledger.block = expr_agg.SharedBudget.blockFor(args.max_memory, workers + state.parts.len);
    defer ledger.block = previous_block;
    if (args.taken) |taken| taken.insert(.shared_strings);
    var decoded = args;
    // Record callbacks bypass automatic expression slicing. Bound their producer to the same cache-sized window
    // as the sink, rather than retaining a whole RG's decompressed string pages beside the shared identity.
    if (decoded.auto_decode_batches and decoded.decode_batch_rows == 0 and decoded.expr_batch_rows != 0)
        decoded.decode_batch_rows = string_table.batchRows();
    const run = try runRecordWorkers(
        gpa,
        arena,
        decoded,
        metas,
        plan,
        work,
        calls,
        &.{key},
        sinks,
        starts,
        outputs_opt orelse &.{},
        timings,
    );
    const prof = profile.threadOf(args.profiler, .main);
    const begin = nowMonoNs();
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    var answer_charge: usize = 0;
    defer ledger.release(answer_charge);
    if (scalar) {
        answer_charge = @sizeOf(AggOutputItem) + calls[0].alias.len;
        _ = ledger.drawExact(answer_charge) orelse {
            answer_charge = 0;
            return error.ExceededMemoryBudget;
        };
        const items = try gpa.alloc(AggOutputItem, 1);
        items[0] = .{ .alias = "", .value = .{ .i = state.count() } };
        output.aggs = items;
        items[0].alias = try gpa.dupe(u8, calls[0].alias);
        const accs = try arena.alloc(expr_agg.Accumulator, 1);
        accs[0] = .{ .count = @intCast(state.count()) };
        const finished = try countedCalls(arena, calls, 0);
        const sources = try arena.alloc(?schema.SchemaElement, 1);
        sources[0] = null;
        for (work) |item| freeOwnedAccumulatorStrings(gpa, item.accumulators);
        if (args.ledger != null) {
            held = worker_credit;
            answer_charge = 0;
        }
        var result = pairResult(args, plan, run, output, .{
            .accumulators = accs,
            .agg_calls = finished,
            .agg_sources = sources,
        });
        result.distinct_pairs = false;
        profile.record(prof, .merge, begin, nowMonoNs(), profile.args(.{}));
        return result;
    }
    const outputs = outputs_opt.?;
    var merge_charge: core_memory.Charged = .{ .child = gpa, .budget = ledger };
    const lists = merge_charge.allocator();
    var slots: std.ArrayList(MergedSlot) = .empty;
    defer slots.deinit(lists);
    var accs: std.ArrayList(expr_agg.Accumulator) = .empty;
    defer accs.deinit(lists);
    try fillFromPartitions(
        gpa,
        lists,
        arena,
        state.parts,
        calls,
        outputs,
        order,
        args.unordered,
        null,
        workers,
        &slots,
        &accs,
    );
    if (!args.unordered) try sortSlotsByFirst(lists, slots.items, workers);
    const key_types = [_]KeyType{.string};
    const types = try arena.alloc(GroupColType, outputs.len);
    for (outputs, types) |out, *ty| ty.* = .{
        .lane = if (out.source == .key) .string else if (calls[out.source.agg].func == .avg) .f64 else .i64,
        .nullable = out.source == .key or calls[out.source.agg].func != .count,
        .source = if (out.source == .key)
            leafSchemaElem(&metas[0], key.col_ref.col_idx)
        else
            passThroughSource(calls[out.source.agg], &metas[0]),
    };
    const tables = try lists.alloc(*expr_agg.GroupTable, state.parts.len);
    defer lists.free(tables);
    for (tables, state.parts) |*out, *part| out.* = &part.table;
    output.arena_credit = try output.takeTableArenas(gpa, tables, ledger);
    output.arena_ledger = args.ledger;
    const source: RowSource = .{
        .slots = slots.items,
        .outputs = outputs,
        .calls = calls,
        .key_types = &key_types,
        .key_exprs = &.{key},
        .accs = accs.items,
        .folded = true,
        .fixed_keys = false,
        .borrowed_strings = output.borrowed_strings,
    };
    answer_charge = answerBytesParallel(slots.items, types, &.{}, args.typed_answer, workers) +|
        outputNamesBytes(outputs);
    _ = ledger.drawExact(answer_charge) orelse {
        answer_charge = 0;
        return error.ExceededMemoryBudget;
    };
    const names = try gpa.alloc([]const u8, outputs.len);
    @memset(names, "");
    output.group_cols = names;
    for (outputs, names) |out, *name| name.* = try gpa.dupe(u8, out.name);
    if (args.typed_answer) {
        output.typed = .{ .rows = 0, .columns = &.{} };
        try buildGroupColumns(gpa, &output.typed.?, source, types, workers);
    } else {
        const out_rows = try gpa.alloc([]const AggValue, slots.items.len);
        @memset(out_rows, &.{});
        output.group_rows = out_rows;
        try buildGroupRows(gpa, &output.slab, source, out_rows, workers);
    }
    if (args.ledger != null) {
        held = worker_credit + outputs.len * @sizeOf(GroupColType);
        answer_charge = 0;
    }
    var result = pairResult(args, plan, run, output, .{
        .accumulators = &.{},
        .agg_calls = calls,
        .group_col_types = types,
    });
    result.distinct_pairs = false;
    profile.record(prof, .merge, begin, nowMonoNs(), profile.args(.{}));
    return result;
}

fn inlineSelectedCount(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    domain: ?*const agg_dense.Domain,
    stat: ?NdvStat,
    pass_share: f64,
    requested_workers: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    if (!args.integer_records or !allRescannable(args.inputs)) return null;
    const keys = keys_opt orelse return null;
    const outputs = outputs_opt orelse return null;
    const program = agg_plan.OwnerProgram.init(calls) orelse return null;
    if (program.distinct_arg != null or calls.len == 0) return null;
    if (program.len != 0 and keys.len < 2) return null;
    for (outputs) |out| if (out.derived != null) return null;
    // Preserve P1's nullable INT64 sidecar and 16-byte producer while extending physical INT32 and tuples.
    if (keys.len == 1 and keys[0] == .col_ref and keys[0].col_ref.physical_type == .INT64 and
        !keys[0].col_ref.unsigned_64) return null;
    const order = args.result_order;
    if (order.keys.len != 1 or order.having != null or order.hidden.len != 0) return null;
    if (order.keys[0].column >= outputs.len or outputs[order.keys[0].column].source != .agg) return null;
    const rank_call = calls[outputs[order.keys[0].column].source.agg];
    if (rank_call.func != .count or rank_call.arg != null) return null;
    const limit = order.limit orelse return null;
    const k = std.math.cast(usize, limit +| order.offset) orelse return null;
    if (limit == 0 or k == 0 or k > 1024 or work.len == 0) return null;
    const input_rows = RecordOrdinals.rows(metas) orelse return null;
    if (input_rows >= @as(usize, 1) << 31) return null;
    var rows: usize = 0;
    for (work) |item| {
        const rg = &metas[item.file].row_groups.items[item.rg];
        rows = std.math.add(usize, rows, std.math.cast(usize, rg.num_rows) orelse return null) catch return null;
        for (keys) |key| {
            if (key != .col_ref) return null;
            const cm = rg.columns.items[key.col_ref.col_idx].meta_data orelse return null;
            if (metas[item.file].getColumnLevels(cm.path_in_schema.items).max_rep != 0) return null;
        }
    }
    if (rows < args.integer_records_min_rows) return null;
    var identity = (try ownerIdentity(gpa, keys, domain)) orelse return null;
    defer identity.deinit(gpa);
    const workers = @min(requested_workers, owner_groups.max_workers);
    if (program.len != 0) {
        // The retained domain supplies dictionary identities, not payload or ordinal validity. A checked raw
        // identity uses the same selected sink and whole-attempt replay, including speculative range mismatch.
        if (!identity.fitsBits(u64)) {
            var narrow = (try pairRawIdentity(gpa, arena, metas, keys, args.scan_all)) orelse return null;
            if (!narrow.fitsBits(u64)) {
                narrow.deinit(gpa);
                return null;
            }
            identity.deinit(gpa);
            identity = narrow;
        }
        // OwnerProgram sorts its four slots by kind, retaining distinct columns of the same kind.
        @setEvalBranchQuota(10000);
        inline for (0..5) |sums| inline for (0..5 - sums) |mins|
            inline for (0..5 - sums - mins) |maxes| inline for (0..5 - sums - mins - maxes) |counts| {
                const kinds = comptime blk: {
                    var values: [sums + mins + maxes + counts]owner_groups.Lane = undefined;
                    var at: usize = 0;
                    for (std.enums.values(owner_groups.Lane), [4]usize{ sums, mins, maxes, counts }) |kind, n| {
                        for (0..n) |_| {
                            values[at] = kind;
                            at += 1;
                        }
                    }
                    break :blk values;
                };
                if (comptime kinds.len == 0) continue;
                if (program.matches(&kinds)) return selectedCountBits(
                    u64,
                    &kinds,
                    gpa,
                    arena,
                    args,
                    metas,
                    plan,
                    work,
                    calls,
                    keys,
                    outputs,
                    &identity,
                    if (domain) |d| d.bytes else 0,
                    program,
                    stat,
                    pass_share,
                    input_rows,
                    rows,
                    workers,
                    k,
                    timings,
                    explain_only,
                );
            };
        return null;
    }
    switch (identity.kind()) {
        .dense_u32, .packed_u64 => return selectedCountBits(
            u64,
            &.{},
            gpa,
            arena,
            args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            &identity,
            if (domain) |d| d.bytes else 0,
            program,
            stat,
            pass_share,
            input_rows,
            rows,
            workers,
            k,
            timings,
            explain_only,
        ),
        .packed_u128 => return selectedCountBits(
            u128,
            &.{},
            gpa,
            arena,
            args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            &identity,
            if (domain) |d| d.bytes else 0,
            program,
            stat,
            pass_share,
            input_rows,
            rows,
            workers,
            k,
            timings,
            explain_only,
        ),
        .decline => return null,
    }
}

fn selectedCountBits(
    comptime Bits: type,
    comptime kinds: []const owner_groups.Lane,
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys: []const expr_ast.Expr,
    outputs: []const BoundOutputColumn,
    identity: *const key_pack.Plan,
    domain_credit: usize,
    program: agg_plan.OwnerProgram,
    stat: ?NdvStat,
    pass_share: f64,
    input_rows: usize,
    rows: usize,
    workers: usize,
    k: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const O = owner_groups.Packed(Bits, kinds, u32);
    const S = owner_groups.SelectedOwner(Bits, kinds, u32);
    const T = @import("owner_result.zig").Top(O.Group, bool, struct {
        fn worse(desc: bool, x: O.Group, y: O.Group) std.math.Order {
            if (x.weight != y.weight) return if (desc)
                std.math.order(x.weight, y.weight)
            else
                std.math.order(y.weight, x.weight);
            return std.math.order(y.first, x.first);
        }
    }.worse);
    var key_bytes: usize = 0;
    if (identity.domain) |d| for (outputs) |out| if (out.source == .key)
        switch (d.axes[out.source.key].values) {
            .bytes => |values| {
                var widest: usize = 0;
                for (values) |v| widest = @max(widest, v.len);
                key_bytes +|= std.mem.alignForward(usize, widest, 16) +| 16;
            },
            else => {},
        };
    const names_credit = outputNamesBytes(outputs);
    const per_row = @sizeOf([]const AggValue) +| outputs.len *| @sizeOf(AggValue) +| key_bytes;
    const output_credit = names_credit +| k *| per_row;
    const pack_rows = owner_groups.batchRows(null);
    const scratch_credit = workers *| pack_rows *| @sizeOf(Bits) +| workers *| (keys.len *| @sizeOf(key_pack.Plan.Binding) +|
        @sizeOf(S) +| @sizeOf(consumer.RecordSink) +| @sizeOf(Worker) +| @sizeOf(expr_agg.GroupTable)) +|
        work.len *| (@sizeOf(S.Source) +| @sizeOf(u32)) +| identity.retainedBytes() +| domain_credit +|
        k *| @sizeOf(MergedSlot) +| keys.len *| @sizeOf(KeyType) +| outputs.len *| @sizeOf(GroupColType);
    const result_credit = T.bytes(workers, k) +| scratch_credit +| output_credit;
    const selected: usize = @intFromFloat(@ceil(@as(f64, @floatFromInt(rows)) * std.math.clamp(pass_share, 0, 1)));
    var q = @import("owner_cost.zig").quote(
        Bits,
        kinds,
        u32,
        rows,
        selected,
        workers,
        result_credit,
        args.byte_top_partitions,
    ) orelse return null;
    var compact = false;
    if (program.commonColumn()) if (@import("owner_cost.zig").quoteStorage(
        Bits,
        kinds,
        u32,
        rows,
        selected,
        workers,
        result_credit,
        args.byte_top_partitions,
        true,
    )) |small| if (small.peak < q.peak) {
        q = small;
        compact = true;
    };
    if (q.peak > args.max_memory) return null;
    if (stat) |s| if (args.plain_rules and s.confidence == .upper_bound and
        q.work > selectedGroupBytes(s, calls.len, workers, pass_share)) return null;
    if (explain_only) return .{ .layout = .packed_count_top_h, .reservation = q.peak, .partitions = q.parts };
    var private_ledger: core_memory.SharedBudget = .{ .limit = args.max_memory };
    const ledger = args.ledger orelse &private_ledger;
    const extra_credit = scratch_credit +| output_credit;
    // No input has been consumed: setup funding refusal leaves the ordinary grouping plan available.
    _ = ledger.drawExact(extra_credit) orelse return null;
    var held: usize = 0;
    defer ledger.release(extra_credit - held);
    const state = (try O.State.initStorage(gpa, ledger, input_rows, rows, workers, q.parts, compact)) orelse
        return null;
    var leave_records = false;
    defer if (!leave_records) state.deinit();
    var top = T.init(gpa, ledger, workers, k, args.result_order.keys[0].descending) catch |err| {
        if (err == error.ExceededMemoryBudget) return null;
        return err;
    };
    defer top.deinit();
    var temporary = std.heap.ArenaAllocator.init(gpa);
    defer temporary.deinit();
    const scratch = temporary.allocator();
    const starts = try scratch.alloc(u32, work.len);
    if (!RecordOrdinals.fill(metas, work, starts)) return error.BadColumn;
    const sources = try scratch.alloc(S.Source, work.len);
    for (sources, work) |*s, item| s.* = .{ .file = item.file, .rg = item.rg };
    const adapters = try scratch.alloc(S, workers);
    const sinks = try scratch.alloc(consumer.RecordSink, workers);
    var refused: std.atomic.Value(bool) = .init(false);
    for (adapters, sinks, state.locals) |*adapter, *sink, *local| {
        adapter.* = .{
            .local = local,
            .identity = identity,
            .program = program,
            .sources = sources,
            .bindings = try scratch.alloc(key_pack.Plan.Binding, keys.len),
            .pack_buffer = try scratch.alloc(Bits, pack_rows),
            .refused = &refused,
        };
        sink.* = .{ .selected = .{ .ctx = adapter, .startFn = S.startErased, .batchFn = S.batchErased } };
    }
    if (args.taken) |taken| taken.insert(.integer_records);
    const run = runRecordWorkers(
        gpa,
        arena,
        args,
        metas,
        plan,
        work,
        calls,
        keys,
        sinks,
        starts,
        outputs,
        timings,
    ) catch |e| {
        if (refused.load(.monotonic)) if (args.taken) |taken| taken.remove(.decode_memory);
        return e;
    };
    const prof = profile.threadOf(args.profiler, .main);
    const begin = nowMonoNs();
    try state.finish(top.receivers, T.Receiver.receive);
    const fold_end = nowMonoNs();
    profile.record(prof, .integer_fold, begin, fold_end, profile.args(.{}));
    const groups = top.finish();
    profile.record(prof, .integer_order, fold_end, nowMonoNs(), profile.args(.{}));
    const slots = try scratch.alloc(MergedSlot, groups.len);
    for (groups, slots, 0..) |g, *slot, i| slot.* = .{ .key = &.{}, .first = g.first, .idx = i };
    const View = struct {
        groups: []const O.Group,
        program: agg_plan.OwnerProgram,
        calls: []const expr_agg.AggCall,
        fn key(ctx: *const anyopaque, i: usize) u128 {
            const v: *const @This() = @ptrCast(@alignCast(ctx));
            return v.groups[i].key;
        }
        fn integer(ctx: *const anyopaque, i: usize, ai: usize) anyerror!?i128 {
            const v: *const @This() = @ptrCast(@alignCast(ctx));
            return v.program.integer(v.groups[i], v.calls[ai], null);
        }
        fn value(ctx: *const anyopaque, a: std.mem.Allocator, i: usize, ai: usize) anyerror!AggValue {
            const v: *const @This() = @ptrCast(@alignCast(ctx));
            return materializeOne(a, v.calls[ai], try v.program.accumulator(v.groups[i], v.calls[ai]));
        }
    };
    const view: View = .{ .groups = groups, .program = program, .calls = calls };
    const key_types = try scratch.alloc(KeyType, keys.len);
    for (keys, key_types) |key, *ty| ty.* = keyTypeFromExpr(key);
    const row_source: RowSource = .{
        .slots = slots,
        .outputs = outputs,
        .calls = calls,
        .key_types = key_types,
        .key_exprs = keys,
        .accs = &.{},
        .folded = false,
        .fixed_keys = false,
        .identity = identity,
        .owner = .{ .ctx = &view, .key = View.key, .integer = View.integer, .value = View.value },
    };
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    const types = try arena.alloc(GroupColType, outputs.len);
    const names = try gpa.alloc([]const u8, outputs.len);
    @memset(names, "");
    output.group_cols = names;
    for (outputs, names, types) |out, *name, *ty| {
        name.* = try gpa.dupe(u8, out.name);
        ty.* = .{
            .lane = if (out.source == .key and key_types[out.source.key] == .string) .string else if (out.source == .agg and calls[out.source.agg].func == .avg) .f64 else .i64,
            .nullable = out.source == .key or calls[out.source.agg].func != .count,
            .source = if (out.source == .key)
                leafSchemaElem(&metas[0], keys[out.source.key].col_ref.col_idx)
            else
                passThroughSource(calls[out.source.agg], &metas[0]),
        };
    }
    const out_rows = try gpa.alloc([]const AggValue, groups.len);
    @memset(out_rows, &.{});
    output.group_rows = out_rows;
    try buildGroupRows(gpa, &output.slab, row_source, out_rows, workers);
    // FailureProbe borrows Worker metadata through canonical diagnostics in prepareAggregate. Keep that query
    // arena credit beside output schema/rows; the temporary bindings, sources and finish views are gone.
    if (args.ledger != null) held = workers *| (@sizeOf(Worker) +| @sizeOf(expr_agg.GroupTable)) +|
        outputs.len *| @sizeOf(GroupColType) +| names_credit +| groups.len *| per_row;
    // As for leave_tables, a successful tiny answer in an exiting process leaves consumed records to exit.
    // Their full ledger credit stays held beside encoding; refusals and reusable/library contexts free normally.
    leave_records = kinds.len != 0 and args.leave_regions and !std.debug.runtime_safety;
    var bytes_in: u64 = 0;
    for (args.inputs) |in| bytes_in += if (in.logical_size != 0) in.logical_size else in.bytes.len;
    return .{
        .files_in = args.inputs.len,
        .rows_in = run.rows_in,
        .rows_scanned = run.rows_scanned,
        .rows_matched = run.rows_matched,
        .bytes_in = bytes_in,
        .row_groups_in = run.row_groups_in,
        .row_groups_pruned = run.row_groups_pruned,
        .row_groups_full_match = run.row_groups_full_match,
        .cols_stat_pruned = plan.cols_stat_pruned,
        .timings = run.timings,
        .output = output,
        .part_agg = true,
        .state = .{ .accumulators = &.{}, .agg_calls = calls, .group_col_types = types },
    };
}

/// Retained value-equal axes form a complete tuple identity inside the existing integer COUNT owner.
fn inlinePackedAnswer(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    domain: *const agg_dense.Domain,
    requested_workers: usize,
    timings: Timings,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const n_workers = @min(requested_workers, owner_groups.max_workers);
    const order = args.result_order;
    if (!args.integer_records or !args.encoded or !allRescannable(args.inputs) or
        calls.len != 1 or
        order.having != null or order.hidden.len != 0 or order.keys.len != 1 or !order.keys[0].descending)
        return null;
    const keys = keys_opt orelse return null;
    const outputs = outputs_opt orelse return null;
    if (keys.len < 2 or keys.len != domain.axes.len or domain.packedIds() == null) return null;
    const call = calls[0];
    if (call.func != .count or call.arg != null or call.where != null or call.offset != 0 or call.state or
        call.result != .i64) return null;
    for (outputs) |out| if (out.derived != null) return null;
    const ranked = outputs[order.keys[0].column].source;
    if (ranked != .agg or ranked.agg != 0) return null;
    const limit = order.limit orelse return null;
    const k = std.math.cast(usize, order.offset +| limit) orelse return null;
    if (limit == 0 or k == 0 or k > 1024) return null;
    var rows: usize = 0;
    for (work) |item| {
        const n = std.math.cast(usize, metas[item.file].row_groups.items[item.rg].num_rows) orelse return null;
        rows = std.math.add(usize, rows, n) catch return null;
    }
    if (rows == 0 or rows < args.integer_records_min_rows or !owner_groups.admitsRows(.int64, rows)) return null;
    const Owner = owner_groups.IntCountTop;
    const parts = Owner.partitionCount(rows, n_workers, args.decode_batch_rows, args.byte_top_partitions);
    var key_credit: usize = 0;
    for (outputs) |out| if (out.source == .key) switch (domain.axes[out.source.key].values) {
        .bytes => |values| {
            var widest: usize = 0;
            for (values) |value| widest = @max(widest, value.len);
            key_credit +|= widest;
        },
        else => {},
    };
    const names_credit = outputNamesBytes(outputs);
    const out_credit = names_credit +| k *|
        (@sizeOf([]const AggValue) +| outputs.len *| @sizeOf(AggValue) +| key_credit);
    const scratch = n_workers *| (keys.len *| @sizeOf(agg_dense.CountAxis) +| @sizeOf(consumer.PackedCount)) +|
        work.len *| (@sizeOf(consumer.PackedCount.Source) +| @sizeOf(u32));
    const credit = domain.bytes +| scratch +| out_credit;
    const quote = Owner.State.reservation(rows, n_workers, parts, k, credit);
    if (quote > args.max_memory) return null;
    if (explain_only) return .{ .layout = .integer_count_top_h, .reservation = quote };
    const state = (try Owner.State.init(
        gpa,
        args.ledger,
        rows,
        n_workers,
        keys[0].col_ref.col_idx,
        0,
        .{ .k = k, .descending = true },
        parts,
        credit,
    )) orelse return null;
    defer state.deinit();
    const sources = try arena.alloc(consumer.PackedCount.Source, work.len);
    const starts = try arena.alloc(u32, work.len);
    var at: usize = 0;
    for (sources, starts, work) |*source, *start, item| {
        source.* = .{ .file = item.file, .rg = item.rg };
        start.* = @intCast(at);
        at += @intCast(metas[item.file].row_groups.items[item.rg].num_rows);
    }
    var refused: std.atomic.Value(bool) = .init(false);
    const sinks = try arena.alloc(consumer.RecordSink, n_workers);
    const packings = try arena.alloc(consumer.PackedCount, n_workers);
    for (sinks, packings, state.locals) |*sink, *packing, *local| {
        packing.* = .{
            .domain = domain,
            .keys = keys,
            .sources = sources,
            .bindings = try arena.alloc(agg_dense.CountAxis, keys.len),
            .refused = &refused,
        };
        sink.* = .{ .integer_count_top = .{ .local = local, .packing = packing } };
    }
    if (args.taken) |taken| taken.insert(.integer_records);
    const run = try runRecordWorkers(
        gpa,
        arena,
        args,
        metas,
        plan,
        work,
        calls,
        keys,
        sinks,
        starts,
        outputs,
        timings,
    );
    // A late PLAIN/mismatched page leaves only private records. Joined workers have released their source pages;
    // the established narrowing chain disables this attempt and rewinds stable mappings before exact fallback.
    if (refused.load(.monotonic)) return error.ExceededMemoryBudget;
    const prof = profile.threadOf(args.profiler, .main);
    const finish_start = nowMonoNs();
    try state.finishSelected(@intCast(run.rows_matched));
    const scatter_end = finish_start + @as(i64, @intCast(state.partition_ns));
    const fold_end = scatter_end + @as(i64, @intCast(state.fold_ns));
    profile.record(prof, .integer_scatter, finish_start, scatter_end, profile.args(.{}));
    profile.record(prof, .integer_fold, scatter_end, fold_end, profile.args(.{}));
    profile.record(prof, .integer_order, fold_end, nowMonoNs(), profile.args(.{}));
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    const names = try gpa.alloc([]const u8, outputs.len);
    @memset(names, "");
    output.group_cols = names;
    const types = try arena.alloc(GroupColType, outputs.len);
    for (outputs, names, types) |out, *name, *ty| {
        name.* = try gpa.dupe(u8, out.name);
        ty.* = switch (out.source) {
            .key => |ki| .{
                .lane = if (keys[ki].col_ref.expr_type == .str) .string else .i64,
                .nullable = true,
                .source = leafSchemaElem(&metas[0], keys[ki].col_ref.col_idx),
            },
            .agg => .{ .lane = .i64, .nullable = false },
        };
    }
    const kept = state.top();
    const out_rows = try gpa.alloc([]const AggValue, kept.len);
    @memset(out_rows, &.{});
    output.group_rows = out_rows;
    const slab = try gpa.alloc(AggValue, kept.len * outputs.len);
    @memset(slab, .null_val);
    output.slab = slab;
    const indices = try arena.alloc(usize, keys.len);
    var held = names_credit + kept.len * (@sizeOf([]const AggValue) + outputs.len * @sizeOf(AggValue));
    for (kept, out_rows, 0..) |group, *row, ri| {
        var rem: u64 = group.key;
        for (domain.axes, indices) |*axis, *index| {
            index.* = @intCast(rem % axis.ids());
            rem /= axis.ids();
        }
        row.* = slab[ri * outputs.len ..][0..outputs.len];
        for (outputs, slab[ri * outputs.len ..][0..outputs.len]) |out, *cell| switch (out.source) {
            .agg => cell.* = .{ .i = group.countValue() },
            .key => |ki| {
                const axis = &domain.axes[ki];
                const id = indices[ki];
                if (id == axis.len()) continue;
                cell.* = switch (axis.values) {
                    .bytes => |values| b: {
                        const copy = try gpa.dupe(u8, values[id]);
                        held += copy.len;
                        break :b .{ .s = copy };
                    },
                    .int32 => |values| .{ .i = if (keys[ki].col_ref.unsigned_32)
                        @as(u32, @truncate(values[id]))
                    else
                        @as(i64, @bitCast(values[id])) },
                    .int64 => |values| .{ .i = if (keys[ki].col_ref.unsigned_64)
                        @as(i128, values[id])
                    else
                        @as(i64, @bitCast(values[id])) },
                };
            },
        };
    }
    if (args.ledger != null) state.charged -= @min(state.charged, held);
    var bytes_in: u64 = 0;
    for (args.inputs) |input| bytes_in += if (input.logical_size != 0) input.logical_size else input.bytes.len;
    return .{
        .files_in = args.inputs.len,
        .rows_in = run.rows_in,
        .rows_scanned = run.rows_scanned,
        .rows_matched = run.rows_matched,
        .bytes_in = bytes_in,
        .row_groups_in = run.row_groups_in,
        .row_groups_pruned = run.row_groups_pruned,
        .row_groups_full_match = run.row_groups_full_match,
        .cols_stat_pruned = plan.cols_stat_pruned,
        .timings = run.timings,
        .output = output,
        .part_agg = true,
        .state = .{ .accumulators = &.{}, .agg_calls = calls, .group_col_types = types },
    };
}

const IntegerCountBounds = union(enum) {
    pending: *bool,
    refined: ?NdvStat,

    fn guess(bounds: @This(), footer: u64) u64 {
        if (bounds == .refined) if (bounds.refined) |stat| if (stat.union_complete) return stat.hi;
        return footer;
    }
};

/// Whether a raw integer owner should take a count or full answer, from the summed footer dictionaries (`guess`).
/// Summed dictionaries can repeat the same small domain in every RG. A reduction hint defers the decision until the
/// union is known; only a complete union replaces the summed footer estimate. An unfiltered count cut always asks:
/// many small row groups each holding most of a small domain sum to more than a quarter of the rows, and the owner
/// would then displace the dense lanes the union admits.
const IntegerGate = enum { owner, coded, ask_union };

fn integerCountGate(
    guess: u64,
    rows: usize,
    unfiltered_top: bool,
    union_allowed: bool,
    bounds: IntegerCountBounds,
) IntegerGate {
    const refine = union_allowed and (guess < rows / 4 or unfiltered_top);
    if (unfiltered_top and bounds == .pending and refine and guess > agg_dense.max_ids) return .ask_union;
    const prefer_coded = if (unfiltered_top)
        (if (refine) bounds.guess(guess) else guess) <= agg_dense.max_ids
    else
        guess < rows / 4;
    return if (prefer_coded) .coded else .owner;
}

test "regression: an unfiltered integer count cut over a repeated small domain asks the union before an owner" {
    // rg64k_100k: 458 row groups of 64K rows each hold most of 100K keys. Their dictionaries sum past a quarter of
    // the rows and past the dense limit, so the owner took the cut from the dense lanes (6d46d1e2, 1.5x slower).
    const rows: usize = 30_000_000;
    const summed: u64 = 22_000_000;
    var asked = false;
    try testing.expectEqual(.ask_union, integerCountGate(summed, rows, true, true, .{ .pending = &asked }));
    const small: NdvStat = .{ .rows = rows, .hi = 100_000, .union_complete = true };
    try testing.expectEqual(.coded, integerCountGate(summed, rows, true, true, .{ .refined = small }));
    // A union as wide as the footer says keeps the owner; so does a union not complete.
    const wide: NdvStat = .{ .rows = rows, .hi = 10_000_000, .union_complete = true };
    try testing.expectEqual(.owner, integerCountGate(summed, rows, true, true, .{ .refined = wide }));
    const partial: NdvStat = .{ .rows = rows, .hi = 100_000, .union_complete = false };
    try testing.expectEqual(.owner, integerCountGate(summed, rows, true, true, .{ .refined = partial }));
    // Filtered, the footer's reduction hint alone decides, as before.
    try testing.expectEqual(.owner, integerCountGate(summed, rows, false, true, .{ .refined = small }));
    try testing.expectEqual(.coded, integerCountGate(1000, rows, false, true, .{ .refined = null }));
}

fn inlineIntegerAnswer(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: *MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys_opt: ?[]const expr_ast.Expr,
    outputs_opt: ?[]const BoundOutputColumn,
    requested_workers: usize,
    timings: Timings,
    bounds: IntegerCountBounds,
    comptime explain_only: bool,
) !if (explain_only) ?RecordAdmission else ?MultiAggResult {
    const n_workers = @min(requested_workers, owner_groups.max_workers);
    const order = args.result_order;
    if (!args.integer_records or !allRescannable(args.inputs) or
        order.having != null or
        order.hidden.len != 0) return null;
    const keys = keys_opt orelse return null;
    const outputs = outputs_opt orelse return null;
    for (outputs) |out| if (out.derived != null) return null;
    const full = order.keys.len == 0 and order.limit == null and order.offset == 0;
    var cut: ?owner_groups.Cut = null;
    if (full) {
        if (!(args.typed_answer or args.record_answer) or calls.len != 2) return null;
    } else {
        const limit = order.limit orelse return null;
        if (limit == 0 or calls.len != 1 or order.keys.len != 1) return null;
        const k = std.math.cast(usize, order.offset +| limit) orelse return null;
        if (k == 0 or k > 1024) return null;
        const source = outputs[order.keys[0].column].source;
        if (source != .agg or source.agg != 0) return null;
        cut = .{ .k = k, .descending = order.keys[0].descending };
    }
    if (keys.len != 1 or keys[0] != .col_ref or outputs.len != calls.len + 1) return null;
    const key = keys[0].col_ref;
    if (key.physical_type != .INT64 or key.expr_type != .i64 or key.unsigned_64) return null;
    var count: ?usize = null;
    var value: ?usize = null;
    var distinct = false;
    for (calls, 0..) |call, i| {
        if (call.where != null or call.offset != 0 or call.state or call.result != .i64) return null;
        switch (call.func) {
            .count => {
                if (call.arg != null or count != null) return null;
                count = i;
            },
            .sum, .count_distinct => {
                if (call.func == .count_distinct) {
                    if (full) return null;
                    // Grouped DISTINCT keeps its established optional output schema, unlike bare COUNT.
                    distinct = true;
                }
                const arg = call.arg orelse return null;
                if (arg != .col_ref or arg.col_ref.physical_type != .INT64 or arg.col_ref.expr_type != .i64 or
                    arg.col_ref.unsigned_64 or value != null) return null;
                value = arg.col_ref.col_idx;
            },
            else => return null,
        }
    }
    const count_top = !full and count != null and !distinct;
    if ((full and count == null) or (!count_top and value == null)) return null;
    if (args.filter != null and !count_top) return null;
    const ordered_count = count_top and orderedIntegerHint(metas, work, key.col_idx);
    // Raw integer identities need no retained dictionary union. The cost gates below leave small domains on
    // their coded folds, while wide count cuts avoid a sketch and its certification rescan.
    // Leave compressed/skew keys on the established distinct certifier. This is a cost hint over all work,
    // never a bound on identity or a reason to skip a decoded value.
    if (distinct and (args.distinct_pairs == .on or
        (args.integer_records_min_rows != 0 and !wideKey(metas, work, key.col_idx)))) return null;
    var owner_args = args.*;
    if (distinct and owner_args.decode_batch_rows == 0)
        owner_args.decode_batch_rows = owner_groups.batchRows(args.byte_top_batch_rows);
    var seen: u8 = 0;
    for (outputs) |out| seen |= @as(u8, 1) << @intCast(switch (out.source) {
        .key => @as(usize, 0),
        .agg => |ai| ai + 1,
    });
    if (seen != (if (full) @as(u8, 7) else @as(u8, 3))) return null;
    const starts = try arena.alloc(u32, work.len);
    var rows: usize = 0;
    var key_range: IntegerRangeHint = .{};
    for (work, starts) |item, *start| {
        if (!owner_groups.admitsRows(.int64, rows)) return null;
        start.* = @intCast(rows);
        const meta = &metas[item.file];
        const rg = &meta.row_groups.items[item.rg];
        const n = rg.num_rows;
        if (n < 0) return null;
        rows +|= @intCast(n);
        if (distinct and args.integer_records_min_rows != 0) key_range.include(rg, meta, key.col_idx);
    }
    if (distinct and args.integer_records_min_rows != 0 and key_range.small(rows)) return null;
    if (rows < args.integer_records_min_rows or !owner_groups.admitsRows(.int64, rows)) return null;
    const quote = integerQuote(rows, n_workers, cut, owner_args, count_top, ordered_count, work.len, outputNamesBytes(outputs));
    if (quote > args.max_memory) return null;
    // A small stored-dictionary estimate favors the established coded fold. Compression can make this estimate low:
    // it is only a cost decision, never a proof about key identity, bounds, or which rows must be evaluated.
    if (args.integer_records_min_rows != 0) {
        if (ndv.footerEntries(metas, keys)) |guess| {
            const unfiltered_top = count_top and !ordered_count and args.filter == null;
            switch (integerCountGate(guess, rows, unfiltered_top, args.ndv_policy and args.ndv_union, bounds)) {
                .owner => {},
                .coded => return null,
                .ask_union => {
                    bounds.pending.* = true;
                    return null;
                },
            }
        } else if (count_top and !ordered_count) {
            var survivors: f64 = 0;
            var range: IntegerRangeHint = .{};
            for (work) |item| {
                const meta = &metas[item.file];
                const rg = &meta.row_groups.items[item.rg];
                const decision = plan.decide(rg, meta);
                if (decision == .skip) continue;
                const share = if (decision == .full_match or plan.query.filter == null)
                    1
                else
                    filter_prune.passFraction(plan.query.filter.?, rg, meta);
                survivors += @as(f64, @floatFromInt(@max(0, rg.num_rows))) * share;
                range.include(rg, meta, key.col_idx);
            }
            // An estimated survivor count also caps its domain for costing. Never bounds or skips decoded identities.
            const kept: usize = @intFromFloat(survivors);
            if (kept < args.integer_records_min_rows or range.small(kept)) return null;
        }
    }
    if (explain_only) return .{
        .layout = if (distinct) .integer_distinct_top_h else if (count_top)
            .integer_count_top_h
        else if (cut != null) .integer_sum_top_h else .integer_group_stream,
        .reservation = quote,
    };
    if (cut) |c| {
        if (distinct) return runIntegerOwner(
            .sum_top,
            gpa,
            arena,
            &owner_args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            n_workers,
            timings,
            rows,
            key.col_idx,
            value.?,
            count,
            starts,
            c,
            false,
        );
        if (count_top) return runIntegerOwner(
            .count_top,
            gpa,
            arena,
            args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            n_workers,
            timings,
            rows,
            key.col_idx,
            0,
            count,
            starts,
            c,
            ordered_count,
        );
        if (orderedIntegerHint(metas, work, key.col_idx)) if (try runIntegerOwner(
            .sum_top,
            gpa,
            arena,
            args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            n_workers,
            timings,
            rows,
            key.col_idx,
            value.?,
            count,
            starts,
            c,
            true,
        )) |answer| return answer;
        return try runIntegerOwner(
            .sum_top,
            gpa,
            arena,
            args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            n_workers,
            timings,
            rows,
            key.col_idx,
            value.?,
            count,
            starts,
            c,
            false,
        );
    }
    if (orderedIntegerHint(metas, work, key.col_idx)) if (try runIntegerOwner(
        .full,
        gpa,
        arena,
        args,
        metas,
        plan,
        work,
        calls,
        keys,
        outputs,
        n_workers,
        timings,
        rows,
        key.col_idx,
        value.?,
        count,
        starts,
        {},
        true,
    )) |answer| return answer;
    return try runIntegerOwner(
        .full,
        gpa,
        arena,
        args,
        metas,
        plan,
        work,
        calls,
        keys,
        outputs,
        n_workers,
        timings,
        rows,
        key.col_idx,
        value.?,
        count,
        starts,
        {},
        false,
    );
}

/// Footer bounds select an attempt; every decoded key and every source seam must still prove the order.
fn orderedIntegerHint(metas: []const schema.FileMetaData, work: []const WorkItem, column: usize) bool {
    const statistics = @import("parquet/statistics.zig");
    var previous: ?i64 = null;
    for (work) |item| {
        const meta = &metas[item.file];
        const rg = &meta.row_groups.items[item.rg];
        if (rg.num_rows == 0) continue;
        const stats = statistics.chunkStats(rg, column, meta, .corroborated);
        // Bounds exclude NULLs. A run cannot represent them; unknown nullability cannot admit a run either.
        if ((stats.null_count orelse -1) != 0) return false;
        const b = stats.bounds orelse return false;
        if (b.min.len != 8 or b.max.len != 8) return false;
        const lo = std.mem.readInt(i64, b.min[0..8], .little);
        const hi = std.mem.readInt(i64, b.max[0..8], .little);
        if (previous) |p| if (lo < p) return false;
        previous = hi;
    }
    return previous != null;
}

/// The reservation of an admitted integer record layout: the full answer's established quote, or a top-H attempt's.
fn integerQuote(
    rows: usize,
    n_workers: usize,
    cut: ?owner_groups.Cut,
    args: MultiAggArgs,
    count_top: bool,
    ordered: bool,
    items: usize,
    names_credit: usize,
) usize {
    const c = cut orelse return owner_groups.IntFull.State.reservation(
        rows,
        n_workers,
        owner_groups.full_parts,
        0,
        names_credit,
    );
    switch (if (count_top) owner_groups.Kind.count_top else owner_groups.Kind.sum_top) {
        inline else => |kind| {
            const Owner = owner_groups.Owner(kind, .int64);
            const parts = Owner.partitionCount(rows, n_workers, args.decode_batch_rows, args.byte_top_partitions);
            return if (ordered and kind == .count_top and args.sorted_count_stream)
                Owner.State.streamReservation(n_workers, items, c.k, names_credit)
            else if (ordered)
                Owner.State.runReservation(rows, n_workers, parts, c.k, names_credit)
            else
                Owner.State.reservation(rows, n_workers, parts, c.k, names_credit);
        },
    }
}

fn runIntegerOwner(
    comptime kind: owner_groups.Kind,
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: *MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys: []const expr_ast.Expr,
    outputs: []const BoundOutputColumn,
    n_workers: usize,
    timings: Timings,
    rows: usize,
    key_col: usize,
    value_col: usize,
    count: ?usize,
    starts: []u32,
    cut: if (kind == .full) void else owner_groups.Cut,
    ordered: bool,
) !?MultiAggResult {
    const Owner = owner_groups.Owner(kind, .int64);
    const parts = if (kind == .full)
        owner_groups.full_parts
    else
        Owner.partitionCount(rows, n_workers, args.decode_batch_rows, args.byte_top_partitions);
    const distinct = kind == .sum_top and calls.len == 1 and calls[0].func == .count_distinct;
    const names_credit = outputNamesBytes(outputs);
    const state = (if (kind == .sum_top and distinct)
        try Owner.State.initDistinctTop(
            gpa,
            args.ledger,
            rows,
            n_workers,
            key_col,
            value_col,
            cut,
            parts,
            names_credit,
        )
    else if (ordered and kind == .count_top and args.sorted_count_stream)
        try Owner.State.initStreamRuns(gpa, args.ledger, rows, n_workers, key_col, cut, parts, work.len, names_credit)
    else if (ordered)
        try Owner.State.initRuns(
            gpa,
            args.ledger,
            rows,
            n_workers,
            key_col,
            value_col,
            cut,
            parts,
            work.len,
            names_credit,
        )
    else
        try Owner.State.init(
            gpa,
            args.ledger,
            rows,
            n_workers,
            key_col,
            value_col,
            cut,
            parts,
            names_credit,
        )) orelse return null;
    if (kind == .full) state.wide_sums = args.record_answer and !args.typed_answer;
    var state_live = true;
    errdefer if (state_live) state.deinit();
    if (args.taken) |taken| taken.insert(.integer_records);
    const sinks = try arena.alloc(consumer.RecordSink, n_workers);
    for (sinks, state.locals) |*sink, *local| sink.* = switch (kind) {
        .full => .{ .integer = local },
        .sum_top => .{ .integer_top = local },
        .count_top => .{ .integer_count_top = .{ .local = local } },
    };
    const run = try runRecordWorkers(
        gpa,
        arena,
        args.*,
        metas,
        plan,
        work,
        calls,
        keys,
        sinks,
        starts,
        outputs,
        timings,
    );
    const prof = profile.threadOf(args.profiler, .main);
    const final_start = nowMonoNs();
    state.finishSelected(@intCast(run.rows_matched)) catch |err| {
        if (err != error.RunOrderDeclined) return err;
        try rewindInputs(arena, args);
        state.deinit();
        state_live = false;
        if (kind == .count_top) return runIntegerOwner(
            kind,
            gpa,
            arena,
            args,
            metas,
            plan,
            work,
            calls,
            keys,
            outputs,
            n_workers,
            timings,
            rows,
            key_col,
            value_col,
            count,
            starts,
            cut,
            false,
        );
        if (args.taken) |taken| taken.remove(.integer_records);
        return null;
    };
    const scatter_end = final_start + @as(i64, @intCast(state.partition_ns));
    const fold_end = scatter_end + @as(i64, @intCast(state.fold_ns));
    profile.record(prof, .integer_scatter, final_start, scatter_end, profile.args(.{}));
    profile.record(prof, .integer_fold, scatter_end, fold_end, profile.args(.{}));
    profile.record(prof, .integer_order, fold_end, nowMonoNs(), profile.args(.{}));
    var output: AggOutput = .{};
    errdefer output.deinit(gpa);
    const names = try gpa.alloc([]const u8, outputs.len);
    @memset(names, "");
    output.group_cols = names;
    const types = try arena.alloc(GroupColType, outputs.len);
    for (outputs, types, names) |out, *ty, *name| {
        name.* = try gpa.dupe(u8, out.name);
        ty.* = .{ .lane = .i64, .nullable = switch (out.source) {
            .key => true,
            .agg => |ai| count == null or ai != count.?,
        }, .source = if (out.source == .key) leafSchemaElem(&metas[0], key_col) else null };
    }
    if (kind != .full) {
        const kept = state.top();
        try buildIntegerTopRows(kind, gpa, &output, kept, outputs);
        // As with the general GROUP BY answer, keep its row storage drawn until the query ledger dies. Transfer
        // that tiny part of the reservation before releasing the records; no owning state remains in the answer.
        if (args.ledger != null) state.charged -= @min(state.charged, names_credit + kept.len *
            (@sizeOf([]const AggValue) + outputs.len * @sizeOf(AggValue)));
        state.deinit();
    } else output.integer_stream = .{ .state = state, .outputs = outputs, .count_call = count.? };
    var bytes_in: u64 = 0;
    for (args.inputs) |in| bytes_in += if (in.logical_size != 0) in.logical_size else in.bytes.len;
    return .{
        .files_in = args.inputs.len,
        .rows_in = run.rows_in,
        .rows_scanned = run.rows_scanned,
        .rows_matched = run.rows_matched,
        .bytes_in = bytes_in,
        .row_groups_in = run.row_groups_in,
        .row_groups_pruned = run.row_groups_pruned,
        .row_groups_full_match = run.row_groups_full_match,
        .cols_stat_pruned = plan.cols_stat_pruned,
        .timings = run.timings,
        .output = output,
        .part_agg = true,
        .state = .{ .accumulators = &.{}, .agg_calls = calls, .group_col_types = types },
    };
}

const RecordRun = struct {
    timings: Timings,
    rows_in: i64 = 0,
    rows_scanned: i64 = 0,
    rows_matched: i64 = 0,
    row_groups_in: usize = 0,
    row_groups_pruned: usize = 0,
    row_groups_full_match: usize = 0,
};

fn runRecordWorkers(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    args: MultiAggArgs,
    metas: []const schema.FileMetaData,
    plan: *const agg_plan.Plan,
    work: []const WorkItem,
    calls: []const expr_agg.AggCall,
    keys: []const expr_ast.Expr,
    sinks: []const consumer.RecordSink,
    starts: []const u32,
    outputs: []const BoundOutputColumn,
    timings: Timings,
) !RecordRun {
    const n = sinks.len;
    const workers = try arena.alloc(Worker, n);
    @memset(workers, undefined);
    const tables = try arena.alloc(expr_agg.GroupTable, n);
    for (tables) |*table| table.* = .init(gpa, 0);
    defer for (tables) |*table| table.deinit();
    var decode_budget: ?consumer.DecodeBudget = if (args.decode_limit) |l| .{ .limit = l, .workers = n } else null;
    var cursor = std.atomic.Value(usize).init(0);
    // An indirect handle keeps the ordinary worker/target layout unchanged; only record paths dispatch the tag.
    for (workers, 0..) |*w, i| w.* = .{
        .gpa = gpa,
        .inputs = args.inputs,
        .metas = metas,
        .work = work,
        .cursor = &cursor,
        .agg_calls = calls,
        .plan = plan,
        .decode_options = .{
            .fast_levels = args.fast_levels,
            .level_runs = args.level_runs,
            .encoded = args.encoded,
            .expand_limit = args.max_memory,
        },
        .expr_batch_rows = args.expr_batch_rows,
        .decode_batch_rows = args.decode_batch_rows,
        .auto_decode_batches = args.auto_decode_batches,
        .scan_workers = workers.len,
        .error_outputs = outputs,
        .failure_probe = args.failure_probe,
        .group_by_keys = keys,
        .group_tables = tables,
        .index = i,
        .records = &sinks[i],
        .record_starts = starts,
        .ledger = args.ledger,
        .decode_budget = if (decode_budget) |*b| b else null,
        .profiler = args.profiler,
    };
    defer releaseRegions(workers);
    if (args.start_reads) |s| {
        try s.start(s.ctx);
        if (s.planned) |planned| planned(s.ctx);
    }
    const t0 = nowMonoNs();
    runWorkers(workers);
    releaseRegionsParallel(workers);
    if (firstWorkerFailure(workers, args.failure_probe)) |failure| {
        const e = failure.err;
        // Only an effectively parallel attempt can benefit from the deterministic serial retry.
        if (e == error.ExceededMemoryBudget and n > 1) if (args.taken) |taken| taken.insert(.decode_memory);
        consumer.setDecodeFailure(failure.site);
        if (e == error.RetainedEncodingUnsupported) return error.ExceededMemoryBudget;
        return e;
    }
    var run: RecordRun = .{ .timings = timings };
    run.timings.decode_wall_ns = @intCast(nowMonoNs() - t0);
    for (workers) |w| {
        run.rows_in += w.rows_in;
        run.rows_scanned += w.rows_scanned;
        run.rows_matched += w.rows_matched;
        run.row_groups_in += w.rgs_in;
        run.row_groups_pruned += w.rgs_pruned;
        run.row_groups_full_match += w.rgs_full_match;
        run.timings.core.decode_ns += w.timings.decode_ns;
        run.timings.core.eval_ns += w.timings.eval_ns;
        run.timings.core.encode_ns += w.timings.encode_ns;
    }
    return run;
}

fn buildIntegerTopRows(
    comptime kind: owner_groups.Kind,
    gpa: std.mem.Allocator,
    output: *AggOutput,
    groups: []const owner_groups.IntSumTop.Group,
    outputs: []const BoundOutputColumn,
) !void {
    const rows = try gpa.alloc([]const AggValue, groups.len);
    @memset(rows, &.{});
    output.group_rows = rows;
    const slab = try gpa.alloc(AggValue, groups.len * outputs.len);
    @memset(slab, .null_val);
    output.slab = slab;
    for (groups, rows, 0..) |g, *row, i| {
        const cells = slab[i * outputs.len ..][0..outputs.len];
        row.* = cells;
        for (outputs, cells) |out, *cell| {
            const v: ?i128 = switch (out.source) {
                .key => if (g.keyValue()) |x| @as(i128, x) else null,
                .agg => owner_groups.Owner(kind, .int64).rank(g),
            };
            cell.* = if (v) |x| .{ .i = x } else .null_val;
        }
    }
}

/// min/max of a bare column returns one of that column's values, so its output can carry the column's type.
/// An aggregate argument or GROUP BY key that reads a repeated leaf (in a LIST or MAP) is refused while planning, as a
/// filter on one is: it is an unsupported query (exit 2), not a decode failure found after reading the column.
fn refuseRepeated(
    arena: std.mem.Allocator,
    meta: *const schema.FileMetaData,
    calls: []const expr_agg.AggCall,
    keys: ?[]const expr_ast.Expr,
    diag: ?*Diag,
) !void {
    for ([_]bool{ false, true }) |in_keys| {
        const reads = try arena.alloc(bool, meta.schema.items.len);
        @memset(reads, false);
        if (in_keys) {
            for (keys orelse &.{}) |k| k.collectColumns(reads);
        } else for (calls) |c| if (c.arg) |a| a.collectColumns(reads);
        var leaves: schema.LeafIterator = .init(meta.schema.items);
        while (leaves.next()) |leaf| if (leaf.max_rep > 0 and leaf.index < reads.len and reads[leaf.index]) {
            Diag.setColumn(diag, try std.mem.join(arena, ".", leaf.path));
            return if (in_keys) error.NestedGroupKeyNotSupported else error.NestedAggregateNotSupported;
        };
    }
}

fn passThroughSource(call: expr_agg.AggCall, meta: *const schema.FileMetaData) ?schema.SchemaElement {
    if (call.func != .min and call.func != .max) return null;
    const arg = call.arg orelse return null;
    if (arg != .col_ref) return if (arg.isBoolean()) boolean_answer else null;
    if (call.as_date) return date_answer;
    return leafSchemaElem(meta, arg.col_ref.col_idx);
}

/// The type `min`/`max` of `make_date(col)` answers as (`AggCall.as_date`), whatever integer type `col` has.
const date_answer: schema.SchemaElement = .{
    .type = .INT32,
    .type_length = null,
    .repetition_type = .OPTIONAL,
    .name = "",
    .num_children = null,
    .scale = null,
    .precision = null,
    .field_id = null,
    .converted_type = .DATE,
    .logical_type = .{ .DATE = .{} },
};

/// The type a computed BOOLEAN answer column (a key, min or max of a BOOLEAN expression) passes through as, as a bare
/// BOOLEAN column's does: printed true/false and written BOOLEAN, though its lane holds 0/1.
const boolean_answer: schema.SchemaElement = .{
    .type = .BOOLEAN,
    .type_length = null,
    .repetition_type = .OPTIONAL,
    .name = "",
    .num_children = null,
    .scale = null,
    .precision = null,
    .field_id = null,
};

const MergeGroupRef = struct {
    table: u32,
    group: u32,
};

fn mergeCandidates(
    gpa: std.mem.Allocator,
    lists: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    keys: []const []const u8,
    calls: []const expr_agg.AggCall,
    n_workers: usize,
    slots: *std.ArrayList(MergedSlot),
    accs: *std.ArrayList(expr_agg.Accumulator),
) !void {
    _ = n_workers;
    try slots.ensureTotalCapacity(lists, keys.len);
    try accs.ensureTotalCapacity(lists, keys.len * calls.len);

    for (keys) |key| {
        var first: u64 = std.math.maxInt(u64);
        var key_borrowed: []const u8 = key;
        var found_any = false;

        for (tables) |gt| {
            if (gt.findKey(key)) |gi| {
                found_any = true;
                if (gt.first.items[gi] < first) {
                    first = gt.first.items[gi];
                    key_borrowed = gt.keyAt(gi);
                }
            }
        }
        if (!found_any) continue;

        const slot_idx = accs.items.len;
        for (calls, 0..) |call, ci| {
            // Appended before merging, so state moved out of a source is owned by `accs` even if a later merge fails.
            accs.appendAssumeCapacity(expr_agg.Accumulator.init(call));
            const dst = &accs.items[accs.items.len - 1];
            for (tables) |gt| {
                if (gt.findKey(key)) |gi| {
                    var local = gt.readAcc(gi, ci, calls.len);
                    const src = if (gt.compact.stride != 0)
                        &local
                    else
                        &gt.accumulators.items[@as(usize, gi) * calls.len + ci];
                    try mergeOwnedAccumulator(dst, src, gpa);
                }
            }
        }

        slots.appendAssumeCapacity(.{
            .key = key_borrowed,
            .first = first,
            .idx = slot_idx,
        });
    }
}

/// Fold `refs` into distinct groups. `slots` borrows keys from `tables`; `accs` owns any string winners moved out of
/// those tables. The map is sized for every ref, so a repeated key does not rehash it. `hashes`, when set, is the
/// Wyhash already computed for each ref (the same one `StringHashMap` uses) and is not computed again.
/// `in_place` (`mergesInPlace`): `accs` stays empty and each group's state is merged into its first ref's own
/// accumulators instead, which `slot.idx` names (`packRef`).
fn hashMergeGroupRefs(
    gpa: std.mem.Allocator,
    lists: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    refs: []const MergeGroupRef,
    hashes: ?[]const u64,
    calls: []const expr_agg.AggCall,
    cut: ?ResultCut,
    in_place: bool,
    slots: *std.ArrayList(MergedSlot),
    accs: *std.ArrayList(expr_agg.Accumulator),
) !void {
    if (in_place) return mergeInPlace(gpa, lists, tables, refs, hashes, calls, slots);
    if (cut) |c| {
        if (c.ranking_first) return mergeResultCut(gpa, lists, tables, refs, hashes, calls, c, slots, accs);
        if (calls[c.a_idx].func == .count) {
            const count_cut: CountCut = .{ .a_idx = c.a_idx, .k = c.k };
            return mergeCountCut(gpa, lists, tables, refs, hashes, calls, count_cut, slots, accs);
        }
    }
    var index = try MergeIndex.init(lists, tables, refs.len, .within_map);
    defer index.deinit();
    try slots.ensureTotalCapacity(lists, refs.len);

    for (refs, 0..) |ref, ri| {
        const gt = &tables[ref.table];
        const key = gt.keyAt(ref.group);
        const gop = index.getOrPut(key, if (hashes) |hs| hs[ri] else std.hash.Wyhash.hash(0, key));
        var src_scratch: [16]expr_agg.Accumulator = undefined;
        const src = gt.readGroup(@as(usize, ref.group), calls.len, &src_scratch);
        if (gop.found) {
            const slot = &slots.items[gop.value.*];
            slot.first = @min(slot.first, gt.first.items[ref.group]);
            const dst = accs.items[slot.idx..][0..calls.len];
            for (dst, src) |*d, *s| try mergeOwnedAccumulator(d, s, gpa);
        } else {
            gop.value.* = @intCast(slots.items.len);
            const acc_at = accs.items.len;
            try accs.ensureUnusedCapacity(lists, calls.len);
            for (calls) |call| accs.appendAssumeCapacity(expr_agg.Accumulator.init(call));
            const dst = accs.items[acc_at..][0..calls.len];
            for (dst, src) |*d, *s| try mergeOwnedAccumulator(d, s, gpa);
            slots.appendAssumeCapacity(.{
                .key = key,
                .first = gt.first.items[ref.group],
                .idx = acc_at,
            });
        }
    }
    // A partition holds every copy of its keys, so its counts are final and a count cut applies here.
    if (cut) |c| try keepCountTop(gpa, lists, calls, .{ .a_idx = c.a_idx, .k = c.k }, slots, accs);
}

/// Whether a full merge may leave each group's state in the source table that first holds it (`mergeInPlace`): no
/// cut, which keeps and reorders merged state, and no count(DISTINCT), whose sets a read-only copy cannot merge.
fn mergesInPlace(calls: []const expr_agg.AggCall, cut: ?ResultCut) bool {
    if (cut != null) return false;
    for (calls) |call| if (call.func == .count_distinct) return false;
    return true;
}

/// `calls` with call `i`, a count(DISTINCT) whose every state `foldDistinctPairs` made a count, merged as the COUNT
/// it now is: a fresh count(DISTINCT) state takes a count as it is, so the merge's every value is the same.
fn countedCalls(arena: std.mem.Allocator, calls: []const expr_agg.AggCall, i: usize) ![]const expr_agg.AggCall {
    std.debug.assert(calls[i].func == .count_distinct);
    const out = try arena.dupe(expr_agg.AggCall, calls);
    out[i].func = .count;
    return out;
}

/// A merged-in-place slot's `idx`: its source table above its group.
fn packRef(ref: MergeGroupRef) usize {
    return @as(usize, ref.table) << 32 | ref.group;
}

fn inPlaceAccs(
    tables: []const expr_agg.GroupTable,
    idx: usize,
    n_calls: usize,
    scratch: *[16]expr_agg.Accumulator,
) []expr_agg.Accumulator {
    const g: usize = @as(u32, @truncate(idx));
    return tables[idx >> 32].readGroup(g, n_calls, scratch);
}

/// `hashMergeGroupRefs` with no copy of a group's state: a key's first ref keeps it, and each later ref of the key is
/// merged into it there. Before each such merge the kept state is first made `foldedAcc` of itself, so the sequence of
/// merges, and every bit of the result, is the copying merge's; rows read a group seen once through `foldedAcc`. A key
/// is in one partition only, so no two threads write the same state.
fn mergeInPlace(
    gpa: std.mem.Allocator,
    lists: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    refs: []const MergeGroupRef,
    hashes: ?[]const u64,
    calls: []const expr_agg.AggCall,
    slots: *std.ArrayList(MergedSlot),
) !void {
    var index = try MergeIndex.init(lists, tables, refs.len, .any);
    defer index.deinit();
    try slots.ensureTotalCapacity(lists, slots.items.len + refs.len);
    for (refs, 0..) |ref, ri| {
        const gt = &tables[ref.table];
        const key = gt.keyAt(ref.group);
        const gop = index.getOrPut(key, if (hashes) |hs| hs[ri] else std.hash.Wyhash.hash(0, key));
        const first = gt.first.items[ref.group];
        if (!gop.found) {
            gop.value.* = @intCast(slots.items.len);
            slots.appendAssumeCapacity(.{ .key = key, .first = first, .idx = packRef(ref) });
            continue;
        }
        const slot = &slots.items[gop.value.*];
        slot.first = @min(slot.first, first);
        var dst_scratch: [16]expr_agg.Accumulator = undefined;
        const dst = inPlaceAccs(tables, slot.idx, calls.len, &dst_scratch);
        var src_scratch: [16]expr_agg.Accumulator = undefined;
        const src = gt.readGroup(@as(usize, ref.group), calls.len, &src_scratch);
        for (dst, src, calls) |*d, *s, call| {
            d.* = try foldedAcc(gpa, call, d.*);
            try mergeOwnedAccumulator(d, s, gpa);
        }
        tables[slot.idx >> 32].writeGroup(@as(u32, @truncate(slot.idx)), dst);
    }
}

/// `hashMergeGroupRefs` under a cut by a COUNT: the counts are summed first, alone, to pick the `cut.k` groups the cut
/// keeps (largest count, earlier first appearance on a tie); only those groups' accumulators are then merged. A key
/// seen once (the common case on a near-unique key) costs a count and a position, not a merged copy of its state.
fn mergeCountCut(
    gpa: std.mem.Allocator,
    lists: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    refs: []const MergeGroupRef,
    hashes: ?[]const u64,
    calls: []const expr_agg.AggCall,
    cut: CountCut,
    slots: *std.ArrayList(MergedSlot),
    accs: *std.ArrayList(expr_agg.Accumulator),
) !void {
    var index = try MergeIndex.init(lists, tables, refs.len, .within_map);
    defer index.deinit();
    const Group = struct { count: u64, first: u64, key: []const u8 };
    var groups: std.ArrayList(Group) = .empty;
    defer groups.deinit(lists);
    try groups.ensureTotalCapacity(lists, refs.len);
    const group_of = try lists.alloc(u32, refs.len);
    defer lists.free(group_of);
    for (refs, group_of, 0..) |ref, *gi, ri| {
        const gt = &tables[ref.table];
        const key = gt.keyAt(ref.group);
        const gop = index.getOrPut(key, if (hashes) |hs| hs[ri] else std.hash.Wyhash.hash(0, key));
        const count = gt.readAcc(@as(usize, ref.group), cut.a_idx, calls.len).count;
        const first = gt.first.items[ref.group];
        if (gop.found) {
            const g = &groups.items[gop.value.*];
            g.count +|= count;
            g.first = @min(g.first, first);
        } else {
            gop.value.* = @intCast(groups.items.len);
            groups.appendAssumeCapacity(.{ .count = count, .first = first, .key = key });
        }
        gi.* = gop.value.*;
    }

    const Item = struct { c: u64, first: u64, g: u32 };
    const worse = struct {
        fn cmp(_: void, a: Item, b: Item) std.math.Order {
            if (a.c != b.c) return std.math.order(a.c, b.c);
            return std.math.order(b.first, a.first);
        }
    }.cmp;
    var heap: std.PriorityQueue(Item, void, worse) = .empty;
    defer heap.deinit(lists);
    const k = @min(cut.k, groups.items.len);
    try heap.ensureTotalCapacity(lists, k);
    if (k > 0) for (groups.items, 0..) |g, gi| {
        const item: Item = .{ .c = g.count, .first = g.first, .g = @intCast(gi) };
        if (heap.count() == k) {
            const w = heap.peek().?;
            if (!(item.c > w.c or (item.c == w.c and item.first < w.first))) continue;
            _ = heap.pop();
        }
        heap.push(lists, item) catch unreachable; // within the capacity reserved above
    };

    // The kept groups' state, merged from just their refs.
    const none = std.math.maxInt(u32);
    const out_of = try lists.alloc(u32, groups.items.len);
    defer lists.free(out_of);
    @memset(out_of, none);
    try slots.ensureTotalCapacity(lists, slots.items.len + heap.count());
    try accs.ensureUnusedCapacity(lists, heap.count() * calls.len);
    for (heap.items) |item| {
        const g = groups.items[item.g];
        out_of[item.g] = @intCast(slots.items.len);
        slots.appendAssumeCapacity(.{ .key = g.key, .first = g.first, .idx = accs.items.len });
        for (calls) |call| accs.appendAssumeCapacity(expr_agg.Accumulator.init(call));
    }
    for (refs, group_of) |ref, gi| {
        const out = out_of[gi];
        if (out == none) continue;
        const dst = accs.items[slots.items[out].idx..][0..calls.len];
        var src_scratch: [16]expr_agg.Accumulator = undefined;
        const src = tables[ref.table].readGroup(@as(usize, ref.group), calls.len, &src_scratch);
        for (dst, src) |*d, *sa| try mergeOwnedAccumulator(d, sa, gpa);
    }
}

/// Complete groups are ranked before any owning payload moves; each partition's top-H contains its global winners.
fn mergeResultCut(
    gpa: std.mem.Allocator,
    lists: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    refs: []const MergeGroupRef,
    hashes: ?[]const u64,
    calls: []const expr_agg.AggCall,
    cut: ResultCut,
    slots: *std.ArrayList(MergedSlot),
    accs: *std.ArrayList(expr_agg.Accumulator),
) !void {
    // Charged as the full merge's maps are, through `lists`: see the merge in `prepareAggregate`.
    var scratch: CutScratch = .{ .parent = cut.memory orelse lists, .shared = null };
    mergeResultCutInner(gpa, lists, tables, refs, hashes, calls, cut, &scratch, slots, accs) catch |e|
        return if (scratch.denied.load(.monotonic)) error.ExceededMemoryBudget else e;
}

fn mergeResultCutInner(
    gpa: std.mem.Allocator,
    lists: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    refs: []const MergeGroupRef,
    hashes: ?[]const u64,
    calls: []const expr_agg.AggCall,
    cut: ResultCut,
    scratch: *CutScratch,
    slots: *std.ArrayList(MergedSlot),
    accs: *std.ArrayList(expr_agg.Accumulator),
) !void {
    const sa = scratch.allocator();
    const ma = cut.memory orelse lists;
    var index = try MergeIndex.init(sa, tables, refs.len, .within_map);
    defer index.deinit();
    const Group = struct { rank: expr_agg.Accumulator, first: u64, key: []const u8 };
    var groups: std.ArrayList(Group) = .empty;
    defer groups.deinit(sa);
    try groups.ensureTotalCapacity(sa, refs.len);
    const group_of = try sa.alloc(u32, refs.len);
    defer sa.free(group_of);
    for (refs, group_of, 0..) |ref, *gi, ri| {
        const gt = &tables[ref.table];
        const key = gt.keyAt(ref.group);
        const gop = index.getOrPut(key, if (hashes) |hs| hs[ri] else std.hash.Wyhash.hash(0, key));
        const rank = gt.readAcc(@as(usize, ref.group), cut.a_idx, calls.len);
        const first = gt.first.items[ref.group];
        if (gop.found) {
            const g = &groups.items[gop.value.*];
            try g.rank.merge(rank, sa);
            g.first = @min(g.first, first);
        } else {
            gop.value.* = @intCast(groups.items.len);
            groups.appendAssumeCapacity(.{ .rank = rank, .first = first, .key = key });
        }
        gi.* = gop.value.*;
    }

    var heap = RankHeap.initContext(cut.descending);
    defer heap.deinit(sa);
    const k = @min(cut.k, groups.items.len);
    try heap.ensureTotalCapacity(sa, k);
    for (groups.items, 0..) |g, gi| {
        const value = try rankValue(g.rank, calls[cut.a_idx]);
        pushRank(&heap, sa, k, .{ .value = value, .first = g.first, .g = @intCast(gi) });
    }

    // The kept groups' state, merged from just their refs.
    const none = std.math.maxInt(u32);
    const out_of = try sa.alloc(u32, groups.items.len);
    defer sa.free(out_of);
    @memset(out_of, none);
    try slots.ensureTotalCapacity(ma, slots.items.len + heap.count());
    try accs.ensureUnusedCapacity(ma, heap.count() * calls.len);
    for (heap.items) |item| {
        const g = groups.items[item.g];
        out_of[item.g] = @intCast(slots.items.len);
        slots.appendAssumeCapacity(.{ .key = g.key, .first = g.first, .idx = accs.items.len });
        for (calls, 0..) |call, i|
            accs.appendAssumeCapacity(if (i == cut.a_idx) g.rank else expr_agg.Accumulator.init(call));
    }
    for (refs, group_of) |ref, gi| {
        const out = out_of[gi];
        if (out == none) continue;
        const dst = accs.items[slots.items[out].idx..][0..calls.len];
        var src_scratch: [16]expr_agg.Accumulator = undefined;
        const src = tables[ref.table].readGroup(@as(usize, ref.group), calls.len, &src_scratch);
        for (dst, src, 0..) |*d, *src_acc, i| if (i != cut.a_idx) try mergeOwnedAccumulator(d, src_acc, gpa);
    }
}

/// How many independent partitions the merge is worth. One partition below a few thousand refs, or with one worker:
/// the hash table is then smaller than the cost of splitting it. Otherwise a power of two, so a key's high bits name
/// its partition, and no larger than the worker count.
/// Bytes of merge state a full-merge partition aims for: a core's share of its chiplet's L3.
const merge_part_bytes = 4 << 20;
const merge_parts_max = 4096;

/// `entry_bytes`: what one reference may add to a partition's map, slots and accumulators.
fn mergePartitionCount(n_workers: usize, n_refs: usize, cut: bool, entry_bytes: usize) usize {
    if (n_workers < 2 or n_refs < 16) return 1;
    var p: usize = 1;
    while (p * 2 <= n_workers and p < 32) p *= 2;
    // Under a count cut each partition shrinks to its top groups as it finishes, so many small partitions keep only a
    // few in flight at once instead of half the groups. Even with small n_refs (e.g. after top-k candidate pruning),
    // each remaining group may hold large distinct sets that benefit from parallel workers.
    if (cut) {
        const cut_parts = std.math.ceilPowerOfTwoAssert(usize, n_refs / 65536 + 1);
        return @min(512, @max(p, cut_parts));
    }
    if (n_refs < 8192) return 1;
    // A full merge of near-unique keys holds about a group a reference: one partition a worker leaves each map far
    // larger than cache, and lookups miss. Sized by bytes instead, a partition's state stays cache-resident.
    const fit = std.math.ceilPowerOfTwoAssert(usize, (n_refs *| entry_bytes) / merge_part_bytes + 1);
    return @min(merge_parts_max, @max(p, fit));
}

/// What one merged reference may cost a partition when it starts a group: its map entry, its slot and its
/// accumulators.
fn mergeEntryBytes(n_calls: usize) usize {
    return @sizeOf([]const u8) + @sizeOf(u32) + 1 + @sizeOf(MergedSlot) + n_calls * @sizeOf(expr_agg.Accumulator);
}

/// Preparation and reclamation are part of the finish too: neither may walk millions of groups on the caller.
/// Stable contiguous ranges retain table/input order before the radix scatter, including canonical float partials.
fn finishGroupRanges(
    tables: []expr_agg.GroupTable,
    refs: ?[]MergeGroupRef,
    slots: ?[]MergedSlot,
    requested: usize,
    cleanup: bool,
) void {
    var total: usize = 0;
    for (tables) |t| total += t.groupCount();
    if (total == 0) return;
    const Task = struct {
        tables: []expr_agg.GroupTable,
        refs: ?[]MergeGroupRef,
        slots: ?[]MergedSlot,
        total: usize,
        chunks: usize,
        cleanup: bool,
        cursor: *std.atomic.Value(usize),
        fn run(t: *@This()) void {
            const width = std.math.divCeil(usize, t.total, t.chunks) catch unreachable;
            while (true) {
                const chunk = t.cursor.fetchAdd(1, .monotonic);
                if (chunk >= t.chunks) return;
                const lo = chunk * width;
                const hi = @min(t.total, lo + width);
                var base: usize = 0;
                for (t.tables, 0..) |*table, ti| {
                    const end = base + table.groupCount();
                    if (lo < end and hi > base) {
                        const first = @max(lo, base) - base;
                        const last = @min(hi, end) - base;
                        if (t.cleanup) {
                            table.deinitRange(first, last);
                        } else for (first..last) |gi| {
                            if (t.refs) |r| r[base + gi] = .{ .table = @intCast(ti), .group = @intCast(gi) };
                            if (t.slots) |s| s[base + gi] = .{
                                .key = table.keyAt(gi),
                                .first = table.first.items[gi],
                                .idx = gi,
                            };
                        }
                    }
                    base = end;
                    if (base >= hi) break;
                }
            }
        }
    };
    var storage: [64]Task = undefined;
    const count = @min(storage.len, @max(1, @min(requested, total / 8192 + 1)));
    const tasks = storage[0..count];
    var cursor = std.atomic.Value(usize).init(0);
    for (tasks) |*t| t.* = .{
        .tables = tables,
        .refs = refs,
        .slots = slots,
        .total = total,
        .chunks = count,
        .cleanup = cleanup,
        .cursor = &cursor,
    };
    if (count == 1 or !spawn_util.runTree(Task, tasks, .{ .stack_size = WORKER_STACK_SIZE }, Task.run)) tasks[0].run();
}

fn freeAccumulatorRanges(gpa: std.mem.Allocator, accs: []expr_agg.Accumulator, workers: usize) void {
    const Task = struct {
        gpa: std.mem.Allocator,
        accs: []expr_agg.Accumulator,
        chunks: usize,
        cursor: *std.atomic.Value(usize),
        fn run(t: *@This()) void {
            const width = std.math.divCeil(usize, t.accs.len, t.chunks) catch unreachable;
            while (true) {
                const chunk = t.cursor.fetchAdd(1, .monotonic);
                if (chunk >= t.chunks) return;
                const lo = @min(t.accs.len, chunk * width);
                freeOwnedAccumulatorStrings(t.gpa, t.accs[lo..@min(t.accs.len, lo + width)]);
            }
        }
    };
    var storage: [64]Task = undefined;
    const count = @min(storage.len, @max(1, @min(workers, accs.len / 8192 + 1)));
    const tasks = storage[0..count];
    var cursor = std.atomic.Value(usize).init(0);
    for (tasks) |*t| t.* = .{ .gpa = gpa, .accs = accs, .chunks = count, .cursor = &cursor };
    if (count == 1 or !spawn_util.runTree(Task, tasks, .{ .stack_size = WORKER_STACK_SIZE }, Task.run)) tasks[0].run();
}

const MergePart = struct {
    refs: []const MergeGroupRef,
    hashes: []const u64,
    slots: std.ArrayList(MergedSlot) = .empty,
    accs: std.ArrayList(expr_agg.Accumulator) = .empty,
    /// Where this partition's slots and accumulators start in the combined lists.
    slot_at: usize = 0,
    acc_at: usize = 0,
};

const MergeTask = struct {
    gpa: std.mem.Allocator,
    lists: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    calls: []const expr_agg.AggCall,
    cut: ?ResultCut,
    in_place: bool,
    parts: []MergePart,
    cursor: *std.atomic.Value(usize),
    err: ?anyerror = null,

    /// Claim partitions until none remain. A thread that never starts leaves its share on the cursor, so a failed
    /// spawn cannot drop a partition.
    fn run(t: *MergeTask) void {
        while (t.err == null) {
            const i = t.cursor.fetchAdd(1, .monotonic);
            if (i >= t.parts.len) return;
            const p = &t.parts[i];
            const slots = &p.slots;
            hashMergeGroupRefs(t.gpa, t.lists, t.tables, p.refs, p.hashes, t.calls, t.cut, t.in_place, slots, &p.accs) catch |e| {
                t.err = e;
                return;
            };
        }
    }
};

/// Several worker tables: hash-merge `refs`. Large merges split by the key hash and run a partition per worker; the
/// partitions are disjoint, so none writes a group another writes. `hashes` are Wyhash with seed 0, matching the map.
fn mergeFoldedRefs(
    gpa: std.mem.Allocator,
    /// The merge's own maps, lists and scratch; `gpa` holds the accumulators' values.
    lists: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    refs: []const MergeGroupRef,
    calls: []const expr_agg.AggCall,
    n_workers: usize,
    cut: ?ResultCut,
    in_place: bool,
    slots: *std.ArrayList(MergedSlot),
    accs: *std.ArrayList(expr_agg.Accumulator),
) !void {
    std.debug.assert(!in_place or mergesInPlace(calls, cut));
    const ma = if (cut) |c| c.memory orelse lists else lists;
    const split_arena = ma;
    const nparts = mergePartitionCount(n_workers, refs.len, cut != null, mergeEntryBytes(calls.len));
    if (nparts == 1) return hashMergeGroupRefs(gpa, ma, tables, refs, null, calls, cut, in_place, slots, accs);

    // Partitions come from the middle of the hash: the map inside each takes its fingerprint from the top bits and
    // its slot from the low ones, and a partition that fixed either would collide more.
    const mask: u64 = nparts - 1;
    const hashes = try split_arena.alloc(u64, refs.len);
    defer split_arena.free(hashes);
    const ordered = try split_arena.alloc(MergeGroupRef, refs.len);
    defer split_arena.free(ordered);
    const ordered_hash = try split_arena.alloc(u64, refs.len);
    defer split_arena.free(ordered_hash);
    const starts = try split_arena.alloc(usize, nparts + 1);
    defer split_arena.free(starts);
    // Hashed and split into partitions by chunks of refs on every worker: each chunk counts its own partitions, the
    // counts give each chunk where it writes in each, and each chunk scatters its own refs. A partition holds its refs
    // in input order, as one thread splitting them all would leave them.
    const n_chunks = @max(1, @min(n_workers, refs.len / 65536));
    const chunk_counts = try split_arena.alloc(usize, n_chunks * nparts);
    defer split_arena.free(chunk_counts);
    @memset(chunk_counts, 0);
    const Split = struct {
        tables: []const expr_agg.GroupTable,
        refs: []const MergeGroupRef,
        hashes: []u64,
        ordered: []MergeGroupRef,
        ordered_hash: []u64,
        counts: []usize,
        nparts: usize,
        mask: u64,
        n_chunks: usize,
        cursor: *std.atomic.Value(usize),
        phase: enum { count, scatter },

        /// Claim chunks until none remain: one a failed spawn left unclaimed is taken by a thread that did start.
        fn run(t: *@This()) void {
            while (true) {
                const c = t.cursor.fetchAdd(1, .monotonic);
                if (c >= t.n_chunks) return;
                const lo = t.refs.len * c / t.n_chunks;
                const hi = t.refs.len * (c + 1) / t.n_chunks;
                const mine = t.counts[c * t.nparts ..][0..t.nparts];
                switch (t.phase) {
                    .count => for (t.refs[lo..hi], t.hashes[lo..hi]) |ref, *h| {
                        h.* = std.hash.Wyhash.hash(0, t.tables[ref.table].keyAt(ref.group));
                        mine[(h.* >> 32) & t.mask] += 1;
                    },
                    // `mine` now holds where this chunk writes next in each partition.
                    .scatter => for (t.refs[lo..hi], t.hashes[lo..hi]) |ref, h| {
                        const at = mine[(h >> 32) & t.mask];
                        t.ordered[at] = ref;
                        t.ordered_hash[at] = h;
                        mine[(h >> 32) & t.mask] = at + 1;
                    },
                }
            }
        }
    };
    var split_cursor = std.atomic.Value(usize).init(0);
    const splits = try split_arena.alloc(Split, n_chunks);
    defer split_arena.free(splits);
    const split_config: std.Thread.SpawnConfig = .{ .stack_size = WORKER_STACK_SIZE };
    for ([_]@TypeOf(splits[0].phase){ .count, .scatter }) |phase| {
        if (phase == .scatter) {
            // Partition p starts after every chunk's refs of the partitions before it; within p, chunk c after
            // chunks < c.
            var at: usize = 0;
            for (0..nparts) |p| {
                starts[p] = at;
                for (0..n_chunks) |c| {
                    const n = chunk_counts[c * nparts + p];
                    chunk_counts[c * nparts + p] = at;
                    at += n;
                }
            }
            starts[nparts] = at;
        }
        split_cursor.store(0, .monotonic);
        for (splits) |*t| t.* = .{
            .tables = tables,
            .refs = refs,
            .hashes = hashes,
            .ordered = ordered,
            .ordered_hash = ordered_hash,
            .counts = chunk_counts,
            .nparts = nparts,
            .mask = mask,
            .n_chunks = n_chunks,
            .cursor = &split_cursor,
            .phase = phase,
        };
        if (splits.len == 1 or !spawn_util.runTree(Split, splits, split_config, Split.run)) splits[0].run();
    }

    const parts = try split_arena.alloc(MergePart, nparts);
    defer split_arena.free(parts);
    for (parts, 0..) |*p, i| {
        p.* = .{
            .refs = ordered[starts[i]..starts[i + 1]],
            .hashes = ordered_hash[starts[i]..starts[i + 1]],
        };
    }
    defer for (parts) |*p| {
        freeOwnedAccumulatorStrings(gpa, p.accs.items);
        p.accs.deinit(ma);
        p.slots.deinit(ma);
    };

    const n_threads = @min(n_workers, nparts);
    const tasks = try split_arena.alloc(MergeTask, n_threads);
    defer split_arena.free(tasks);
    var cursor = std.atomic.Value(usize).init(0);
    for (tasks) |*task| task.* = .{
        .gpa = gpa,
        .lists = ma,
        .tables = tables,
        .calls = calls,
        .cut = cut,
        .in_place = in_place,
        .parts = parts,
        .cursor = &cursor,
    };
    const config: std.Thread.SpawnConfig = .{ .stack_size = WORKER_STACK_SIZE };
    if (!spawn_util.runTree(MergeTask, tasks, config, MergeTask.run)) MergeTask.run(&tasks[0]);
    for (tasks) |task| if (task.err) |e| return e;

    // Each partition is copied to its place in the combined lists on every worker: on one thread the copy of a large
    // merge costs more than sorting it.
    var nslots: usize = slots.items.len;
    var naccs: usize = accs.items.len;
    for (parts) |*p| {
        p.slot_at = nslots;
        p.acc_at = naccs;
        nslots += p.slots.items.len;
        naccs += p.accs.items.len;
    }
    try slots.ensureTotalCapacity(ma, nslots);
    try accs.ensureTotalCapacity(ma, naccs);
    const copies = try split_arena.alloc(ConcatTask, n_threads);
    defer split_arena.free(copies);
    // Nothing fails from here on, so the lists never hold an entry no partition wrote.
    slots.items.len = nslots;
    accs.items.len = naccs;
    cursor.store(0, .monotonic);
    for (copies) |*c| c.* = .{
        .parts = parts,
        .slots = slots.items,
        .accs = accs.items,
        .in_place = in_place,
        .cursor = &cursor,
    };
    if (!spawn_util.runTree(ConcatTask, copies, config, ConcatTask.run)) ConcatTask.run(&copies[0]);
    // The combined list now owns these winners.
    for (parts) |*p| p.accs.clearRetainingCapacity();
}

/// Copies the partitions it claims to their place in the combined lists, offsetting each slot's accumulators.
const ConcatTask = struct {
    parts: []const MergePart,
    slots: []MergedSlot,
    accs: []expr_agg.Accumulator,
    /// Slots name their source groups (`packRef`), not merged accumulators, so none is offset.
    in_place: bool,
    cursor: *std.atomic.Value(usize),

    fn run(t: *ConcatTask) void {
        while (true) {
            const i = t.cursor.fetchAdd(1, .monotonic);
            if (i >= t.parts.len) return;
            const p = &t.parts[i];
            for (p.slots.items, t.slots[p.slot_at..][0..p.slots.items.len]) |s, *d| d.* = .{
                .key = s.key,
                .first = s.first,
                .idx = if (t.in_place) s.idx else s.idx + p.acc_at,
            };
            @memcpy(t.accs[p.acc_at..][0..p.accs.items.len], p.accs.items);
        }
    }
};

/// The keys of the only groups a LIMIT with no ORDER BY can return: groups come out in first-appearance order, so it
/// keeps the `k` that appeared first. Each of those is among the `k` earliest groups of the table that first saw it,
/// since any group that table saw earlier appeared earlier overall, so the union of every table's `k` earliest holds
/// them all. Null when that would not shrink the merge.
/// Per-range first-H nominees contain the first H global keys: each winning key's earliest ref is among its
/// range's H earliest distinct keys. Taking minima over those nominees therefore gives exact original ordinals.
/// Only bounded nominees meet on the caller; source keys remain borrowed and the returned outer slice is owned.
fn firstCandidatesParallel(
    a: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    k: usize,
    requested: usize,
) !?[]const []const u8 {
    if (k == 0) return &.{};
    var groups: usize = 0;
    for (tables) |t| groups += t.groupCount();
    if (groups <= k *| 4) return null;
    const Item = struct { first: u64, key: []const u8 };
    const later = struct {
        fn cmp(_: void, x: Item, y: Item) std.math.Order {
            return std.math.order(y.first, x.first);
        }
    }.cmp;
    const Heap = std.PriorityQueue(Item, void, later);
    const Task = struct {
        allocator: std.mem.Allocator,
        tables: []const expr_agg.GroupTable,
        chunks: usize,
        k: usize,
        cursor: *std.atomic.Value(usize),
        heap: Heap = .empty,
        keys: KeyHashMapUnmanaged(u64) = .empty,
        err: ?anyerror = null,
        fn offer(queue: *Heap, allocator: std.mem.Allocator, limit: usize, item: Item) void {
            if (queue.count() == limit) {
                if (item.first >= queue.peek().?.first) return;
                _ = queue.pop();
            }
            queue.push(allocator, item) catch unreachable;
        }
        fn run(t: *@This()) void {
            while (t.err == null) {
                const job = t.cursor.fetchAdd(1, .monotonic);
                if (job >= t.tables.len * t.chunks) return;
                const table = &t.tables[job % t.tables.len];
                const width = std.math.divCeil(usize, table.groupCount(), t.chunks) catch unreachable;
                const lo = @min(table.groupCount(), (job / t.tables.len) * width);
                t.heap.clearRetainingCapacity();
                for (lo..@min(table.groupCount(), lo + width)) |gi| offer(
                    &t.heap,
                    t.allocator,
                    t.k,
                    .{ .first = table.first.items[gi], .key = table.keyAt(gi) },
                );
                for (t.heap.items) |item| {
                    const entry = t.keys.getOrPut(t.allocator, item.key) catch |e| {
                        t.err = e;
                        return;
                    };
                    entry.value_ptr.* = if (entry.found_existing) @min(entry.value_ptr.*, item.first) else item.first;
                }
            }
        }
    };
    const chunks = @max(1, @min(64, requested, groups / @max(1, k *| tables.len *| 4)));
    var storage: [64]Task = undefined;
    const tasks = storage[0..@max(1, @min(storage.len, requested, tables.len * chunks))];
    var cursor = std.atomic.Value(usize).init(0);
    for (tasks) |*t| t.* = .{ .allocator = a, .tables = tables, .chunks = chunks, .k = k, .cursor = &cursor };
    defer for (tasks) |*t| {
        t.keys.deinit(a);
        t.heap.deinit(a);
    };
    for (tasks) |*t| try t.heap.ensureTotalCapacity(a, k);
    if (tasks.len == 1 or !spawn_util.runTree(Task, tasks, .{ .stack_size = WORKER_STACK_SIZE }, Task.run))
        tasks[0].run();
    var nominees: KeyHashMapUnmanaged(u64) = .empty;
    defer nominees.deinit(a);
    for (tasks) |*t| {
        if (t.err) |e| return e;
        var it = t.keys.iterator();
        while (it.next()) |entry| {
            const to = try nominees.getOrPut(a, entry.key_ptr.*);
            to.value_ptr.* = if (to.found_existing) @min(to.value_ptr.*, entry.value_ptr.*) else entry.value_ptr.*;
        }
    }
    var heap: Heap = .empty;
    defer heap.deinit(a);
    try heap.ensureTotalCapacity(a, k);
    var it = nominees.iterator();
    while (it.next()) |entry|
        Task.offer(&heap, a, k, .{ .first = entry.value_ptr.*, .key = entry.key_ptr.* });
    const keys = try a.alloc([]const u8, heap.count());
    for (keys, heap.items) |*key, item| key.* = item.key;
    return keys;
}

fn firstCandidates(arena: std.mem.Allocator, tables: []const expr_agg.GroupTable, k: usize) error{OutOfMemory}!?[]const []const u8 {
    if (k == 0) return &.{};
    var groups: usize = 0;
    for (tables) |t| groups += t.groupCount();
    if (groups <= k *| 4) return null;
    const Item = struct { first: u64, g: u32 };
    const later = struct {
        fn cmp(_: void, a: Item, b: Item) std.math.Order {
            return std.math.order(b.first, a.first);
        }
    }.cmp;
    var heap: std.PriorityQueue(Item, void, later) = .empty;
    try heap.ensureTotalCapacity(arena, k);
    var kept: std.StringArrayHashMapUnmanaged(void) = .empty;
    for (tables) |*t| {
        heap.clearRetainingCapacity();
        for (t.first.items[0..t.groupCount()], 0..) |first, g| {
            if (heap.count() == k) {
                if (first >= heap.peek().?.first) continue;
                _ = heap.pop();
            }
            heap.push(arena, .{ .first = first, .g = @intCast(g) }) catch unreachable; // within the capacity reserved above
        }
        for (heap.items) |item| try kept.put(arena, t.keyAt(item.g), {});
    }
    return kept.keys();
}

/// The keys of the only groups that can reach the first `offset + limit` rows of an answer ordered by a COUNT,
/// descending, first; null when the order is not such a cut. Exact, after the threshold algorithm of distributed
/// top-k (Cao and Wang, 2004): every table nominates its own top groups, and the k-th largest exact total among the
/// nominees, `tau`, is a floor on the k-th largest total of all. A key whose total reaches `tau` across `m` tables has
/// at least `tau / m` in one of them, so the keys some table counts that high are all that can make the cut, ties at
/// the cut included; the rest are never merged or materialized. Typically a few hundred groups of millions survive.
fn premergeLargeDistinctSets(
    gpa: std.mem.Allocator,
    arena: std.mem.Allocator,
    tables: []expr_agg.GroupTable,
    calls: []const expr_agg.AggCall,
    n_workers: usize,
) !void {
    if (tables.len <= 1 or n_workers <= 1) return;

    for (calls, 0..) |call, ci| {
        if (call.func != .count_distinct) continue;

        var large_keys: KeyHashMapUnmanaged(void) = .empty;
        defer large_keys.deinit(gpa);

        const Task = struct {
            allocator: std.mem.Allocator,
            tables: []const expr_agg.GroupTable,
            stride: usize,
            call: usize,
            chunks: usize,
            cursor: *std.atomic.Value(usize),
            keys: KeyHashMapUnmanaged(void) = .empty,
            err: ?anyerror = null,
            fn run(t: *@This()) void {
                while (t.err == null) {
                    const job = t.cursor.fetchAdd(1, .monotonic);
                    if (job >= t.tables.len * t.chunks) return;
                    const table = &t.tables[job % t.tables.len];
                    const width = std.math.divCeil(usize, table.groupCount(), t.chunks) catch unreachable;
                    const lo = @min(table.groupCount(), (job / t.tables.len) * width);
                    for (lo..@min(table.groupCount(), lo + width)) |gi| {
                        const acc = table.readAcc(gi, t.call, t.stride);
                        if (acc == .distinct and acc.distinct.count() >= 16384)
                            t.keys.put(t.allocator, table.keyAt(gi), {}) catch |e| {
                                t.err = e;
                                return;
                            };
                    }
                }
            }
        };
        var storage: [64]Task = undefined;
        const tasks = storage[0..@max(1, @min(storage.len, n_workers))];
        var cursor = std.atomic.Value(usize).init(0);
        for (tasks) |*task| task.* = .{
            .allocator = gpa,
            .tables = tables,
            .stride = calls.len,
            .call = ci,
            .chunks = tasks.len,
            .cursor = &cursor,
        };
        defer for (tasks) |*task| task.keys.deinit(gpa);
        if (!spawn_util.runTree(Task, tasks, .{ .stack_size = WORKER_STACK_SIZE }, Task.run)) tasks[0].run();
        for (tasks) |*task| {
            if (task.err) |e| return e;
            var keys = task.keys.keyIterator();
            while (keys.next()) |key| try large_keys.put(gpa, key.*, {});
        }

        if (large_keys.count() == 0) continue;

        var it = large_keys.keyIterator();
        while (it.next()) |k_ptr| {
            const key = k_ptr.*;
            var sources: std.ArrayListUnmanaged(*const expr_agg.DistinctSet) = .empty;
            var is_u64 = true;

            for (tables) |*gt| {
                if (gt.findKey(key)) |gi| {
                    const acc = &gt.accumulators.items[gi * calls.len + ci];
                    if (acc.* != .distinct or acc.distinct.count() == 0) continue;
                    // A sibling that never spilled still holds its values inline; the union count needs them too.
                    const ds = try acc.distinct.ensureHeap(gpa);
                    try sources.append(arena, ds);
                    // Only sets of integers split by value here; a partition holding anything else keeps the whole set
                    // on the merge's own path.
                    const u64_only = struct {
                        fn of(d: *const expr_agg.DistinctSet) bool {
                            return d.val_set == .none or d.val_set == .inline_u64 or d.val_set == .u64;
                        }
                    }.of;
                    if (!u64_only(ds)) is_u64 = false;
                    if (ds.parts) |parts| for (parts) |*part| {
                        if (!u64_only(part)) is_u64 = false;
                    };
                }
            }

            if (!is_u64 or sources.items.len <= 1) continue;

            const total = try parallelDistinctCountU64(gpa, arena, sources.items, n_workers);

            var first = true;
            for (tables) |*gt| {
                if (gt.findKey(key)) |gi| {
                    const acc_ptr = &gt.accumulators.items[gi * calls.len + ci];
                    if (acc_ptr.* == .distinct) acc_ptr.distinct.deinit(gpa);
                    if (first) {
                        acc_ptr.* = .{ .count = total };
                        first = false;
                    } else {
                        acc_ptr.* = .{ .count = 0 };
                    }
                }
            }
        }
    }
}

fn topKCandidates(
    arena: std.mem.Allocator,
    tables: []const expr_agg.GroupTable,
    outputs: []const BoundOutputColumn,
    agg_calls: []const expr_agg.AggCall,
    order: expr_ast.ResultOrder,
) error{OutOfMemory}!?[]const []const u8 {
    const limit = order.limit orelse return null;
    if (order.keys.len == 0) return firstCandidates(arena, tables, std.math.cast(usize, order.offset +| limit) orelse return null);
    if (!order.keys[0].descending) return null;
    const a_idx = switch (outputs[order.keys[0].column].source) {
        .agg => |a| a,
        .key => return null,
    };
    if (agg_calls[a_idx].func != .count and agg_calls[a_idx].func != .count_distinct) return null;
    const is_distinct = agg_calls[a_idx].func == .count_distinct;
    const k = std.math.cast(usize, order.offset +| limit) orelse return null;
    if (k == 0) return &.{};
    var groups: usize = 0;
    for (tables) |t| groups += t.groupCount();
    if (groups <= k *| 4) return null;

    const stride = agg_calls.len;
    const Count = struct {
        c: u64,
        g: u32,
        fn of(t: *const expr_agg.GroupTable, g: usize, at: usize, n: usize) u64 {
            return accCount(t.readAcc(g, at, n));
        }
        fn byCount(_: void, a: @This(), b: @This()) std.math.Order {
            return std.math.order(a.c, b.c);
        }
    };

    // Nominees: each table's own k largest counts, by key.
    var nominees: KeyHashMapUnmanaged(void) = .empty;
    var heap: std.PriorityQueue(Count, void, Count.byCount) = .empty;
    try heap.ensureTotalCapacity(arena, k);
    for (tables) |*t| {
        heap.clearRetainingCapacity();
        for (0..t.groupCount()) |g| {
            const entry: Count = .{ .c = Count.of(t, g, a_idx, stride), .g = @intCast(g) };
            if (heap.count() == k) {
                if (entry.c <= heap.peek().?.c) continue;
                _ = heap.pop();
            }
            heap.push(arena, entry) catch unreachable; // within the capacity reserved above
        }
        for (heap.items) |entry| try nominees.put(arena, t.keyAt(entry.g), {});
    }
    if (nominees.count() < k) return null;

    // tau: a lower bound on the k-th largest total of all.
    // For plain count, sum_i c_i is exact. For count_distinct, max_i c_i is a lower bound on the true distinct count.
    const totals = try arena.alloc(u64, nominees.count());
    var it = nominees.keyIterator();
    for (totals) |*total| {
        const key = it.next().?.*;
        total.* = 0;
        for (tables) |*t| if (t.findKey(key)) |g| {
            const c = Count.of(t, g, a_idx, stride);
            if (is_distinct) {
                total.* = @max(total.*, c);
            } else {
                total.* +|= c;
            }
        };
    }
    std.mem.sortUnstable(u64, totals, {}, std.sort.desc(u64));
    const tau = totals[k - 1];
    if (tau == 0) return null;

    const m: u64 = tables.len;
    // When most groups pass (counts nearly all equal), the plain merge is cheaper than collecting them.
    var passing: usize = 0;
    for (tables) |*t| {
        for (0..t.groupCount()) |g| passing += @intFromBool(Count.of(t, g, a_idx, stride) *| m >= tau);
    }
    if (passing > groups / 4) return null;
    var kept: std.StringArrayHashMapUnmanaged(void) = .empty;
    try kept.ensureTotalCapacity(arena, passing);
    for (tables) |*t| {
        for (0..t.groupCount()) |g| {
            if (Count.of(t, g, a_idx, stride) *| m >= tau) kept.putAssumeCapacity(t.keyAt(g), {});
        }
    }
    // Candidate merging probes every table for the first position and each aggregate, plus ref construction.
    // Leave broad sets to the parallel count-cut merge before doing another serial DISTINCT pass.
    if ((kept.count() *| tables.len) *| (agg_calls.len +| 2) > groups / 2) return null;
    if (is_distinct) {
        // Second-stage filter for distinct: sum_i c_i is an exact upper bound on the union cardinality.
        // Any key where sum_i c_i < tau provably cannot reach tau.
        var i: usize = 0;
        while (i < kept.count()) {
            const key = kept.keys()[i];
            var sum_c: u64 = 0;
            for (tables) |*t| if (t.findKey(key)) |g| {
                sum_c +|= Count.of(t, g, a_idx, stride);
            };
            if (sum_c < tau) {
                _ = kept.swapRemove(key);
            } else {
                i += 1;
            }
        }
    }
    return kept.keys();
}

fn mergeDistinctPart(
    dst: *expr_agg.DistinctSet,
    src: *expr_agg.DistinctSet,
    allocator: std.mem.Allocator,
) !void {
    if (src.count() == 0) {
        src.deinit(allocator);
        src.* = .{ .shared = dst.shared };
        return;
    }
    if (dst.count() == 0) {
        dst.* = src.*;
        src.* = .{ .shared = dst.shared };
        return;
    }
    if (dst.count() < src.count()) {
        const tmp = dst.*;
        dst.* = src.*;
        src.* = tmp;
    }
    defer {
        src.deinit(allocator);
        src.* = .{ .shared = dst.shared };
    }
    src.releaseConsumedNumericSurplus();
    return dst.merge(src, allocator);
}

const DistinctMergeTask = struct {
    gpa: std.mem.Allocator,
    dst_parts: []expr_agg.DistinctSet,
    work_items: []const WorkItem,
    agg_idx: usize,
    cursor: *std.atomic.Value(usize),
    err: ?anyerror = null,

    fn run(t: *DistinctMergeTask) void {
        while (t.err == null) {
            const p = t.cursor.fetchAdd(1, .monotonic);
            if (p >= t.dst_parts.len) return;
            const dst_part = &t.dst_parts[p];
            for (t.work_items) |item| {
                if (t.agg_idx < item.agg_start or t.agg_idx >= item.agg_start + item.agg_len) continue;
                const src_acc = &item.accumulators[t.agg_idx - item.agg_start];
                if (src_acc.* == .distinct) if (src_acc.distinct.heap()) |ds| {
                    if (ds.parts) |src_parts| {
                        const src_part = &src_parts[p];
                        mergeDistinctPart(dst_part, src_part, t.gpa) catch |e| {
                            t.err = e;
                            return;
                        };
                    }
                };
            }
        }
    }
};

/// Move each partition's groups into `slots` / `accs`. Keys stay borrowed from the partition tables.
fn fillFromPartitions(
    gpa: std.mem.Allocator,
    lists: std.mem.Allocator,
    arena: std.mem.Allocator,
    parts: []partagg.Part,
    calls: []const expr_agg.AggCall,
    outputs: []const BoundOutputColumn,
    order: expr_ast.ResultOrder,
    unordered: bool,
    result_cut: ?ResultCut,
    n_workers: usize,
    slots: *std.ArrayList(MergedSlot),
    accs: *std.ArrayList(expr_agg.Accumulator),
) !void {
    _ = gpa;
    _ = arena;
    const ma = if (result_cut) |c| c.memory orelse lists else lists;
    const Piece = struct { ids: ?[]u32 = null, n: usize = 0, offset: usize = 0 };
    const pieces = try ma.alloc(Piece, parts.len);
    @memset(pieces, .{});
    defer {
        for (pieces) |p| if (p.ids) |ids| ma.free(ids);
        ma.free(pieces);
    }
    const Task = struct {
        ma: std.mem.Allocator,
        parts: []partagg.Part,
        pieces: []Piece,
        calls: []const expr_agg.AggCall,
        outputs: []const BoundOutputColumn,
        order: expr_ast.ResultOrder,
        unordered: bool,
        slots: []MergedSlot = &.{},
        accs: []expr_agg.Accumulator = &.{},
        copy: bool = false,
        cursor: *std.atomic.Value(usize),
        err: ?anyerror = null,
        fn run(t: *@This()) void {
            while (t.err == null) {
                const p = t.cursor.fetchAdd(1, .monotonic);
                if (p >= t.parts.len) return;
                const gt = &t.parts[p].table;
                const piece = &t.pieces[p];
                if (!t.copy) {
                    piece.ids = resultLimitGroups(t.ma, gt, t.outputs, t.calls, t.order, t.unordered, t.ma) catch |e| {
                        t.err = e;
                        return;
                    };
                    piece.n = if (piece.ids) |ids| ids.len else gt.groupCount();
                } else for (0..piece.n) |i| {
                    const g = if (piece.ids) |ids| ids[i] else i;
                    var scratch: [16]expr_agg.Accumulator = undefined;
                    const src = gt.readGroup(g, t.calls.len, &scratch);
                    const at = piece.offset + i;
                    @memcpy(t.accs[at * t.calls.len ..][0..t.calls.len], src);
                    for (src) |*a| detachOwned(a);
                    t.slots[at] = .{ .key = gt.keyAt(g), .first = gt.first.items[g], .idx = at * t.calls.len };
                }
            }
        }
    };
    var storage: [64]Task = undefined;
    const tasks = storage[0..@max(1, @min(n_workers, parts.len, storage.len))];
    var cursor = std.atomic.Value(usize).init(0);
    for (tasks) |*t| t.* = .{
        .ma = ma,
        .parts = parts,
        .pieces = pieces,
        .calls = calls,
        .outputs = outputs,
        .order = order,
        .unordered = unordered,
        .cursor = &cursor,
    };
    const config: std.Thread.SpawnConfig = .{ .stack_size = WORKER_STACK_SIZE };
    if (tasks.len == 1 or !spawn_util.runTree(Task, tasks, config, Task.run)) tasks[0].run();
    for (tasks) |t| if (t.err) |e| return e;
    var total: usize = 0;
    for (pieces) |*p| {
        p.offset = total;
        total += p.n;
    }
    try slots.ensureTotalCapacity(ma, total);
    try accs.ensureTotalCapacity(ma, total * calls.len);
    // The copy cannot fail. From this point these lists own every moved winner, even after a failed thread spawn.
    slots.items.len = total;
    accs.items.len = total * calls.len;
    cursor.store(0, .monotonic);
    for (tasks) |*t| {
        t.copy = true;
        t.slots = slots.items;
        t.accs = accs.items;
    }
    if (tasks.len == 1 or !spawn_util.runTree(Task, tasks, config, Task.run)) tasks[0].run();
}

// ============================================================
// Compile-time API check. Behavioral coverage is via the CLI
// regression suite + lambda integration tests.
// ============================================================
test "scan: API is well-typed" {
    _ = runMultiAggregate;
    _ = materializeOne;
}

// ============================================================ Partial thread-spawn failure.
//
// `Thread.spawn` can fail partway through a loop (EAGAIN); leftover work must still run and started threads must still
// be joined. Driven through the seam in spawn.zig, since real spawn failure is not reproducible.
// ============================================================

const testing = std.testing;
const test_fixtures = @import("parquet/test_fixtures.zig");
/// The padding columns exist only to push fetch volume past the 2 MiB-per-worker threshold, so workers really spawn.
const SPAWN_FIXTURE_AGG =
    "count(*) AS n" ++
    ", sum(pad0) AS s0" ++ ", sum(pad1) AS s1" ++ ", sum(pad2) AS s2" ++
    ", sum(pad3) AS s3" ++ ", sum(pad4) AS s4" ++ ", sum(pad5) AS s5" ++
    ", sum(pad6) AS s6" ++ ", sum(pad7) AS s7" ++ ", sum(pad8) AS s8" ++
    ", sum(pad9) AS s9" ++ ", sum(pad10) AS s10";
test "runMultiAggregate: injected spawn failures don't change the answer" {
    // The scan workers, unlike the footer parsers, are the loop whose old `try spawn` returned while earlier threads
    // still read the arena the caller frees. Sizing is by decode volume, so a small fixture would test nothing.
    const fixture = "data/bench_types.parquet";
    const bytes = metadata.readFileSlice(fixture, testing.allocator) catch |err| {
        if (err == error.FileNotFound) {
            std.debug.print("skipping: {s} not present\n", .{fixture});
            return error.SkipZigTest;
        }
        return err;
    };
    defer testing.allocator.free(bytes);

    const parallelism = 4;
    const inputs = [_]Input{.{ .name = fixture, .bytes = bytes }};

    const Answer = struct { sum: i128, rows: i64 };
    var baseline: ?Answer = null;
    for ([_]?usize{ null, 0, 1, parallelism - 1 }) |fail_after| {
        var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena_state.deinit();

        if (fail_after) |n| spawn_util.injectFailureAfter(n);
        defer spawn_util.resetFailure();

        const res = try runMultiAggregate(testing.allocator, arena_state.allocator(), .{
            .inputs = &inputs,
            .aggregate = "sum(id) AS s",
            .parallelism = parallelism,
            // Force a real decode; otherwise the sum is answered from statistics and no worker ever runs.
            .scan_all = true,
        });
        defer freeResult(res);

        try testing.expectEqual(@as(usize, 1), res.output.aggs.len);
        const got: Answer = .{ .sum = res.output.aggs[0].value.i, .rows = res.rows_in };
        // Work dropped by a failed spawn and never picked up inline would show as a short row count.
        try testing.expect(got.rows > 0);

        if (baseline) |b| {
            try testing.expectEqual(b.sum, got.sum);
            try testing.expectEqual(b.rows, got.rows);
            // Prove the run took the failure path; one worker means nothing was tested.
            if (spawn_util.failuresInjected() == 0) {
                std.debug.print(
                    "spawn injection never fired (fail_after={?d}) — test is vacuous\n",
                    .{fail_after},
                );
                return error.TestUnexpectedResult;
            }
        } else {
            baseline = got;
        }
    }
}

test "partagg: same GROUP BY answer as the per-worker tables at every -j" {
    const bytes = (try loadFixture(full_match_fixture)) orelse return error.SkipZigTest;
    defer testing.allocator.free(bytes);
    const inputs = [_]Input{.{ .name = full_match_fixture, .bytes = bytes }};
    const Q = struct {
        aggregate: []const u8,
        group_by: []const u8,
        /// False: the query must stay on the per-worker tables (float merge, or count distinct).
        part: bool,
        cap: usize = 0,
        probe: u64 = 0,
    };
    const queries = [_]Q{
        .{ .aggregate = "count(*) AS c, sum(ts) AS sm, min(ts) AS mn, max(ts) AS mx, avg(ts) AS a", .group_by = "b", .part = true },
        .{ .aggregate = "count(*) AS c, min(s) AS mn, max(s) AS mx", .group_by = "b", .part = true, .cap = 40, .probe = 80 },
        .{ .aggregate = "count(*) AS c, sum(ts) AS sm", .group_by = "s", .part = true, .cap = 30, .probe = 50 },
        .{ .aggregate = "count(*) AS c, sum(ts) AS sm", .group_by = "n", .part = true, .cap = 40, .probe = 80 },
        .{ .aggregate = "sum(x) AS sx", .group_by = "b", .part = false },
        .{ .aggregate = "count(DISTINCT ts) AS d", .group_by = "b", .part = false },
    };
    for (queries) |q| for ([_]usize{ 1, 3, 8 }) |j| {
        var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena_state.deinit();
        const base: MultiAggArgs = .{
            .inputs = &inputs,
            .aggregate = q.aggregate,
            .group_by = q.group_by,
            .parallelism = j,
            .min_bytes_per_worker = 1,
            .scan_all = true,
        };
        const want = try runMultiAggregate(testing.allocator, arena_state.allocator(), base);
        defer freeResult(want);
        var args = base;
        args.partagg = true;
        args.part_cap = q.cap;
        args.part_probe = q.probe;
        const got = try runMultiAggregate(testing.allocator, arena_state.allocator(), args);
        defer freeResult(got);
        try testing.expectEqual(q.part, got.part_agg);
        expectSameAnswer(want, got) catch |err| {
            std.debug.print("partagg -j{d} {s} GROUP BY {s}\n", .{ j, q.aggregate, q.group_by });
            return err;
        };
    };
}

