        .{ .agg = "count(*) AS n, sum(d9o) AS a, min(d18o) AS b, max(d38o) AS c, count(d38o) AS cc", .compacts = false },
        .{ .agg = "count(*) AS n, min(ts) AS t, max(tso) AS u, count(tso) AS cu", .compacts = false },
