        var args: MultiAggArgs = .{
            .inputs = &inputs,
            .group_by = "k",
            .aggregate = "count(*) AS c",
            .parallelism = 1,
            .decode_limit = limit,
            .result_order = .{ .limit = 1, .offset = 8 },
        };
        for ([_]?SketchTopK{ null, .{} }) |sketch| {
            args.sketch_topk = sketch;
