    for (&k, &text, &value, &defs, 0..) |*ki, *t, *v, *d, i| {
        ki.* = @intCast(i % 17);
        t.* = if (i % 2 == 0) "first" else "second";
        v.* = @as(i64, @intCast(i % 19)) - 9;
        d.* = @intFromBool(i % 17 != 0);
    }
    const columns = [_]expr_agg.OutputCol{
