        .{ .name = "v", .col = .{ .i64 = .{ .values = &value, .def_levels = &defs, .max_def = 1 } }, .parquet_type = .INT64, .nullable = true },
    };
    var sink: @import("writer/streaming.zig").MemorySink = .{ .arena = a };
